insert into books (volume_id, book_no, title_ml, title_ar, start_page) values (4, 20, 'ഗ്രന്ഥകർത്താവിനെക്കുറിച്ച്', null, 1010) on conflict (volume_id, book_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, books.title_ar), start_page=excluded.start_page;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا تَكَلَّمَ اللهُ بِالْوَحْيِ، سَمِعَ أَهْلُ السَّمَاءِ لِلسَّمَاءِ صَلْصَلَةً كَجَرِّ السِّلْسِلَةِ عَلَى الصَّفَا، فَيُصْعَقُونَ، فَلَا يَزَالُونَ كَذَلِكَ حَتَّى يَأْتِيَهُمْ جِبْرِيلُ، حَتَّى إِذَا جَاءَهُمْ جِبْرِيلُ فُزِّعَ عَنْ قُلُوبِهِمْ، قَالَ: فَيَقُولُونَ: يَا جِبْرِيلُ، مَاذَا قَالَ رَبُّكَ؟ فَيَقُولُ: الْحَقَّ. فَيَقُولُونَ: الْحَقَّ، الْحَقَّ". (خ,د,ت,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു വഹ്യ് കൊണ്ട് സംസാരിക്കുമ്പോൾ ആകാശവാസികളെല്ലാം, ആകാശത്ത്, പാറയുടെ മുകളിലൂടെ ചങ്ങല വലിക്കുമ്പോഴുണ്ടാകുന്ന ശബ്ദം പോലെയുള്ള ശബ്ദം കേൾക്കും. അപ്പോഴവർക്ക് ബോധക്ഷയം സംഭവിക്കും. ജിബ്രീൽ(അ) അവരുടെ അടുത്ത് വരുന്നതുവരെ അവർ ആ അവസ്ഥയിൽ തന്നെയായിരിക്കും. അങ്ങനെ ജിബ്രീൽ(അ) വന്നാൽ അവർക്ക് ബോധം തിരിച്ചുകിട്ടും. അപ്പോഴവർ ചോദിക്കും: ഓ ജിബ്രീൽ, താങ്കളുടെ രക്ഷിതാവെന്താണ് പറഞ്ഞത്? അന്നേരം ജിബ്രീൽ(അ) പറയും: സത്യമാണ് പറഞ്ഞത്. അപ്പോൾ അവർ പറയും: സത്യം തന്നെയാണ്, സത്യം തന്നെയാണ്." (ബു,ദ,തു,ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['خ','د','ت','جه']::text[], array['ബു','ദ','തു','ജ']::text[], null, null, 531, 531, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "مَا مِنَ الْأَنْبِيَاءِ نَبِيٌّ إِلَّا أُعْطِيَ مَا مِثْلَهُ آمَنَ عَلَيْهِ الْبَشَرُ، وَإِنَّمَا كَانَ الَّذِي أُوتِيتُ وَحْيًا أَوْحَاهُ اللَّهُ إِلَيَّ، فَأَرْجُو أَنْ أَكُونَ أَكْثَرَهُمْ تَابِعًا يَوْمَ الْقِيَامَةِ". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ജനങ്ങൾ വിശ്വസിക്കാൻ പര്യാപ്തമാകുമാറുള്ള ഒരമാനുഷിക ദൃഷ്ടാന്തം നൽകപ്പെടാത്ത ഒരു പ്രവാചകനുമില്ല. എനിക്ക് നൽകപ്പെട്ടിരിക്കുന്നത് അല്ലാഹു എനിക്കേകിയ അവന്റെ വഹ്യ് (ദിവ്യബോധനം) ആണ്. അതിനാൽത്തന്നെ അവരിൽവെച്ച് ഏറ്റവും കൂടുതൽ അനുയായികളുള്ളയാൾ ഞാനാകണമെന്ന് ഞാനാശിക്കുന്നു." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 531, 531, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ اللَّهَ تَعَالَى تَابَعَ عَلَى رَسُولِه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْوَحْيَ قَبْلَ وَفَاتِه، حَتَّى تَوَفَّاهُ أَكْثَرَ مَا كَانَ الْوَحْيُ، ثُمَّ تُوُفِّيَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ بَعْدُ. (خ)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) വഫാതാകുന്നതിന് മുമ്പുതൊട്ട് വഫാതാകുന്നത് വരെ അല്ലാഹു വളരെ കൂടുതലായി വഹ്യിനെ നിരന്തരം അവതരിപ്പിച്ചുകൊണ്ടിരുന്നു. ശേഷം റസൂൽ(സ) വഫാതായി. (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 531, 531, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ الْحَارِثَ بْنَ هِشَامٍ سَأَلَ رَسُولَ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: كَيْفَ يَأْتِيكَ الْوَحْيُ؟ فَقَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "أَحْيَانًا يَأْتِينِي فِي مِثْلِ صَلْصَلَة الْجَرَسِ، وَهُوَ أَشَدُّهُ عَلَيَّ، فَيَفْصِمُ عَنِّي وَقَدْ وَعَيْتُ مَا قَالَ، وَأَحْيَانًا يَتَمَثَّلُ لِيَ الْمَلَكُ رَجُلًا، فَيُكَلِّمُنِي فَأَعِي مَا يَقُولُ". قَالَتْ عَائِشَةُ: وَلَقَدْ رَأَيْتُهُ يَنْزِلُ عَلَيْه فِي الْيَوْمِ الشَّدِيدِ الْبَرْدِ، فَيَفْصِمُ عَنْهُ وَإِنَّ جَبِينَهُ لَيَتَفَصَّدُ عَرَقًا. (ن)', 'ആഇശ(റ): ഹാരിസുബ്നു ഹിശാം(റ) നബി(സ)യോട് ചോദിച്ചു: അങ്ങേക്കെങ്ങനെയാണ് ദിവ്യബോധനം അവതരിക്കാറ്? അപ്പോൾ നബി(സ) പറഞ്ഞു: "ചില സമയങ്ങളിൽ മണിക്കിലുക്കം പോലെയായിരിക്കും. അതാണെനിക്കേറ്റവും പ്രയാസമേറിയത്. പിന്നെയത് എന്നിൽ നിന്നും വേർപ്പെട്ടുപോകും. പറഞ്ഞതെല്ലാം ഞാൻ മനഃപാഠമാക്കിയിട്ടുണ്ടാകും. ചില സമയങ്ങളിൽ മലക്ക് ഒരു പുരുഷന്റെ രൂപത്തിൽ വരും. എന്നോട് സംസാരിക്കും. പറഞ്ഞതെല്ലാം ഞാൻ മനഃപാഠമാക്കുകയും ചെയ്യും." ആഇശ(റ) പറയുന്നു: ശക്തിയായ തണുപ്പുള്ള ദിനങ്ങളിൽ അവിടുത്തേക്ക് വഹ്യ് അവതരിക്കുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. വേർപിരിഞ്ഞു പോകുമ്പോഴേക്ക് അവിടുത്തെ നെറ്റിയിൽ വിയർപ്പ് പൊടിഞ്ഞിട്ടുണ്ടാകും. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 531, 532, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، فِي قَوْلِهِ عَزَّ وَجَلَّ: {لَا تُحَرِّكْ بِهِ لِسَانَكَ لِتَعْجَلَ بِهِ. إِنَّ عَلَيْنَا جَمْعَهُ وَقُرْآنَهُ} [القيامة: ١٦،١٧] قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُعَالِجُ مِنَ التَّنْزِيلِ شِدَّةً، وَكَانَ يُحَرِّكُ شَفَتَيْهِ، قَالَ اللهُ عَزَّ وَجَلَّ: {لَا تُحَرِّكْ بِهِ لِسَانَكَ لِتَعْجَلَ بِهِ. إِنَّ عَلَيْنَا جَمْعَهُ وَقُرْآنَهُ} قَالَ: جَمْعُهُ فِي صَدْرِكَ ثُمَّ تَقْرَؤُهُ {فَإِذَا قَرَأْنَاهُ فَاتَّبِعْ قُرْآنَهُ} [القيامة: ١٨] قَالَ: فَاسْتَمِعْ لَهُ وَأَنْصِتْ، فَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا أَتَاهُ جِبْرِيلُ اسْتَمَعَ، فَإِذَا انْطَلَقَ قَرَأَهُ كَمَا أَقْرَأَهُ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ''ധൃതികാണിച്ച് അതിലേക്ക് (നാമവതരിപ്പിക്കുന്ന ഖുർആനിലേക്ക്) അങ്ങ് നാക്ക് ചലിപ്പിക്കരുത്, അതിന്റെ സമാഹരണവും ഓതിക്കേൾപ്പിക്കലും നമ്മുടെ ബാധ്യതയാണ്'' (ഖിയാമ: 16, 17) എന്ന സൂക്തങ്ങളെക്കുറിച്ച് പറയുന്നു: വഹ്യ് അവതരിക്കുമ്പോൾ നബി(സ)ക്ക് കാഠിന്യം അനുഭവപ്പെടാറുണ്ടായിരുന്നു. നബി(സ) രണ്ട് ചുണ്ടും ചലിപ്പിക്കുമായിരുന്നു. അല്ലാഹു പറഞ്ഞു: ''അതിലേക്ക് ധൃതികാണിച്ച് അങ്ങ് നാക്ക് ചലിപ്പിക്കരുത്. അതിന്റെ സമാഹരണവും അത് ഓതിക്കേൾപ്പിക്കലും നമ്മുടെ ബാധ്യതയാണ്.'' ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നു: അങ്ങയുടെ ഹൃദയത്തിൽ സമാഹരിക്കലും ശേഷം അങ്ങത് ഓതലും. ''അങ്ങേക്ക് നാം ഓതിക്കേൾപ്പിച്ചാൽ, ആ ഓത്ത് നിങ്ങൾ പിന്തുടരുക.'' ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നു: അങ്ങ് മൗനിയായി അത് ശ്രദ്ധിച്ചുകേൾക്കുക. അങ്ങനെ ജിബ്രീൽ(അ) വരുമ്പോഴൊക്കെ നബി(സ) ശ്രദ്ധിച്ചുകേൾക്കും. ജിബ്രീൽ(അ) പോയിക്കഴിഞ്ഞാൽ ഓതിക്കൊടുത്തത് പോലെ നബി(സ) ഓതും. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], 'القيامة: ١٨', null, 532, 532, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ عُثْمَانَ بْنِ عَفَّانَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "خَيْرُكُمْ – وَفِي رِوَايَةٍ: أَفْضَلُكُمْ – مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ". (خ,د,ت,جه)', 'ഉസ്മാനുബ്നു അഫാൻ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിലേറ്റവും ഉത്തമർ - മറ്റൊരു നിവേദനത്തിൽ: നിങ്ങളിലേറ്റവും ശ്രേഷ്ഠർ - ഖുർആൻ പഠിക്കുകയും പഠിപ്പിക്കുകയും ചെയ്തവരാണ്." (ബു,ദ,തു,ജ)', 'عُثْمَانَ بْنِ عَفَّانَ', 'ഉസ്മാനുബ്നു അഫാൻ(റ)', null, null, array['خ','د','ت','جه']::text[], array['ബു','ദ','തു','ജ']::text[], null, null, 532, 532, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=11 and h.hadith_no=6), 1, 'وَفِي رِوَايَةٍ: أَفْضَلُكُمْ – مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ". (خ,د,ت,جه)', 'മറ്റൊരു നിവേദനത്തിൽ: നിങ്ങളിലേറ്റവും ശ്രേഷ്ഠർ - ഖുർആൻ പഠിക്കുകയും പഠിപ്പിക്കുകയും ചെയ്തവരാണ്." (ബു,ദ,തു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ أَنَسِ بْنِ مَالك رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "إِنَّ لِلَّه أَهْلِينَ مِنَ النَّاسِ". قَالُوا: يَا رَسُولَ اللَّه، مَنْ هُمْ؟ قَالَ: "هُمْ أَهْلُ الْقُرْآن، أَهْلُ اللَّه وَخَاصَّتُهُ". (جه)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം ജനങ്ങളിൽ അല്ലാഹുവിന്റെ ചില കൂട്ടരുണ്ട്." അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അവരാരാണ്? റസൂൽ(സ) പറഞ്ഞു: "അവർ ഖുർആന്റെ ആളുകളാണ്. അല്ലാഹുവിന്റെ ആളുകളും അവന്റെ സ്വന്തക്കാരുമാണവർ." (ജ)', 'أَنَسِ بْنِ مَالك', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 532, 532, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِب رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "مَنْ قَرَأَ الْقُرْآنَ وَحَفِظَهُ أَدْخَلَهُ اللَّهُ الْجَنَّةَ وَشَفَّعَهُ فِي عَشَرَةٍ مِنْ أَهْلِ بَيْتِه، كُلُّهُمْ قَدِ اسْتَوْجَبُوا النَّارَ". (ت,جه)', 'അലി(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും ഖുർആൻ ഓതുകയും അത് മനഃപാഠമാക്കുകയും ചെയ്താൽ അല്ലാഹു അവനെ സ്വർഗത്തിൽ പ്രവേശിപ്പിക്കും. തന്റെ കൂട്ടുകുടുംബത്തിൽ നിന്ന് നരകാവകാശികളായ പത്തുപേരെ ശുപാർശ ചെയ്യാനുള്ള അവകാശം അവന് നൽകപ്പെടുകയും ചെയ്യും." (തു,ജ)', 'عَلِيِّ بْنِ أَبِي طَالِب', 'അലി(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 532, 533, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "تَعَلَّمُوا الْقُرْآنَ وَاقْرَءُوهُ وَارْقُدُوا، فَإِنَّ مَثَلَ الْقُرْآن وَمَنْ تَعَلَّمَهُ فَقَامَ بِه: كَمَثَلِ جِرَابٍ مَحْشُوٌّ مِسْكًا، يَفُوحُ رِيحُهُ كُلَّ مَكَانٍ. وَمَثَلُ مَنْ تَعَلَّمَهُ فَرَقَدَ وَهُوَ فِي جَوْفِه: كَمَثَلِ جِرَابٍ أُوكِيَ عَلَى مِسْك". (ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ഖുർആൻ പഠിക്കുകയും അതോതി ഉറങ്ങുകയും ചെയ്യുക. കാരണം ഖുർആന്റെയും അത് പഠിച്ച് അനുസരിച്ച് പാലിക്കുന്നവന്റെയും ഉപമ കസ്തൂരി നിറഞ്ഞ ഉറ പോലെയാണ്. അതിന്റെ സുഗന്ധം എല്ലാ സ്ഥലത്തും അടിച്ചുവീശും. അത് പഠിച്ച് ഉള്ളിൽ വെച്ചുറങ്ങിയവന്റെ ഉപമ കസ്തൂരി നിറച്ച് മുടിവെക്കപ്പെട്ട ചാടി പോലെയാണ്." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 533, 533, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ عَامِرِ بْنِ وَاثِلَةَ أَبِي الطُّفَيْلِ رَضِيَ اللَّهُ عَنْهُ: أَنَّ نَافِعَ بْنَ عَبْد الْحَارِث لَقِيَ عُمَرَ بْنَ الْخَطَّاب رَضِيَ اللَّهُ عَنْهُ بِعُسْفَانَ، وَكَانَ عُمَرُ اسْتَعْمَلَهُ عَلَى مَكَّةَ، فَقَالَ عُمَرُ: مَنِ اسْتَخْلَفْتَ عَلَى أَهْلِ الْوَادِي؟ قَالَ: اسْتَخْلَفْتُ عَلَيْهِمُ ابْنَ أَبْزَى. قَالَ: وَمَنِ ابْنُ أَبْزَى؟ قَالَ: رَجُلٌ مِنْ مَوَالِينَا. قَالَ عُمَرُ: فَاسْتَخْلَفْتَ عَلَيْهِمْ مَوْلًى؟ قَالَ: إِنَّهُ قَارِئٌ لِكِتَاب اللَّه تَعَالَى، عَالِمٌ بِالْفَرَائِضِ، قَاضٍ. قَالَ عُمَرُ: أَمَا إِنَّ نَبِيَّكُمْ صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ قَالَ: "إِنَّ اللَّهَ يَرْفَعُ بِهَذَا الْكِتَاب أَقْوَامًا وَيَضَعُ بِه آخَرِينَ". (م,جه)', 'ആമിറുബ്നു വാസിലതു അബുത്ത്വുഫൈൽ(റ): ഉസ്ഫാൻ എന്ന ദേശത്തുവെച്ച് നാഫിഉബ്നു അബ്ദിൽ ഹാരിസ്(റ) ഉമറുബ്നുൽ ഖത്താബ്(റ)വിനെ കണ്ടുമുട്ടി. ഉമർ(റ) അദ്ദേഹത്തെ മക്കയുടെ ഗവർണറാക്കിയിരുന്നു. ഉമർ(റ) ചോദിച്ചു: മക്കക്കാർക്ക് ആരെയാണ് നീ പ്രതിനിധിയാക്കിയത്? നാഫിഅ്(റ) പറഞ്ഞു: അവർക്ക് ഇബ്നുഅബ്സയെയാണ് ഞാനേൽപിച്ചത്. ഉമർ(റ) ചോദിച്ചു: ആരാണീ ഇബ്നുഅബ്സ? നാഫിഅ്(റ)പറഞ്ഞു: നമ്മുടെ അടിമകളിൽപ്പെട്ട ഒരാളാണ്. ഉമർ(റ) ചോദിച്ചു: ഒരു അടിമയെയാണോ നീ ഏൽപിച്ചത്? നാഫിഅ്(റ) പറഞ്ഞു: അദ്ദേഹം ഖുർആൻ കൂടുതൽ ഓതുന്നവനാണ്, അനന്തരാവകാശ നിയമങ്ങളറിയുന്നവനാണ്, വിധികർത്താവുമാണ്. ഉമർ(റ) പറഞ്ഞു: നിശ്ചയം നിങ്ങളുടെ പ്രവാചകൻ പറഞ്ഞിട്ടുണ്ട്: "അല്ലാഹു ഈ ഗ്രന്ഥം കൊണ്ട് ചിലരെ ഉയർത്തുകയും മറ്റുചിലരെ താഴ്ത്തുകയും ചെയ്യും." (മു,ജ)', 'عَامِرِ بْنِ وَاثِلَةَ أَبِي الطُّفَيْلِ', 'ആമിറുബ്നു വാസിലതു അബുത്ത്വുഫൈൽ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 533, 533, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ لِي رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "يَا أَبَا ذَرٍّ، لَأَنْ تَغْدُوَ فَتَعَلَّمَ آيَةً مِنْ كِتَاب اللَّه خَيْرٌ لَكَ مِنْ أَنْ تُصَلِّيَ مِائَةَ رَكْعَة. وَلَأَنْ تَغْدُوَ فَتَعَلَّمَ بَابًا مِنَ الْعِلْمِ، عُمِلَ بِه أَوْ لَمْ يُعْمَلْ، خَيْرٌ لَكَ مِنْ أَنْ تُصَلِّيَ أَلْفَ رَكْعَة". (جه)', 'അബൂദർറ്(റ): എന്നോട് റസൂൽ(സ) പറഞ്ഞു: "അബൂദർറേ, നീ പോയി അല്ലാഹുവിന്റെ കിത്താബിലെ ഒരു സൂക്തം പഠിക്കുന്നതാണ് നൂറ് റക്അത്ത് നിസ്കരിക്കുന്നതിനേക്കാൾ നിനക്കുത്തമം. നീ പോയി അൽപം അറിവ് നുകരലാണ്, ആ അറിവനുസരിച്ച് പ്രവർത്തിച്ചാലും ഇല്ലെങ്കിലും, ആയിരം റക്അത്ത് നിസ്കരിക്കുന്നതിനേക്കാൾ നിനക്കുത്തമം." (ജ)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 533, 533, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ مُعَاذٍ الْجُهَنِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ قَالَ: "مَنْ قَرَأَ الْقُرْآنَ وَعَمِلَ بِمَا فِيه، أُلْبِسَ وَالِدَاهُ تَاجًا يَوْمَ الْقِيَامَة، ضَوْءُهُ أَحْسَنُ مِنْ ضَوْءِ الشَّمْسِ فِي بُيُوتِ الدُّنْيَا لَوْ كَانَتْ فِيكُمْ، فَمَا ظَنُّكُمْ بِالَّذِي عَمِلَ بِهَذَا". (د)', 'മുആദുൽ ജുഹനി(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും ഖുർആൻ ഓതി അതനുസരിച്ച് പ്രവർത്തിച്ചാൽ അവന്റെ മാതാപിതാക്കൾ അന്ത്യനാളിൽ കിരീടമണിയിക്കപ്പെടും. നിങ്ങൾ ഈ ലോകത്തായിരിക്കുമ്പോൾ നിങ്ങൾക്കിടയിൽ സൂര്യനുണ്ടാകുന്ന ശോഭയേക്കാൾ ഭംഗിയായിരിക്കും ആ കിരീടത്തിനുണ്ടാകുന്ന ശോഭ. അപ്പോൾ ഇതനുസരിച്ച് പ്രവർത്തിക്കുന്നവനെക്കുറിച്ച് നിങ്ങൾ വിചാരിക്കുന്നതെന്താണ്." (ദ)', 'مُعَاذٍ الْجُهَنِيِّ', 'മുആദുൽ ജുഹനി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 533, 534, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ قَالَ: "مَا اجْتَمَعَ قَوْمٌ فِي بَيْتٍ مِنْ بُيُوت اللَّه تَعَالَى، يَتْلُونَ كِتَابَ اللَّه وَيَتَدَارَسُونَهُ بَيْنَهُمْ، إِلَّا نَزَلَتْ عَلَيْهِمُ السَّكِينَةُ، وَغَشِيَتْهُمُ الرَّحْمَةُ، وَحَفَّتْهُمُ الْمَلَائِكَةُ، وَذَكَرَهُمُ اللَّهُ فِيمَنْ عِنْدَهُ". (م,د,ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ ഭവനങ്ങളിൽ ഏതെങ്കിലുമൊരു ഭവനത്തിൽ ഒരുമിച്ചുകൂടി ഖുർആൻ പാരായണം ചെയ്യുകയും അതേക്കുറിച്ച് പരസ്പരം ചർച്ച ചെയ്യുകയും ചെയ്യുന്നവരിൽ തീർച്ചയായും ശാന്തി അവതരിക്കും. അനുഗ്രഹങ്ങൾ അവരെ പൊതിയുകയും മാലാഖമാർ വാരിപ്പുണരുകയും അല്ലാഹു അവരെക്കുറിച്ച് തന്റെ അടുത്തുള്ളവരോട് സ്മരിക്കുകയും ചെയ്യും." (മു,ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 534, 534, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "يُقَالُ لِصَاحِب الْقُرْآنِ إِذَا دَخَلَ الْجَنَّةَ: اقْرَأْ وَاصْعَدْ، فَيَقْرَأُ وَيَصْعَدُ بِكُلِّ آيَة دَرَجَةً، حَتَّى يَقْرَأَ آخِرَ شَيْءٍ مَعَهُ". (جه)', 'അബൂസഈദിൽ ഖുദ്രി(റ): റസൂൽ(സ) പറഞ്ഞു: "ഖിയാമത്ത് നാളിൽ ഖുർആനുമായി സഹവസിച്ചവനോട് സ്വർഗത്തിൽ പ്രവേശിച്ചാൽ പറയപ്പെടും: നീ ഓതുകയും കയറുകയും ചെയ്യുക. അങ്ങനെ അവൻ ഓതുകയും ഓരോ സൂക്തത്തിനനുസരിച്ച് ഓരോ സ്ഥാനം കയറുകയും ചെയ്യും. അങ്ങനെ അവൻ അവസാനത്തെ സൂക്തവും ഓതുംവരെ (സ്ഥാനങ്ങൾ ഉയർന്നുകൊണ്ടിരിക്കും)." (ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 534, 534, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ بُرَيْدَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "يَجِيءُ الْقُرْآنُ يَوْمَ الْقِيَامَة كَالرَّجُلِ الشَّاحِب، فَيَقُولُ: أَنَا الَّذِي أَسْهَرْتُ لَيْلَكَ، وَأَظْمَأْتُ نَهَارَكَ". (جه)', 'ബുറൈദ(റ): റസൂൽ(സ) പറഞ്ഞു: "അന്ത്യനാളിൽ ഖുർആൻ മെലിഞ്ഞൊട്ടി, നിറം മാറിയ ഒരാളുടെ രൂപത്തിൽ വന്ന് പറയും: നിന്റെ രാത്രിയെ ഉറക്കമൊഴിപ്പിച്ചവനും നിന്റെ പകലിനെ ദാഹിപ്പിച്ചവനുമാണ് ഞാൻ." (ജ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 534, 534, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "أَيُحِبُّ أَحَدُكُمْ، إِذَا رَجَعَ إِلَى أَهْله، أَنْ يَجِدَ فِيه ثَلَاثَ خَلِفَات عِظَامٍ سِمَان". قُلْنَا: نَعَمْ. قَالَ: "فَثَلَاثُ آيَات يَقْرَؤُهُنَّ أَحَدُكُمْ فِي صَلَاته، خَيْرٌ لَهُ مِنْ ثَلَاث خَلِفَات سِمَان عِظَامٍ". (م,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) ചോദിച്ചു: "നിങ്ങളിലാരെങ്കിലും തന്റെ വീട്ടുകാരുടെ അടുത്തേക്ക് തിരിച്ചെത്തുമ്പോൾ, അവിടെ നല്ല തടിച്ചുകൊഴുത്ത ഗർഭിണികളായ മൂന്ന് ഒട്ടകങ്ങളെ കാണുന്നത് ഇഷ്ടപ്പെടുന്നുണ്ടോ?" ഞങ്ങൾ പറഞ്ഞു: അതെ. റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാൾ തന്റെ നിസ്കാരത്തിലോതുന്ന മൂന്ന് ആയത്തുകൾ തടിച്ചുകൊഴുത്ത ഗർഭിണികളായ മൂന്ന് ഒട്ടകങ്ങളേക്കാൾ അവനുത്തമമാണ്." (മു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 534, 534, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "مَثَلُ الْقُرْآنِ مَثَلُ الْإِبِلِ الْمُعَقَّلَة: إِنْ تَعَاهَدَهَا صَاحِبُهَا بِعُقُلِهَا أَمْسَكَهَا عَلَيْه، وَإِنْ أَطْلَقَ عُقُلَهَا ذَهَبَتْ". (م,جه)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഖുർആനിന്റെ ഉപമ കെട്ടിയിടപ്പെട്ട ഒട്ടകത്തെപ്പോലെയാണ്: ഉടമസ്ഥൻ അതിന്റെ കയറുകൊണ്ട് അതിനെ സൂക്ഷിച്ചാൽ അതിനെ പിടിച്ചുനിൽക്കാം. കയറഴിച്ചാൽ അത് ഓടിപ്പോകും." (മു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 534, 535, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "يَقُولُ الرَّبُّ عَزَّ وَجَلَّ: مَنْ شَغَلَهُ الْقُرْآنُ وَذِكْرِي عَنْ مَسْأَلَتِي، أَعْطَيْتُهُ أَفْضَل مَا أُعْطِي السَّائِلِينَ، وَفَضْلُ كَلَامِ اللَّه عَلَى سَائِرِ الْكَلَامِ كَفَضْلِ اللَّه عَلَى خَلْقِه". (ت)', 'അബൂസഈദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "യോഗ്യനും ഉന്നതനുമായ അല്ലാഹു പറയും: ഖുർആനും എന്റെ സ്മരണയും കാരണത്താലാണ് ഒരാൾക്ക് എന്നോട് (വല്ലതും) ചോദിക്കാൻ കഴിയാത്തതെങ്കിൽ ചോദിക്കുന്നവർക്ക് നൽകുന്നതിനേക്കാൾ ശ്രേഷ്ഠമായി ഞാനവന് നൽകും. മറ്റു സംസാരങ്ങളേക്കാൾ അല്ലാഹുവിന്റെ കലാമിനുള്ള ശ്രേഷ്ഠത, തന്റെ സൃഷ്ടികളേക്കാൾ അല്ലാഹുവിനുള്ള ശ്രേഷ്ഠത പോലെയാണ്." ഹദീസ് ഹസനാണ്. (തു)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 535, 535, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: خَرَجَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ وَنَحْنُ فِي الصُّفَّة فَقَالَ: "أَيُّكُمْ يُحِبُّ أَنْ يَغْدُوَ كُلَّ يَوْمٍ إِلَى بُطْحَانَ، أَوْ إِلَى الْعَقِيق، فَيَأْتِيَ مِنْهُ بِنَاقَتَيْنِ كَوْمَاوَيْنِ، فِي غَيْرِ إِثْمٍ وَلَا قَطْعِ رَحِمٍ". فَقُلْنَا: يَا رَسُولَ اللَّه، كُلُّنَا يُحِبُّ ذَلِكَ. قَالَ: "أَفَلَا يَغْدُو أَحَدُكُمْ إِلَى الْمَسْجِد فَيَعْلَمُ أَوْ يَقْرَأُ آيَتَيْنِ مِنْ كِتَابِ اللَّه عَزَّ وَجَلَّ، خَيْرٌ لَهُ مِنْ نَاقَتَيْنِ، وَثَلَاثٌ [خَيْرٌ لَهُ مِنْ ثَلَاثٍ] وَأَرْبَعٌ خَيْرٌ لَهُ مِنْ أَرْبَعٍ، وَمِنْ أَعْدَادِهِنَّ مِنَ الْإِبِلِ". (م)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): ഞങ്ങൾ പള്ളിയുടെ ചെരുവിലിരിക്കെ തിരുദൂതർ(സ) പുറപ്പെട്ടു. റസൂൽ(സ) ചോദിച്ചു: "നിങ്ങളിലാരെങ്കിലും എല്ലാ ദിവസവും ബുഥ്ഹാനിലേക്കും അഖീഖിലേക്കും (മദീനക്കടുത്തുള്ള രണ്ട് ദേശങ്ങൾ) പോയി, ഒരു തെറ്റും ചെയ്യാതെയും കുടുംബബന്ധം വിഛേദിക്കാതെയും പൂഞ്ഞയുയർന്ന രണ്ട് ഒട്ടകങ്ങളെ അവിടെ നിന്നും കൊണ്ടുവരുന്നത് ഇഷ്ടപ്പെടുന്നുണ്ടോ?" ഞങ്ങൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞങ്ങളെല്ലാവരും അത് ഇഷ്ടപ്പെടുന്നുണ്ട്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാൾ പള്ളിയിൽ പോയി മഹോന്നതനായ അല്ലാഹുവിന്റെ ഗ്രന്ഥത്തിൽ നിന്നും രണ്ട് സൂക്തങ്ങൾ ഓതുകയോ പഠിക്കുകയോ ചെയ്യലാണ് രണ്ട് ഒട്ടകത്തേക്കാൾ അവനുത്തമം. മൂന്ന് സൂക്തങ്ങളാണ് (മൂന്ന് ഒട്ടകങ്ങളേക്കാൾ ഉത്തമം) നാല് സൂക്തങ്ങളാണ് നാല് ഒട്ടകങ്ങളേക്കാൾ അവനുത്തമം. ഓരോ സൂക്തവും അത്രയെണ്ണം ഒട്ടകങ്ങളേക്കാൾ അവനുത്തമമാണ്." (മു)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['م']::text[], array['മു']::text[], 'خَيْرٌ لَهُ مِنْ ثَلَاثٍ', null, 535, 535, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنِ الْحَارِثِ الْأَعْوَرِ قَالَ: مَرَرْتُ فِي الْمَسْجِدِ، فَإِذَا النَّاسُ يَخُوضُونَ فِي الْأَحَادِيثِ، فَدَخَلْتُ عَلَى عَلِيٍّ رَضِيَ اللهُ عَنْهُ، فَقُلْتُ: يَا أَمِيرَ الْمُؤْمِنِينَ، أَلَا تَرَى أَنَّ النَّاسَ قَدْ خَاضُوا فِي الْأَحَادِيثِ؟ قَالَ: وَقَدْ فَعَلُوهَا؟ قُلْتُ: نَعَمْ. قَالَ: أَمَا إِنِّي قَدْ سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "أَلَا إِنَّهَا سَتَكُونُ فِتْنَةٌ". فَقُلْتُ: مَا الْمَخْرَجُ مِنْهَا يَا رَسُولَ اللهِ؟ قَالَ: "كِتَابُ اللهِ، فِيهِ نَبَأُ مَا كَانَ قَبْلَكُمْ وَخَبَرُ مَا بَعْدَكُمْ، وَحُكْمُ مَا بَيْنَكُمْ، وَهُوَ الْفَصْلُ، لَيْسَ بِالْهَزْلِ، مَنْ تَرَكَهُ مِنْ جَبَّارٍ قَصَمَهُ اللهُ، وَمَنِ ابْتَغَى الْهُدَى فِي غَيْرِهِ أَضَلَّهُ اللهُ، وَهُوَ حَبْلُ اللهِ الْمَتِينُ، وَهُوَ الذِّكْرُ الْحَكِيمُ، وَهُوَ الصِّرَاطُ الْمُسْتَقِيمُ. وَهُوَ الَّذِي لَا تَزِيغُ بِهِ الْأَهْوَاءُ، وَلَا تَلْتَبِسُ بِهِ الْأَلْسِنَةُ، وَلَا يَشْبَعُ مِنْهُ الْعُلَمَاءُ، وَلَا يَخْلَقُ عَلَى كَثْرَةِ الرَّدِّ، وَلَا تَنْقَضِي عَجَائِبُهُ، هُوَ الَّذِي لَمْ تَنْتَهِ الْجِنُّ إِذْ سَمِعَتْهُ حَتَّى قَالُوا: {إِنَّا سَمِعْنَا قُرْآنًا عَجَبًا. يَهْدِي إِلَى الرُّشْدِ فَآمَنَّا بِهِ} [الجن: ١، ٢]. مَنْ قَالَ بِهِ صَدَقَ، وَمَنْ عَمِلَ بِهِ أُجِرَ، وَمَنْ حَكَمَ بِهِ عَدَلَ، وَمَنْ دَعَا إِلَيْهِ هَدَى إِلَى صِرَاطٍ مُسْتَقِيمٍ". خُذْهَا إِلَيْكَ يَا أَعْوَرُ. (ت)', 'ഹാരിസുൽ അഅ്വർ(റ): ഞാൻ പള്ളിയിലൂടെ നടന്നു. അന്നേരം ജനങ്ങളെല്ലാം ഓരോ സംസാരങ്ങളിൽ ഏർപ്പെട്ടിരിക്കുകയാണ്. അങ്ങനെ ഞാൻ അലി(റ)വിന്റെ അടുത്ത് ചെന്ന് പറഞ്ഞു: അമീറുൽ മുഅ്മിനീൻ, ജനങ്ങൾ ഓരോ സംസാരങ്ങളിലേർപ്പെട്ടിരിക്കുന്നത് അങ്ങ് കാണുന്നില്ലേ? അലി(റ) ചോദിച്ചു: അവരങ്ങനെ ചെയ്തോ? ഞാൻ പറഞ്ഞു: അതെ. അലി(റ) പറഞ്ഞു: "അറിയുക, നിശ്ചയം പിന്നീട് ഫിത്ന ഉണ്ടാകുന്നതാണ്" എന്ന് റസൂൽ(സ) പറഞ്ഞിരുന്നു. അപ്പോൾ ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അതിൽ നിന്നുള്ള പോംവഴി എന്താണ്? റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ ഗ്രന്ഥം. അതിൽ നിങ്ങൾക്ക് മുമ്പുള്ള ചരിത്രങ്ങളും നിങ്ങൾക്ക് ശേഷം വരാനിരിക്കുന്ന വിവരങ്ങളും നിങ്ങൾക്കിടയിലെ വിധിന്യായങ്ങളും ഉണ്ട്. അത് സത്യാസത്യം വേർതിരിക്കുന്നതാണ്. അത് തമാശയല്ല. ഏതെങ്കിലും ഒരു അഹങ്കാരി അതിനെ ഉപേക്ഷിച്ചാൽ അവനെ അല്ലാഹു നശിപ്പിക്കുന്നതാണ്. അതല്ലാത്ത മറ്റൊന്നിൽ ആരെങ്കിലും സന്മാർഗത്തെ കാംക്ഷിച്ചാൽ അല്ലാഹു അവനെ പിഴപ്പിക്കും. അത് അല്ലാഹുവിന്റെ ദൃഢമായ പാശമാണ്. അത് യുക്തി നിറഞ്ഞ ചിന്തയാണ്. അത് ചൊവ്വായ മാർഗമാണ്. അതു കാരണത്താൽ ഇച്ഛകൾ വഴിതെറ്റുകയില്ല. നാക്കുകൾക്ക് അതുകൊണ്ട് അവ്യക്തത വരില്ല. ജ്ഞാനികൾക്ക് അതിൽ നിന്നും വയറ് നിറയുകയില്ല. എത്രതന്നെ ആവർത്തിച്ചാലും മടുപ്പ് വരില്ല. അതിന്റെ അത്ഭുതങ്ങൾ അവസാനിക്കില്ല. ജിന്നുകളത് കേട്ടപ്പോൾ അവർക്ക് ആശ തീർന്നില്ല. അവർ പറഞ്ഞില്ലേ: ''സന്മാർഗത്തിലേക്ക് നയിക്കുന്ന, അത്ഭുതകരമായ ഖുർആൻ ഞങ്ങൾ കേട്ടു. അപ്പോൾ ഞങ്ങളത് കൊണ്ട് വിശ്വസിച്ചു.'' (ജിന്ന്: 1,2) ഖുർആനനുസരിച്ചാരെങ്കിലും പറഞ്ഞാൻ അവൻ സത്യം പറഞ്ഞിരിക്കുന്നു. അതനുസരിച്ച് പ്രവർത്തിച്ചവന് കൂലി നൽകപ്പെടും. അതനുസരിച്ച് വിധി നടപ്പാക്കിയവൻ നീതി പാലിച്ചിരിക്കുന്നു. അതിലേക്കാരെങ്കിലും ക്ഷണിച്ചാൽ അവൻ ചൊവ്വായ വഴിയിലേക്ക് നയിക്കപ്പെട്ടിരിക്കുന്നു." അഅ്വറേ, നീ ഈ കാര്യം മനസ്സിലാക്കിവെക്കുക. (തു)', 'الْحَارِثِ الْأَعْوَرِ قَالَ', 'ഹാരിസുൽ അഅ്വർ(റ)', null, null, array['ت']::text[], array['തു']::text[], 'الجن: ١، ٢', null, 535, 536, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "الَّذِي يَقْرَأُ الْقُرْآن، وَهُوَ مَاهِرٌ بِه، مَعَ السَّفَرَة الْكِرَامِ الْبَرَرَة. وَالَّذِي يَقْرَؤُهُ، وَهُوَ شَدِيدٌ عَلَيْه وَهُوَ عَلَيْه شَاقٌّ، فَلَهُ أَجْرَان". (ق,د,ت,ن,جه)', 'ആഇശ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഖുർആനെക്കുറിച്ച് നൈപുണ്യമുള്ളവനായി അതിനെ പാരായണം ചെയ്യുന്നവൻ ഉന്നതസ്ഥാനീയരായ മലക്കുകളുടെയും പ്രവാചകന്മാരുടെയും കൂടെയായിരിക്കും. ബുദ്ധിമുട്ട് സഹിച്ച്, അത് ഭാരമായിരിക്കെ ഖുർആൻ ഓതുന്നവന് രണ്ട് കൂലിയുണ്ട്." (ബു,മു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 536, 536, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ عَلِيٍّ بْنِ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "مَنْ قَرَأَ الْقُرْآن وَاسْتَظْهَرَهُ، فَأَحَلَّ حَلَالَهُ وَحَرَّمَ حَرَامَهُ، أَدْخَلَهُ اللَّهُ بِه الْجَنَّةَ، وَشَفَّعَهُ فِي عَشَرَةٍ مِنْ أَهْلِ بَيْتِه، كُلُّهُمْ وَجَبَتْ لَهُمُ النَّارُ". (ت,جه)', 'അലി(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും ഖുർആൻ പാരായണം ചെയ്ത് അത് മനഃപാഠമാക്കുകയും അതിലെ അനുവദനീയമായ കാര്യങ്ങളെ അനുവദനീയമായി കാണുകയും അതിൽ നിഷിദ്ധമാക്കപ്പെട്ടവയെ നിഷിദ്ധമാക്കപ്പെട്ടവയായി കാണുകയും ചെയ്താൽ അല്ലാഹു അവനെ സ്വർഗത്തിൽ പ്രവേശിപ്പിക്കുകയും അവന്റെ കൂട്ടുകുടുംബത്തിലെ നരകാവകാശികളായ പത്താളുകളിൽ അവന് ശുപാർശക്ക് അവകാശം നൽകുകയും ചെയ്യുന്നതാണ്." (തു,ജ)', 'عَلِيٍّ بْنِ أَبِي طَالِبٍ', 'അലി(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 536, 536, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنْ عَبْد اللَّه بْنِ مَسْعُود رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "مَنْ قَرَأَ حَرْفًا مِنْ كِتَاب اللَّه فَلَهُ بِه حَسَنَةٌ، وَالْحَسَنَةُ بِعَشْرِ أَمْثَالِهَا، لَا أَقُولُ: {الم} حَرْفٌ، وَلَكِنْ أَلِفٌ حَرْفٌ، وَلَامٌ حَرْفٌ، وَمِيمٌ حَرْفٌ". (ت)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും അല്ലാഹുവിന്റെ കിതാബിൽ നിന്ന് ഒരു അക്ഷരമോതിയാൽ അവന് അതുകൊണ്ട് നന്മയുണ്ട്. ഒരു നന്മ (അതിന്റെ പ്രതിഫലം) പത്തിരട്ടിയാണ്. ''അലിഫ്ലാംമീം'' എന്നത് ഒരു അക്ഷരമാണെന്ന് ഞാൻ പറയുന്നില്ല. മറിച്ച്, അലിഫ് ഒരക്ഷരമാണ്. ലാം ഒരക്ഷരമാണ്. മീം മറ്റൊരക്ഷരമാണ്." (തു)', 'عَبْد اللَّه بْنِ مَسْعُود', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 536, 537, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "مَا أَذِنَ اللَّهُ لِعَبْدٍ فِي شَيْءٍ أَفْضَلَ مِنْ رَكْعَتَيْنِ يُصَلِّيهِمَا، وَإِنَّ الْبِرَّ لَيُذَرُّ عَلَى رَأْسِ الْعَبْد مَا دَامَ فِي صَلَاته، وَمَا تَقَرَّبَ الْعِبَادُ إِلَى اللَّه بِمِثْلِ مَا خَرَجَ مِنْهُ". يَعْنِي: الْقُرْآنَ. (ت)', 'അബൂഉമാമ(റ): നബി(സ) പറഞ്ഞു: "താൻ നിസ്കരിക്കുന്ന രണ്ട് റക്അത്തിനേക്കാൾ ശ്രേഷ്ഠമായി ഒരു കാര്യത്തിലും ഒരടിമയെ അല്ലാഹു ശ്രദ്ധിച്ച് ശ്രവിച്ചിട്ടില്ല. ഒരു അടിമ നിസ്കാരത്തിലായിരിക്കുമ്പോൾ അവന്റെ ശിരസ്സിന് മീതെ നന്മ വീതിക്കപ്പെട്ടുകൊണ്ടിരിക്കും. ഖുർആൻ മൂലമുണ്ടാകുന്ന നന്മകൾ പോലെയുള്ളതുകൊണ്ട് അടിമകൾ അല്ലാഹുവിലേക്കടുത്തിട്ടില്ല."¹ (തു)', 'أَبِي أُمَامَةَ', 'അബൂഉമാമ(റ)', '¹ ഖുർആൻ പാരായണം കൊണ്ട് അല്ലാഹുവിലേക്കടുക്കാൻ കഴിയുന്നത്ര മറ്റ് ആരാധനകൾ കൊണ്ട് കഴിയില്ല എന്ന് സാരം.', null, array['ت']::text[], array['തു']::text[], null, null, 537, 537, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "مَنْ نَفَّسَ عَنْ أَخِيه كُرْبَةً مِنْ كُرَبِ الدُّنْيَا نَفَّسَ اللَّهُ عَنْهُ كُرْبَةً مِنْ كُرَب يَوْمِ الْقِيَامَة، وَمَنْ سَتَرَ مُسْلِمًا سَتَرَهُ اللَّهُ فِي الدُّنْيَا وَالْآخِرَة، وَمَنْ يَسَّرَ عَلَى مُعْسِرٍ يَسَّرَ اللَّهُ عَلَيْه فِي الدُّنْيَا وَالْآخِرَة، وَاللَّهُ فِي عَوْنِ الْعَبْد مَا كَانَ الْعَبْدُ فِي عَوْنِ أَخِيه، وَمَنْ سَلَكَ طَرِيقًا يَلْتَمِسُ فِيه عِلْمًا، سَهَّلَ اللَّهُ لَهُ طَرِيقًا إِلَى الْجَنَّة، وَمَا قَعَدَ قَوْمٌ فِي مَسْجِد يَتْلُونَ كِتَابَ اللَّه، وَيَتَدَارَسُونَهُ بَيْنَهُمْ، إِلَّا نَزَلَتْ عَلَيْهِمُ السَّكِينَةُ، وَغَشِيَتْهُمُ الرَّحْمَةُ، وَحَفَّتْهُمُ الْمَلَائِكَةُ. وَمَنْ أَبْطَأَ بِه عَمَلُهُ لَمْ يُسْرِعْ بِه نَسَبُهُ". (م,د,ت,ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും തന്റെ സഹോദരനെ, ദുൻയാവിലെ വിഷമങ്ങളിലെ വല്ല വിഷമത്തിൽ നിന്നും അകറ്റിയാൽ, ഖിയാമത്ത് നാളിലെ വിഷമങ്ങളിലെ ഒരു വിഷമത്തിൽ നിന്നും അല്ലാഹു അവനെ അകറ്റും. ആരെങ്കിലും ഒരു മുസ്ലിമിന്റെ ന്യൂനതകളെ മറച്ചുവെച്ചാൽ അല്ലാഹു അവന്റെ ന്യൂനതകളെ ഇഹത്തിലും പരത്തിലും മറച്ചുവെക്കും. പ്രയാസമനുഭവിക്കുന്നവന് ആശ്വാസം നൽകിയവന് ഇഹത്തിലും പരത്തിലും അല്ലാഹു ആശ്വാസം നൽകും. ഒരടിമ തന്റെ സഹോദരനെ സഹായിച്ചുകൊണ്ടിരിക്കുന്ന സമയമത്രയും അല്ലാഹു അവനെ സഹായിച്ചുകൊണ്ടിരിക്കും. ആരെങ്കിലും അറിവ് അന്വേഷിച്ച് ഒരു മാർഗ്ഗത്തിൽ പ്രവേശിച്ചാൽ അല്ലാഹു അവന് സ്വർഗത്തിലേക്കുള്ള വഴി എളുപ്പമാക്കിക്കൊടുക്കും. ഏതെങ്കിലുമൊരു പള്ളിയിൽ കൂടിയിരുന്ന് ഖുർആൻ പാരായണം ചെയ്യുകയും അത് പരസ്പരം പഠിക്കുകയും ചെയ്യുന്ന ജനങ്ങൾക്ക് ശാന്തിയും മനസ്സമാധാനവുമിറങ്ങും. അനുഗ്രഹങ്ങൾ അവരെ പൊതിയുകയും മാലാഖമാർ അവരെ വാരിപ്പുണരുകയും ചെയ്യും. (അതനുസരിച്ച് പ്രവർത്തിച്ച് ഉന്നതസ്ഥാനം കരസ്ഥമാക്കുന്നതിൽ) ആരുടെയെങ്കിലും കർമ്മങ്ങൾ വൈകിപ്പോയാൽ, അവന്റെ തറവാടിത്തം അവനെ ഉന്നത സ്ഥാനങ്ങളിലേക്ക് എത്തിക്കുകയില്ല." (മു,ദ,തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 537, 537, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "إِنَّ الَّذِي لَيْسَ فِي جَوْفِه شَيْءٌ مِنَ الْقُرْآنِ كَالْبَيْتِ الْخَرِبِ". (ت)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഖുർആനിൽ നിന്ന് അൽപം പോലും അകത്തില്ലാത്തവൻ നശിച്ച വീടു പോലെയാണ്." (തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 537, 538, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ عَبْدِ اللَّه بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ قَالَ: "يُقَالُ لِصَاحِب الْقُرْآن: اقْرَأْ وَارْتَقِ، وَرَتِّلْ كَمَا كُنْتَ تُرَتِّلُ فِي الدُّنْيَا، فَإِنَّ مَنْزِلَتَكَ عِنْدَ آخِرِ آيَة تَقْرَأُ بِهَا". (خ,ت)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറഞ്ഞു: "ഖുർആനുമായി സഹവസിച്ചവനോട് പറയപ്പെടും: നീ ഓതുകയും കയറുകയും ചെയ്യുക, ദുൻയാവിൽ വെച്ച് നീ ആകർഷകമായി പാരായണം ചെയ്തതുപോലെ ആകർഷകമായി നീ പാരായണം ചെയ്യുക. നിശ്ചയം നിന്റെ സ്ഥാനം നീ ഓതുന്ന അവസാന സൂക്തത്തിനടുത്താണ്." (ബു,തു)', 'عَبْدِ اللَّه بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['خ','ت']::text[], array['ബു','തു']::text[], null, null, 538, 538, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ قَالَ: "يَجِيءُ الْقُرْآنُ يَوْمَ الْقِيَامَة، فَيَقُولُ: يَا رَبِّ حَلِّه، فَيُلْبَسُ تَاجَ الْكَرَامَة، ثُمَّ يَقُولُ: يَا رَبِّ، زِدْهُ، فَيُلْبَسُ حُلَّةَ الْكَرَامَة، ثُمَّ يَقُولُ: يَا رَبِّ: ارْضَ عَنْهُ، فَيَرْضَى عَنْهُ، فَيُقَالُ لَهُ: اقْرَأْ وَارْقَ، وَتُزَادُ بِكُلِّ آيَة حَسَنَةً". (ت)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "അന്ത്യനാളിൽ ഖുർആൻ വന്ന് പറയും: എന്റെ രക്ഷിതാവേ, അവനെ നീ അണിയിക്ക്. അപ്പോഴവൻ മഹത്വത്തിന്റെ കിരീടമണിയിക്കപ്പെടും. പിന്നെ അത് പറയും: എന്റെ രക്ഷിതാവേ, അവന് നീ അധികരിപ്പിക്ക്, അപ്പോഴവൻ മഹത്വത്തിന്റെ വസ്ത്രം ധരിപ്പിക്കപ്പെടും. പിന്നെ ഖുർആൻ പറയും: എന്റെ രക്ഷിതാവേ, അവനിൽ നീ സംതൃപ്തനായാലും, അപ്പോൾ അല്ലാഹു അവനിൽ സംതൃപ്തനാകും. അവനോട് പറയപ്പെടും: നീ ഓതുകയും കയറുകയും ചെയ്യുക. ഓരോ സൂക്തത്തിനും പകരം ഓരോ നന്മ അവന് അധികരിക്കപ്പെടും." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 538, 538, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنِ الْبَرَاءِ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَجُلٌ يَقْرَأُ سُورَةَ الْكَهْف، وَعِنْدَهُ فَرَسٌ مَرْبُوطٌ بِشَطَنَيْنِ، فَتَغَشَّتْهُ سَحَابَةٌ، فَجَعَلَتْ تَدُورُ وَتَدْنُو، وَجَعَلَ فَرَسُهُ يَنْفِرُ مِنْهَا، فَلَمَّا أَصْبَحَ أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ فَذَكَرَ ذَلِكَ لَهُ، فَقَالَ: "تِلْكَ السَّكِينَةُ تَنَزَّلَتْ لِلْقُرْآن". (م)', 'ബറാഅ്(റ): ഒരാൾ സൂറത്തുൽ കഹ്ഫ് ഓതുകയായിരുന്നു. അയാളുടെ അടുത്ത് നീണ്ട രണ്ട് കയറുകൾ കൊണ്ട് കെട്ടിയിട്ട ഒരു കുതിരയുമുണ്ടായിരുന്നു. അപ്പോൾ അദ്ദേഹത്തെ ഒരു മേഘം പൊതിഞ്ഞു. അത് കറങ്ങാനും തന്നോടടുക്കാനും തുടങ്ങി. കുതിരയാണെങ്കിൽ അതിൽ നിന്നും ഓടിയകലാൻ തുടങ്ങി. പ്രഭാതമായപ്പോൾ അദ്ദേഹം തിരുദൂതരുടെ അടുത്തുചെന്ന് സംഭവം പറഞ്ഞു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അത് ഖുർആൻ പാരായണം കാരണം ഇറങ്ങിയ ശാന്തിയാണ്." (മു)', 'الْبَرَاءِ', 'ബറാഅ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 538, 538, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ أُسَيْدِ بْنِ حُضَيْرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَيْنَمَا هُوَ يَقْرَأُ مِنَ اللَّيْلِ سُورَةَ الْبَقَرَة، وَفَرَسُهُ مَرْبُوطَةٌ عِنْدَهُ، إِذْ جَالَتِ الْفَرَسُ، فَسَكَتَ فَسَكَتَتْ، فَقَرَأَ فَجَالَتِ الْفَرَسُ، فَسَكَتَ وَسَكَتَتِ الْفَرَسُ، ثُمَّ قَرَأَ، فَجَالَتِ الْفَرَسُ فَانْصَرَفَ، وَكَانَ ابْنُهُ يَحْيَى قَرِيبًا مِنْهَا، فَأَشْفَقَ أَنْ تُصِيبَهُ، فَلَمَّا اجْتَرَّهُ رَفَعَ رَأْسَهُ إِلَى السَّمَاءِ حَتَّى مَا يَرَاهَا، فَلَمَّا أَصْبَحَ حَدَّثَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ فَقَالَ: "اقْرَأْ يَا ابْنَ حُضَيْرٍ، اقْرَأْ يَا ابْنَ حُضَيْرٍ". قَالَ: فَأَشْفَقْتُ يَا رَسُولَ اللَّه أَنْ تَطَأَ يَحْيَى، وَكَانَ مِنْهَا قَرِيبًا، فَرَفَعْتُ رَأْسِي فَانْصَرَفْتُ إِلَيْه، فَرَفَعْتُ رَأْسِي إِلَى السَّمَاءِ، فَإِذَا مِثْلُ الظُّلَّة فِيهَا أَمْثَالُ الْمَصَابِيح، فَخَرَجَتْ حَتَّى لَا أَرَاهَا، قَالَ: "وَتَدْرِي مَا ذَاكَ؟" قُلْتُ: لَا، قَالَ: "تِلْكَ الْمَلَائِكَةُ دَنَتْ لِصَوْتِكَ، وَلَوْ قَرَأْتَ لَأَصْبَحَتْ يَنْظُرُ النَّاسُ إِلَيْهَا، لَا تَتَوَارَى مِنْهُمْ". (خ)', 'ഉസൈദുബ്നു ഹുളൈർ(റ): അദ്ദേഹം രാത്രിയിൽ ''ബഖറ'' സൂറത്ത് ഓതിക്കൊണ്ടിരിക്കെ, അദ്ദേഹത്തിന്റെ കുതിര അദ്ദേഹത്തിനടുത്ത് തന്നെ ബന്ധിക്കപ്പെട്ടിരിക്കുകയായിരുന്നു. പെട്ടെന്ന് കുതിര ചാടി. അദ്ദേഹം നിശബ്ദനായപ്പോൾ കുതിരയുമടങ്ങി. അദ്ദേഹം ഓത്ത് തുടർന്നപ്പോൾ കുതിര വീണ്ടും ചാടി. അദ്ദേഹം നിശബ്ദനായപ്പോൾ കുതിരയും അടങ്ങി. ശേഷം ഓത്ത് തുടർന്നു. അപ്പോൾ കുതിര ചാടി. അപ്പോൾ അദ്ദേഹം അവിടെ നിന്നെഴുന്നേറ്റു. ആ കുതിരയുടെ അടുത്തായി തന്റെ മകൻ യഹ്യയുമുണ്ടായിരുന്നു. ആ കുതിര അവന് വല്ല വിപത്തും വരുത്തുമോ എന്ന് അദ്ദേഹം ഭയന്നു. അവനെ വലിച്ചുകൊണ്ടുവന്ന് അദ്ദേഹം ആകാശത്തേക്ക് തലയുയർത്തിയപ്പോൾ വല്ലാത്തൊരു കാഴ്ച കണ്ടു. പ്രഭാതമായപ്പോൾ നബി(സ)യോട് വിവരം പറഞ്ഞു. അപ്പോൾ നബി(സ) ഉസൈദ്(റ)വിനോട് പറഞ്ഞു: "ഇബ്നുഹുളൈറേ, നീ ഓതുക. ഇബ്നുഹുളൈറേ, നീ ഓതുക." ഉസൈദ്(റ) തുടർന്നു: തിരുദൂതരേ, ആ കുതിര എന്റെ മകൻ യഹ്യയെ ചവിട്ടുമോ എന്ന് ഞാൻ ഭയന്നു. അവൻ ആ കുതിരയുടെ അടുത്തായിരുന്നു. ഞാൻ എന്റെ തലയുയർത്തി. അവനടുത്തേക്ക് പോയി. ഞാൻ ആകാശത്തേക്ക് തലയുയർത്തിനോക്കിയപ്പോഴതാ, തണൽ മേഘം പോലൊരു സാധനം. അതിൽ നിറയെ വിളക്കുമാടങ്ങളുണ്ട്. എനിക്ക് കാണാൻ കഴിയാത്ത നിലക്ക് അത് നീങ്ങിപ്പോയി. റസൂൽ(സ) ചോദിച്ചു: "അതെന്താണെന്ന് താങ്കൾക്കറിയുമോ?" ഞാൻ പറഞ്ഞു: ഇല്ല. റസൂൽ(സ) പറഞ്ഞു: "അത് നിന്റെ ശബ്ദം കേട്ട് അടുത്തുവന്ന മാലാഖമാരാണ്. നീ ഓതിക്കൊണ്ടിരിക്കുകയാണെങ്കിൽ പ്രഭാതമാകുംവരെ അവർ അവിടത്തന്നെ നിൽക്കുകയും ജനങ്ങൾക്ക് അവരെ കാണുകയും ചെയ്യാമായിരുന്നു." (ബു)', 'أُسَيْدِ بْنِ حُضَيْرٍ', 'ഉസൈദുബ്നു ഹുളൈർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 538, 539, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ سَمِعَ رَسُولَ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ يَقُولُ: "مَا أَذِنَ اللَّهُ لِشَيْءٍ مَا أَذِنَ لِنَبِيٍّ حَسَنِ الصَّوْت يَتَغَنَّى بِالْقُرْآن". يَجْهَرُ بِه. (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നത് അദ്ദേഹം കേട്ടു: "അല്ലാഹു ഒരു പ്രവാചകനിൽ നിന്നും ഖുർആൻ ശ്രവണസുന്ദരമായി ഉച്ചത്തിൽ പാരായണം ചെയ്യുന്നത് ശ്രവിക്കുന്നത്ര മറ്റൊന്നിനെയും ശ്രദ്ധിച്ച് ശ്രവിച്ചിട്ടില്ല." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 539, 539, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ أَبِي بُرْدَةَ، عَنْ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ لِأَبِي مُوسَى: "لَوْ رَأَيْتَنِي وَأَنَا أَسْتَمِعُ قِرَاءَتَكَ الْبَارِحَةَ، لَقَدْ أُوتِيتَ مِزْمَارًا مِنْ مَزَامِير آل دَاوُدَ". (م)', 'അബൂബുർദ(റ) അബൂമൂസാ(റ)വിൽ നിന്നും ഉദ്ധരിക്കുന്നു: റസൂൽ(സ) അബൂമൂസാ(റ)വിനോട് പറഞ്ഞു: "ഇന്നലെ രാത്രി നിന്റെ ഖുർആൻ പാരായണം ഞാൻ ശ്രദ്ധിച്ചുകേൾക്കുന്നത് നീ കണ്ടിരുന്നെങ്കിൽ. നിശ്ചയം ദാവൂദ് കുടുംബത്തിന് നൽകപ്പെട്ട സുന്ദരശബ്ദങ്ങളിൽ നിന്നൊരു സ്വരം നിനക്ക് നൽകപ്പെട്ടിരിക്കുന്നു." (മു)', 'أَبِي بُرْدَةَ، عَنْ أَبِي مُوسَى', 'അബൂബുർദ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 539, 539, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "زَيِّنُوا الْقُرْآنَ بِأَصْوَاتِكُمْ". (ن)', 'ബറാഉബ്നു ആസിബ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളുടെ ശബ്ദങ്ങൾ കൊണ്ട് ഖുർആനെ നിങ്ങൾ ഭംഗിയാക്കുക." (ന)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നു ആസിബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 539, 539, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ يَقُولُ: "إِنَّ هَذَا الْقُرْآنَ نَزَلَ بِحُزْنٍ، فَإِذَا قَرَأْتُمُوهُ فَابْكُوا، فَإِنْ لَمْ تَبْكُوا فَتَبَاكَوْا. وَتَغَنَّوْا بِه، فَمَنْ لَمْ يَتَغَنَّ بِه فَلَيْسَ مِنَّا". (جه)', 'സഅ്ദുബ്നു അബീവഖാസ്(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "നിശ്ചയം, ഈ ഖുർആൻ വ്യസനം കൂടെപ്പിറപ്പായാണ് അവതരിച്ചിട്ടുള്ളത്. (ചിന്തിക്കുന്നവൻ ചിന്തിച്ചാൽ അവന് വ്യസനം വരും, കണ്ണ് നിറയും.) അതുകൊണ്ട് ഖുർആൻ പാരായണം ചെയ്യുമ്പോൾ നിങ്ങൾ കരയുക. കരച്ചിൽ വരുന്നില്ലെങ്കിൽ ഉണ്ടാക്കിക്കരയുക. അതിനെ ശ്രവണസുന്ദരമായി പാരായണം ചെയ്യുക. ശ്രവണസുന്ദരമായി അതിനെ പാരായണം ചെയ്യാത്തവൻ നമ്മിൽപ്പെട്ടവനല്ല." (ജ)', 'سَعْدِ بْنِ أَبِي وَقَّاصٍ', 'സഅ്ദുബ്നു അബീവഖാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 539, 540, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: أَبْطَأْتُ عَلَى عَهْد رَسُول اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ لَيْلَةً بَعْدَ الْعِشَاء، ثُمَّ جِئْتُ، فَقَالَ: "أَيْنَ كُنْت". قُلْتُ: كُنْتُ أَسْتَمِعُ قِرَاءَةَ رَجُلٍ مِنْ أَصْحَابِكَ، لَمْ أَسْمَعْ مِثْل قِرَاءَتِه وَصَوْتِه مِنْ أَحَد. قَالَتْ: فَقَامَ وَقُمْتُ مَعَهُ حَتَّى اسْتَمَعَ لَهُ، ثُمَّ الْتَفَتَ إِلَيَّ فَقَالَ: "هَذَا سَالِمٌ مَوْلَى أَبِي حُذَيْفَةَ. الْحَمْدُ لِلَّه الَّذِي جَعَلَ فِي أُمَّتِي مِثْل هَذَا". (جه)', 'ആഇശ(റ): റസൂൽ(സ)യുടെ കാലത്തൊരിക്കൽ ഇശാ കഴിഞ്ഞു രാത്രി ഞാൻ താമസിച്ചു. പിന്നീട് ഞാൻ വന്നു. അപ്പോൾ അവിടുന്ന് ചോദിച്ചു: "നീ എവിടെയായിരുന്നു?" ഞാൻ പറഞ്ഞു: ഞാൻ അങ്ങയുടെ അനുചരരിൽപ്പെട്ട ഒരാളുടെ ഖുർആൻ പാരായണം ശ്രവിക്കുകയായിരുന്നു. അദ്ദേഹത്തിന്റെ ശബ്ദം പോലെയോ ഖുർആൻ പാരായണം പോലെയോ ഒരാളിൽ നിന്നും ഞാൻ കേട്ടിട്ടില്ല. മഹതി പറയുന്നു: അപ്പോൾ റസൂൽ(സ) എഴുന്നേറ്റു. ഞാനും അദ്ദേഹത്തിന്റെ പാരായണം കേൾക്കാൻ വേണ്ടി റസൂൽ(സ)യോടുകൂടെ എഴുന്നേറ്റു. പിന്നെ റസൂൽ(സ) എന്നിലേക്ക് തിരിഞ്ഞ് പറഞ്ഞു: "ഇത് അബൂഹുദൈഫയുടെ അടിമ സാലിമാണ്. എന്റെ സമുദായത്തിൽ ഇതു പോലെയുള്ളവരെ സൃഷ്ടിച്ച അല്ലാഹുവിനാണ് സർവ സ്തുതിയും." (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 540, 540, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "إِنَّ مِنْ أَحْسَنِ النَّاسِ صَوْتًا بِالْقُرْآن، الَّذِي إِذَا سَمِعْتُمُوهُ يَقْرَأُ حَسِبْتُمُوهُ يَخْشَى اللَّهَ". (جه)', 'ജാബിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം ജനങ്ങളിൽ വെച്ച് ഖുർആൻ കൊണ്ട് ഏറ്റവും സുന്ദര ശബ്ദമുള്ളവൻ, അവൻ ഓതുന്നത് നിങ്ങൾ കേട്ടാൽ അയാൾ അല്ലാഹുവിനെ ഭയക്കുന്നവനാണെന്ന് നിങ്ങൾ വിചാരിക്കുന്നവനാണ്." പരമ്പരയിൽ ബലഹീനരുണ്ട്. (ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 540, 540, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ فَضَالَةَ بْنِ عُبَيْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَلَّهُ أَشَدُّ أَذَنًا إِلَى الرَّجُلِ الْحَسَنِ الصَّوْتِ بِالْقُرْآنِ – يَجْهَرُ بِهِ – مِنْ صَاحِبِ الْقَيْنَةِ إِلَى قَيْنَتِهِ". (جه)', 'ഫളാലതുബ്നു ഉബൈദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "തീർച്ചയായും ഒരു ഗാനാരാധകൻ തന്റെ പാട്ടുകാരിയെ ശ്രദ്ധിക്കുന്നതിനേക്കാൾ കൂടുതൽ, സുന്ദര ശബ്ദത്തോടെ ഉച്ചത്തിൽ ഖുർആൻ പാരായണം ചെയ്യുന്നവനെ അല്ലാഹു ശ്രദ്ധിക്കുന്നതാണ്." (ജ)', 'فَضَالَةَ بْنِ عُبَيْدٍ', 'ഫളാലതുബ്നു ഉബൈദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 540, 540, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: دَخَلَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ الْمَسْجِدَ فَسَمِعَ قِرَاءَةَ رَجُلٍ، فَقَالَ: "مَنْ هَذَا؟" فَقِيلَ: عَبْدُ اللَّه بْنُ قَيْسٍ. فَقَالَ: "لَقَدْ أُوتِيَ هَذَا مِنْ مَزَامِيرِ آلِ دَاوُدَ". (جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പള്ളിയിൽ പ്രവേശിച്ചപ്പോൾ ഒരാളുടെ ഓത്ത് കേട്ടു. അപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "ഇതാരാണ്?" ആരോ പറഞ്ഞു: അബ്ദുല്ലാഹിബ്നു ഖൈസാണ്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം ദാവൂദ്(അ)ന്റെ കുടുംബത്തിന്റെ സുന്ദരശബ്ദങ്ങളിൽ നിന്ന് (അൽപം) അദ്ദേഹത്തിന് നൽകപ്പെട്ടിരിക്കുന്നു." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 540, 540, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ عَبْدِ اللَّه بْنِ مُغَفَّلٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ يَوْمَ فَتْحِ مَكَّةَ وَهُوَ عَلَى نَاقَة، يَقْرَأُ بِسُورَة الْفَتْح وَهُوَ يُرَجِّعُ. (ق,د,ت)', 'അബ്ദുല്ലാഹിബ്നു മുഗഫ്ഫൽ(റ): ഫത്ഹ് മക്കാ ദിനത്തിൽ റസൂൽ(സ) ഒരു ഒട്ടകപ്പുറത്തിരിക്കുന്നത് ഞാൻ കണ്ടു. അവിടുന്ന് ഫത്ഹ് സൂറത്ത് ആവർത്തിച്ച് ഓതിക്കൊണ്ടിരിക്കുന്നു. (ബു,മു,ദ,തു)', 'عَبْدِ اللَّه بْنِ مُغَفَّلٍ', 'അബ്ദുല്ലാഹിബ്നു മുഗഫ്ഫൽ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 540, 540, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ أُمِّ هَانِئٍ رَضِيَ اللَّهُ عَنْهُ قَالَتْ: كُنْتُ أَسْمَعُ قِرَاءَةَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ وَأَنَا عَلَى عَرِيشِي. (ن)', 'ഉമ്മുഹാനിഅ്(റ): ഞാനെന്റെ മേലോപ്പിലിരിക്കെതന്നെ റസൂൽ(സ)യുടെ ഖുർആൻ പാരായണം കേൾക്കാറുണ്ടായിരുന്നു. (ന)', 'أُمِّ هَانِئٍ', 'ഉമ്മുഹാനിഅ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 541, 541, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ قَتَادَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَأَلْتُ أَنَسًا رَضِيَ اللَّهُ عَنْهُ: كَيْفَ كَانَتْ قِرَاءَةُ رَسُولِ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ؟ قَالَ: كَانَ يَمُدُّ صَوْتَهُ مَدًّا. (ن)', 'ഖതാദ(റ): ഞാൻ അനസ്(റ)വിനോട് ചോദിച്ചു: റസൂൽ(സ)യുടെ ഖുർആൻ പാരായണം എപ്രകാരം ആയിരുന്നു? അനസ്(റ) പറഞ്ഞു: റസൂൽ(സ) അവിടുത്തെ ശബ്ദം നല്ലവണ്ണം നീട്ടുമായിരുന്നു. (ന)', 'قَتَادَةَ', 'ഖതാദ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 541, 541, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنْ أَنَسٍ، عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ – رَضِيَ اللهُ عَنْهُمَا – قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَثَلُ الْمُؤْمِنِ الَّذِي يَقْرَأُ الْقُرْآنَ كَمَثَلِ الْأُتْرُنْجَةِ، رِيحُهَا طَيِّبٌ وَطَعْمُهَا طَيِّبٌ. وَمَثَلُ الْمُؤْمِنِ الَّذِي لَا يَقْرَأُ الْقُرْآنَ كَمَثَلِ التَّمْرَةِ، لَا رِيحَ لَهَا وَطَعْمُهَا حُلْوٌ. وَمَثَلُ الْمُنَافِقِ الَّذِي يَقْرَأُ الْقُرْآنَ كَمَثَلِ الرَّيْحَانَةِ، رِيحُهَا طَيِّبٌ وَطَعْمُهَا مُرٌّ. وَمَثَلُ الْمُنَافِقِ الَّذِي لَا يَقْرَأُ الْقُرْآنَ كَمَثَلِ الْحَنْظَلَةِ، رِيحُهَا مُرٌّ وَطَعْمُهَا مُرٌّ". (ق,د,ت,ن,جه)', 'അനസ്(റ): അബൂമൂസൽ അശ്അരി(റ): റസൂൽ(സ) പറഞ്ഞു: "ഖുർആൻ പാരായണം ചെയ്യുന്ന വിശ്വാസിയുടെ ഉപമ മാതളനാരങ്ങ പോലെയാണ്. അതിന്റെ വാസനയും രുചിയും നല്ലതാണ്. ഖുർആൻ ഓതാത്ത വിശ്വാസിയുടെ ഉപമ കാരക്ക പോലെയാണ്. അതിന് വാസനയില്ല. അതിന്റെ രുചി മധുരമാണ് താനും. ഖുർആൻ പാരായണം ചെയ്യുന്ന കപടവിശ്വാസിയുടെ ഉപമ റൈഹാൻ പുഷ്പം പോലെയാണ്. അതിന്റെ വാസന നല്ലതും രുചി കയ്പുമാണ്. ഖുർആൻ പാരായണം ചെയ്യാത്ത കപടവിശ്വാസിയുടെ ഉപമ ആട്ടങ്ങ പോലെയാണ്. അതിന്റെ വാസനയും രുചിയും കയ്പാണ്." (ബു,മു,ദ,തു,ന,ജ)', 'أَنَسٍ، عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ –', 'അനസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 541, 541, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "مَثَلُ الْمُؤْمِنِ كَمَثَلِ الزَّرْعِ، لَا تَزَالُ الرِّيَاحُ تُفَيِّئُهُ، وَلَا يَزَالُ الْمُؤْمِنُ يُصِيبُهُ بَلَاءٌ. وَمَثَلُ الْمُنَافِق مَثَلُ شَجَرَة الْأَرْزِ، لَا تَهْتَزُّ حَتَّى تُسْتَحْصَدَ". (ق,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "സത്യവിശ്വാസിയുടെ ഉപമ കൃഷി പോലെയാണ്. കാറ്റുകൾ അവയെ ചലിപ്പിച്ച് കൊണ്ടിരിക്കും. സത്യവിശ്വാസിക്ക് എപ്പോഴും പരീക്ഷണങ്ങൾ എത്തിക്കൊണ്ടിരിക്കും. കപടവിശ്വാസിയുടെ ഉപമ ദേവദാരു മരത്തെപ്പോലെയാണ്. അത് മുറിക്കപ്പെടുന്നത് വരെ ഇളകുകയില്ല." (ബു,മു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 541, 541, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ قَالَ: "إِنَّ مِنَ الشَّجَرِ شَجَرَةً لَا يَسْقُطُ وَرَقُهَا، وَهِيَ مَثَلُ الْمُؤْمِنِ، حَدِّثُونِي مَا هِيَ". قَالَ عَبْدُ اللَّه: فَوَقَعَ النَّاسُ فِي شَجَرِ الْبَوَادِي، وَوَقَعَ فِي نَفْسِي أَنَّهَا النَّخْلَةُ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "هِيَ النَّخْلَةُ". فَاسْتَحْيَيْتُ أَنْ أَقُولَ. قَالَ عَبْدُ اللَّه: فَحَدَّثْتُ عُمَرَ رَضِيَ اللَّهُ عَنْهُ بِالَّذِي وَقَعَ فِي نَفْسِي، فَقَالَ: لَأَنْ تَكُونَ قُلْتَهَا أَحَبُّ إِلَيَّ مِنْ أَنْ يَكُونَ لِي كَذَا وَكَذَا. (ق,ت)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "വൃക്ഷങ്ങളിൽ ഇല പൊഴിക്കാത്തൊരു മരമുണ്ട്. അത് സത്യവിശ്വാസിയുടെ ഉപമയാണ്. അത് ഏതാണെന്ന് നിങ്ങളെനിക്ക് പറഞ്ഞുതരിക." അബ്ദുല്ല(റ) പറഞ്ഞു: അപ്പോൾ ജനങ്ങൾക്ക് തോന്നിയത് അത് പർവതതാഴ്വാരത്തിലുണ്ടാകുന്ന വൃക്ഷമാണെന്നാണ്. എനിക്ക് തോന്നിയത് അത് തീർച്ചയായും ഈത്തപ്പനയാണെന്നാണ്. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അത് ഈത്തപ്പനയാണ്." പക്ഷേ, ഞാൻ പറയാൻ മടിച്ചു. അബ്ദുല്ല(റ) പറയുന്നു: ശേഷം ഞാൻ ഉമർ(റ)വിനോട് എന്റെ മനസ്സിൽ തോന്നിയതിനെക്കുറിച്ച് പറഞ്ഞു. അപ്പോൾ ഉമർ(റ) പറഞ്ഞു: നീ അത് പറയലായിരുന്നു ഇന്നാലിന്ന വസ്തുക്കൾ ലഭിക്കുന്നതിനേക്കാൾ എനിക്കേറ്റവും ഇഷ്ടപ്പെട്ടത്. (ബു,മു,തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 541, 542, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّهُ مَرَّ عَلَى قَاصٍّ يَقْرَأُ، ثُمَّ سَأَلَهُ، فَاسْتَرْجَعَ ثُمَّ قَالَ: سَمِعْتُ رَسُولَ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ يَقُولُ: "مَنْ قَرَأَ الْقُرْآنَ فَلْيَسْأَلِ اللَّهَ بِه، فَإِنَّهُ سَيَجِيءُ أَقْوَامٌ يَقْرَءُونَ الْقُرْآن، يَسْأَلُونَ بِه النَّاسَ". (ت)', 'ഇംറാനുബ്നു ഹുസൈൻ(റ): അദ്ദേഹം ഖുർആനോതിക്കൊണ്ടിരിക്കുന്ന ഒരു പ്രസംഗകന്റെ അടുത്തുകൂടെ നടന്നുപോയി. പിന്നെ അയാൾ അദ്ദേഹത്തോട് യാചിച്ചു. അപ്പോൾ അദ്ദേഹം ''ഇസ്തിർജാഅ്'' (''ഇന്നാലില്ലാഹി വ ഇന്നാഇലൈഹി റാജിഊൻ'' എന്ന്) ചൊല്ലി, എന്നിട്ട് പറഞ്ഞു: റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "ആരെങ്കിലും ഖുർആൻ പാരായണം ചെയ്താൽ അവൻ അതുകൊണ്ട് അല്ലാഹുവിനോട് ചോദിക്കട്ടെ. നിശ്ചയം, ശേഷം ഖുർആൻ പാരായണം ചെയ്യുന്ന ഒരു വിഭാഗം വരും. അവർ ഖുർആൻ കൊണ്ട് ജനങ്ങളോട് യാചിക്കുന്നവരായിരിക്കും." ഹദീസ് ഹസനാണ്. (തു)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസൈൻ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 542, 542, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ صُهَيْبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "مَا آمَنَ بِالْقُرْآن مَنِ اسْتَحَلَّ مَحَارِمَهُ". (ت)', 'സുഹൈബ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഖുർആനിലെ നിഷിദ്ധമാക്കപ്പെട്ട കാര്യങ്ങൾ അനുവദനീയമായി കാണുന്നവൻ ഖുർആൻ കൊണ്ട് വിശ്വസിച്ചിട്ടില്ല." (തു)', 'صُهَيْبٍ', 'സുഹൈബ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 542, 542, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ يَقُولُ: "الْجَاهِرُ بِالْقُرْآن كَالْجَاهِرِ بِالصَّدَقَة، وَالْمُسِرُّ بِالْقُرْآن كَالْمُسِرِّ بِالصَّدَقَة". (د,ت,ن)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഖുർആൻ ഉച്ചത്തിൽ പാരായണം ചെയ്യുന്നവൻ പരസ്യമായി ദാനം ചെയ്യുന്നവനെപ്പോലെയാണ്. ഖുർആൻ രഹസ്യമായി പാരായണം ചെയ്യുന്നവൻ രഹസ്യമായി ദാനം ചെയ്യുന്നവനെപ്പോലെയാണ്." ഹദീസ് ഹസനാണ്. (ദ,തു,ന)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 542, 542, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ أَبِي سَعِيد الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ يَقُولُ: "يَخْرُجُ فِيكُمْ قَوْمٌ تَحْقِرُونَ صَلَاتَكُمْ مَعَ صَلَاتِهِمْ، وَصِيَامَكُمْ مَعَ صِيَامِهِمْ، وَعَمَلَكُمْ مَعَ عَمَلِهِمْ، وَيَقْرَءُونَ الْقُرْآنَ لَا يُجَاوِزُ حَنَاجِرَهُمْ، يَمْرُقُونَ مِنَ الدِّينِ كَمَا يَمْرُقُ السَّهْمُ مِنَ الرَّمِيَّة، يَنْظُرُ فِي النَّصْلِ فَلَا يَرَى شَيْئًا، وَيَنْظُرُ فِي الْقِدْحِ فَلَا يَرَى شَيْئًا، وَيَنْظُرُ فِي الرِّيشِ فَلَا يَرَى شَيْئًا، وَيَتَمَارَى فِي الْفُوقِ". (خ)', 'അബൂസഈദിൽ ഖുദ്രി(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "നിങ്ങളിലൊരു വിഭാഗം പ്രത്യക്ഷപ്പെടും. അവരുടെ നിസ്കാരങ്ങളും നോമ്പുകളും ആരാധനകളും കണ്ടാൽ നിങ്ങളുടെ നോമ്പുകളും നിസ്കാരങ്ങളും ആരാധനകളും നിങ്ങൾക്ക് പുച്ഛമായി തോന്നും. അവർ ഖുർആൻ പാരായണം ചെയ്യും. പക്ഷേ, അത് അവരുടെ തൊണ്ട വിട്ടിറങ്ങുകയില്ല. വേട്ടയാടപ്പെടുന്ന മൃഗത്തിലൂടെ തുളച്ച് മറുപുറം കടക്കുന്ന അമ്പ് പോലെ അവർ ദീനിൽ നിന്ന് പുറത്ത് പോയിക്കൊണ്ടിരിക്കും. അമ്പെയ്തവൻ അമ്പെടുത്ത് അതിന്റെ മുനയിൽ നോക്കും. പക്ഷേ, അമ്പേറ്റ ലക്ഷണം കാണില്ല. അമ്പിന്റെ തൂവലിലും കമ്പിലും നോക്കും പക്ഷേ, അവനൊന്നും കാണില്ല. പിന്നെയവൻ അമ്പിന്റെ കുതയിൽ സംശയിക്കും. (അത്രക്കും സൂക്ഷമമായിട്ടായിരിക്കും ദീനിൽനിന്ന് അവർ പുറത്തുപോവുക.) (ബു)', 'أَبِي سَعِيد الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 542, 543, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ جَابِرِ بْنِ عَبْد اللَّه رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ يَعْرِضُ نَفْسَهُ عَلَى النَّاسِ فِي الْمَوْقِف، فَقَالَ: "أَلَا رَجُلٌ يَحْمِلُنِي إِلَى قَوْمِه، فَإِنَّ قُرَيْشًا قَدْ مَنَعُونِي أَنْ أُبَلِّغَ كَلَامَ رَبِّي". (د,ت,جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) ഹജ്ജ് കാലത്ത് ജനങ്ങൾക്ക് മുന്നിൽ പ്രത്യക്ഷപ്പെടും. എന്നിട്ട് പറയും: "തന്റെ ജനതയിലേക്ക് എന്നെ കൊണ്ടുപോകാൻ തയ്യാറുള്ള ആരെങ്കിലുമുണ്ടോ, കാരണം എന്റെ രക്ഷിതാവിന്റെ വാക്കുകൾ എത്തിച്ചുകൊടുക്കുന്നതിൽ നിന്നും ഖുറൈശികൾ എന്നെ തടഞ്ഞിരിക്കുന്നു." (ദ,തു,ജ)', 'جَابِرِ بْنِ عَبْد اللَّه', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 543, 543, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: وَلَشَأْنِي فِي نَفْسِي كَانَ أَحْقَرَ مِنْ أَنْ يَتَكَلَّمَ اللَّهُ فِيَّ بِأَمْرٍ يُتْلَى. (ق,د)', 'ആഇശ(റ): പാരായണം ചെയ്യപ്പെടുന്ന ഒരു സൂക്തവുമായി എന്റെ വിഷയത്തിൽ അല്ലാഹു സംസാരിക്കാതിരിക്കാൻ മാത്രം നിസ്സാരമായിരുന്നു എനിക്ക് എന്റെ കാര്യം.² (ബു,മു,ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', '² എന്റെ കാര്യത്തിൽ അല്ലാഹു ഖുർആൻ അവതരിപ്പിക്കാൻ മാത്രം വലിയ ആളല്ല ഞാൻ എന്നായിരുന്നു ഞാൻ ചിന്തിച്ചിരുന്നത് എന്ന് സാരം.', null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 543, 543, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ عَامِرِ بْنِ شَهْرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنْتُ عِنْدَ النَّجَاشِيِّ، فَقَرَأَ ابْنٌ لَهُ آيَةً مِنَ الْإِنْجِيلِ، فَضَحِكْتُ، فَقَالَ: أَتَضْحَكُ مِنْ كَلَامِ اللَّه؟ (د)', 'ആമിറുബ്നു ശഹ്ർ(റ): ഞാൻ നജാശിയുടെ അടുത്തായിരുന്നപ്പോൾ അദ്ദേഹത്തിന്റെ ഒരു മകൻ ഇഞ്ചീലിലെ ഒരു സൂക്തം ഓതിക്കേൾപ്പിച്ചു. ഉടനെ ഞാൻ ചിരിച്ചു. അപ്പോൾ നജാശി ചോദിച്ചു: അല്ലാഹുവിന്റെ വാക്ക് കേട്ടിട്ട് നീ ചിരിക്കുകയാണോ? (ദ)', 'عَامِرِ بْنِ شَهْرٍ', 'ആമിറുബ്നു ശഹ്ർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 543, 543, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ يُعَوِّذُ الْحَسَنَ وَالْحُسَيْنَ: "أُعِيذُكُمَا بِكَلِمَات اللَّه التَّامَّة مِنْ كُلِّ شَيْطَانٍ وَهَامَّة، وَمِنْ كُلِّ عَيْنٍ لَامَّة". ثُمَّ يَقُولُ: "كَانَ أَبُوكُمْ يُعَوِّذُ بِهِمَا إِسْمَاعِيلَ وَإِسْحَقَ". (خ,د,ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) ഹസൻ(റ)വിനും ഹുസൈൻ(റ)വിനും വേണ്ടി കാവൽതേടാറുണ്ടായിരുന്നു: "അല്ലാഹുവിന്റെ സമ്പൂർണമായ വാക്യങ്ങൾ കൊണ്ട്, എല്ലാ പിശാചിൽ നിന്നും വിഷജന്തുക്കളിൽ നിന്നും, മനുഷ്യനെ ബുദ്ധിമുട്ടാക്കുന്ന കണ്ണിൽ നിന്നും നിങ്ങൾക്ക് ഞാൻ അഭയം തേടുന്നു." എന്നിട്ട് റസൂൽ(സ) പറയും: "നിങ്ങളുടെ പിതാവ് - ഇബ്റാഹീം(അ) - ഇവ രണ്ടുകൊണ്ടുമായിരുന്നു ഇസ്ഹാഖ്(അ)മിനും ഇസ്മാഇൗൽ(അ)നും കാവൽ തേടാറുണ്ടായിരുന്നത്." (ബു,ദ,തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','د','ت','جه']::text[], array['ബു','ദ','തു','ജ']::text[], null, null, 543, 544, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا – زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – وَقَدْ سُئِلَتْ عَنْ قِرَاءَةِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَصَلَاتِهِ، فَقَالَتْ: مَا لَكُمْ وَصَلَاتَهُ؟ كَانَ يُصَلِّي ثُمَّ يَنَامُ قَدْرَ مَا صَلَّى، ثُمَّ يُصَلِّي قَدْرَ مَا نَامَ، ثُمَّ يَنَامُ قَدْرَ مَا صَلَّى حَتَّى يُصْبِحَ. ثُمَّ نَعَتَتْ قِرَاءَتَهُ، فَإِذَا هِيَ تَنْعَتُ قِرَاءَةً مُفَسَّرَةً حَرْفًا حَرْفًا. (د,ت,ن)', 'നബി(സ)യുടെ ഭാര്യയായ ഉമ്മുസലമ(റ): നബി(സ)യുടെ ഖുർആൻ പാരായണത്തെക്കുറിച്ചും അവിടുത്തെ നിസ്കാരത്തെക്കുറിച്ചും മഹതി ചോദിക്കപ്പെട്ടു. അപ്പോൾ അവർ പറഞ്ഞു: നിങ്ങളെവിടെ! തിരുമേനി(സ)യുടെ നിസ്കാരമെവിടെ! അവിടുന്ന് നിസ്കരിക്കും. പിന്നെ നിസ്കരിച്ചയത്ര സമയം ഉറങ്ങും. വീണ്ടും ഉറങ്ങിയതിനു തുല്യമായ സമയം നിസ്കരിക്കും. പിന്നെ നിസ്കരിച്ചത്ര ഉറങ്ങും. നേരം പുലരുവോളം അവിടുന്ന് ഇങ്ങനെ തുടരും. ശേഷം മഹതി അവിടുത്തെ പാരായണത്തെക്കുറിച്ച് വർണിച്ചു. ഓരോ അക്ഷരങ്ങളും വേർതിരിച്ച് മനസ്സിലാക്കാവുന്ന, സുവ്യക്തമായ പാരായണമായിരുന്നുവെന്നാണ് മഹതി വിശേഷിപ്പിച്ചത്. (ദ,തു,ന)', 'أُمِّ سَلَمَةَ', 'നബി(സ)യുടെ ഭാര്യയായ ഉമ്മുസലമ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 544, 544, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ عَبْدِ اللهِ بْنِ أَبِي قَيْسٍ – هُوَ رَجُلٌ بَصْرِيٌّ – قَالَ: سَأَلْتُ عَائِشَةَ رَضِيَ اللهُ عَنْهَا عَنْ وِتْرِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: كَيْفَ كَانَ يُوتِرُ، مِنْ أَوَّلِ اللَّيْلِ أَوْ مِنْ آخِرِهِ؟ فَقَالَتْ: كُلُّ ذَلِكَ قَدْ كَانَ يَصْنَعُ، رُبَّمَا أَوْتَرَ مِنْ أَوَّلِ اللَّيْلِ وَرُبَّمَا أَوْتَرَ مِنْ آخِرِهِ. فَقُلْتُ: الْحَمْدُ لِلَّهِ الَّذِي جَعَلَ فِي الْأَمْرِ سَعَةً. فَقُلْتُ: كَيْفَ كَانَتْ قِرَاءَتُهُ، أَكَانَ يُسِرُّ بِالْقِرَاءَةِ أَمْ يَجْهَرُ؟ قَالَتْ: كُلُّ ذَلِكَ قَدْ كَانَ يَفْعَلُ، قَدْ كَانَ رُبَّمَا أَسَرَّ وَرُبَّمَا جَهَرَ. قَالَ: فَقُلْتُ: الْحَمْدُ لِلَّهِ الَّذِي جَعَلَ فِي الْأَمْرِ سَعَةً. قُلْتُ: فَكَيْفَ كَانَ يَصْنَعُ فِي الْجَنَابَةِ، أَكَانَ يَغْتَسِلُ قَبْلَ أَنْ يَنَامَ أَوْ يَنَامُ قَبْلَ أَنْ يَغْتَسِلَ؟ قَالَتْ: كُلُّ ذَلِكَ قَدْ كَانَ يَفْعَلُ، فَرُبَّمَا اغْتَسَلَ فَنَامَ، وَرُبَّمَا تَوَضَّأَ فَنَامَ. قُلْتُ: الْحَمْدُ لِلَّهِ الَّذِي جَعَلَ فِي الْأَمْرِ سَعَةً. (ق,د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു അബീഖൈസ്(റ) - അദ്ദേഹം ബസ്വറക്കാരനാണ്: നബി(സ)യുടെ വിത്ർ നിസ്കാരത്തെക്കുറിച്ച് ഞാൻ ആഇശ(റ)യോട് ചോദിച്ചു. അവിടുന്ന് രാത്രിയുടെ ആദ്യഭാഗത്തായിരുന്നോ അവസാനഭാഗത്തായിരുന്നോ വിത്ർ നിസ്കരിക്കാറുണ്ടായിരുന്നത്? മഹതി പറഞ്ഞു: അവിടുന്ന് എല്ലാ രീതിയിലും ചെയ്യാറുണ്ടായിരുന്നു. ചിലപ്പോൾ രാത്രിയുടെ ആദ്യസമയങ്ങളിൽ നിസ്കരിക്കും. ചിലസമയങ്ങളിൽ രാത്രിയുടെ അവസാനയാമങ്ങളിലും നിസ്കരിക്കും. അപ്പോൾ ഞാൻ പറഞ്ഞു: കാര്യങ്ങളിൽ വിശാലത നൽകിയ അല്ലാഹുവിനാണ് സർവ്വ സ്തുതിയും. അപ്പോൾ ഞാൻ ചോദിച്ചു: അവിടുത്തെ ഖുർആൻ പാരായണം എങ്ങനെയായിരുന്നു? പതുക്കെയായിരുന്നോ ഉച്ചത്തിലായിരുന്നോ അവിടുന്ന് ഓതിയിരുന്നത്? മഹതി പറഞ്ഞു: അവിടുന്ന് എല്ലാ വിധത്തിലും ചെയ്യാറുണ്ടായിരുന്നു. ചിലപ്പോൾ പതുക്കെയും ചിലപ്പോൾ ഉച്ചത്തിലും ഓതും. അപ്പോൾ ഞാൻ പറഞ്ഞു: കാര്യങ്ങളിൽ വിശാലത നൽകിയ അല്ലാഹുവിനാണ് സർവ്വ സ്തുതിയും. ഞാൻ ചോദിച്ചു: വലിയ അശുദ്ധിയുടെ വിഷയത്തിൽ അവിടുന്ന് എന്താണ് ചെയ്യാറുണ്ടായിരുന്നത്? ഉറങ്ങുന്നതിന് മുമ്പ് അവിടുന്ന് കുളിക്കാറുണ്ടായിരുന്നോ, അതോ കുളിക്കുന്നതിന് മുമ്പ് ഉറങ്ങാറുണ്ടായിരുന്നോ? മഹതി പറഞ്ഞു: അവിടുന്ന് എല്ലാ വിധത്തിലും ചെയ്യാറുണ്ടായിരുന്നു. ചിലപ്പോൾ കുളിച്ച് ഉറങ്ങും. ചിലപ്പോൾ വുളു ചെയ്ത് ഉറങ്ങും. അപ്പോൾ ഞാൻ പറഞ്ഞു: കാര്യങ്ങളിൽ വിശാലത നൽകിയ അല്ലാഹുവിനാണ് സർവ്വ സ്തുതിയും. (ബു,മു,ദ,തു,ന,ജ)', 'عَبْدِ اللهِ بْنِ أَبِي قَيْسٍ – هُوَ رَجُلٌ بَصْرِيٌّ – قَالَ', 'അബ്ദുല്ലാഹിബ്നു അബീഖൈസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 544, 544, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ، أَنَّهُ سُئِلَ: كَيْفَ كَانَتْ قِرَاءَةُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ؟ فَقَالَ: كَانَتْ مَدًّا، ثُمَّ قَرَأَ {بِسْمِ اللَّه الرَّحْمَنِ الرَّحِيمِ} يَمُدُّ بِبِسْمِ اللَّه، وَيَمُدُّ بِالرَّحْمَنِ، وَيَمُدُّ بِالرَّحِيمِ. (خ)', 'അനസുബ്നു മാലിക്(റ): നബി(സ)യുടെ പാരായണം എങ്ങനെയായിരുന്നുവെന്ന് അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടു. അപ്പോഴദ്ദേഹം പറഞ്ഞു: അവിടുത്തെ പാരായണം നീട്ടിക്കൊണ്ടുള്ളതായിരുന്നു. പിന്നീടദ്ദേഹം ബിസ്മില്ലാഹി എന്നതും അർറഹ്മാനി എന്നതും അർറഹീം എന്നതും നീട്ടിക്കൊണ്ട് ബിസ്മി ഓതി. (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 544, 545, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ أَنَسِ بْنِ مَالك رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ لِأُبَيِّ بْنِ كَعْبٍ رَضِيَ اللَّهُ عَنْهُ: "إِنَّ اللَّهَ [عَزَّ وَجَلَّ] أَمَرَنِي أَنْ أَقْرَأَ عَلَيْكَ: {لَمْ يَكُنِ الَّذِينَ كَفَرُوا}". قَالَ: وَسَمَّانِي [لَكَ]؟ قَالَ: "نَعَمْ". قَالَ: فَبَكَى. (م)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) ഉബയ്യുബ്നു കഅ്ബ്(റ)വിനോട് പറഞ്ഞു: "ലം യകുനില്ലദീന കഫറൂ'' എന്ന സൂറത്ത് നിങ്ങൾക്ക് ഓതിത്തരാൻ ഉന്നതനും യോഗ്യനുമായ അല്ലാഹു എന്നോട് കൽപിച്ചിരിക്കുന്നു." അദ്ദേഹം ചോദിച്ചു: അല്ലാഹു അങ്ങയോട് എന്റെ പേര് പറഞ്ഞുവോ? അവിടുന്ന് പറഞ്ഞു: "അതെ." നിവേദകൻ പറയുന്നു: അപ്പോഴദ്ദേഹം കരഞ്ഞു. (മു)', 'أَنَسِ بْنِ مَالك', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م']::text[], array['മു']::text[], 'لَكَ', null, 545, 545, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنْ عَامِرٍ [هُوَ الشَّعْبِيُّ] قَالَ: سَأَلْتُ عَلْقَمَةَ: هَلْ كَانَ ابْنُ مَسْعُود شَهِدَ مَعَ رَسُول اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ لَيْلَةَ الْجِنِّ؟ قَالَ: فَقَالَ عَلْقَمَةُ: أَنَا سَأَلْتُ ابْنَ مَسْعُود فَقُلْتُ: هَلْ شَهِدَ أَحَدٌ مِنْكُمْ مَعَ رَسُول اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ لَيْلَةَ الْجِنِّ؟ قَالَ: لَا، وَلَكِنَّا كُنَّا مَعَ رَسُول اللَّه ذَاتَ لَيْلَة فَفَقَدْنَاهُ، فَالْتَمَسْنَاهُ فِي الْأَوْدِيَة وَالشِّعَاب، فَقُلْنَا: اسْتُطِيرَ أَوِ اغْتِيلَ. قَالَ: فَبِتْنَا بِشَرِّ لَيْلَة بَاتَ بِهَا قَوْمٌ، فَلَمَّا أَصْبَحْنَا إِذَا هُوَ جَاءٍ مِنْ قِبَلِ حِرَاء، قَالَ: فَقُلْنَا: يَا رَسُولَ اللَّه، فَقَدْنَاكَ فَطَلَبْنَاكَ فَلَمْ نَجِدْكَ، فَبِتْنَا بِشَرِّ لَيْلَة بَاتَ بِهَا قَوْمٌ. فَقَالَ: "أَتَانِي دَاعِي الْجِنِّ، فَذَهَبْتُ مَعَهُ، فَقَرَأْتُ عَلَيْهِمُ الْقُرْآنَ". قَالَ: فَانْطَلَقَ بِنَا، فَأَرَانَا آثَارَهُمْ وَآثَارَ نِيرَانِهِمْ، وَسَأَلُوهُ الزَّادَ، فَقَالَ: "لَكُمْ كُلُّ عَظْمٍ ذُكِرَ اسْمُ اللَّه عَلَيْه، يَقَعُ فِي أَيْدِيكُمْ أَوْفَرَ مَا يَكُونُ لَحْمًا، وَكُلُّ بَعْرَة عَلَفٌ لِدَوَابِّكُمْ". فَقَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "فَلَا تَسْتَنْجُوا بِهِمَا، فَإِنَّهُمَا طَعَامُ إِخْوَانِكُمْ". (م)', 'ആമിർ(റ): ഞാൻ അൽഖമ(റ)വിനോട് ചോദിച്ചു: ജിന്നുകളുമായി നബി(സ) കണ്ടുമുട്ടിയ രാത്രി ഇബ്നുമസ്ഊദ്(റ) നബി(സ)യുടെ കൂടെയുണ്ടായിരുന്നോ? അപ്പോൾ അൽഖമ(റ) പറഞ്ഞു: ഞാൻ ഇബ്നുമസ്ഊദ്(റ)വിനോടൊരിക്കൽ ചോദിച്ചു: നബി(സ) ജിന്നുകളുമായി കണ്ടുമുട്ടിയ രാത്രി നിങ്ങളിലാരെങ്കിലും അവിടുത്തോടൊപ്പമുണ്ടായിരുന്നോ? അദ്ദേഹം പറഞ്ഞു: ഇല്ല. എന്നാൽ ഒരു രാത്രിയിൽ ഞങ്ങൾ തിരുമേനി(സ)യുടെ കൂടെ കഴിയുന്നതിനിടക്ക് അവിടുത്തെ കാണാതായി. ഞങ്ങൾ മലഞ്ചെരുവുകളിലും മലയിടുക്കുകളിലും തിരുമേനി(സ)യെ തിരഞ്ഞു. ഒടുവിൽ ഞങ്ങൾ പറഞ്ഞു: മലക്കുകൾ അവിടുത്തെയെടുത്ത് പറന്നുപോയിരിക്കുന്നു. അല്ലെങ്കിൽ അവിടുന്ന് ചതിയിലൂടെ കൊല്ലപ്പെട്ടിരിക്കുന്നു. നിവേദകൻ പറയുന്നു: അങ്ങനെ ഞങ്ങൾ, ജനങ്ങൾ കഴിച്ചുകൂട്ടിയ രാത്രികളിൽ ഏറ്റവും മോശമായ ഒരു രാത്രി കഴിച്ചുകൂട്ടി. നേരം പുലർന്നപ്പോൾ അവിടുന്നതാ ഹിറാഇന്റെ (ഒരു സ്ഥലം) ഭാഗത്തുനിന്ന് വരുന്നു. നിവേദകൻ പറയുന്നു: അപ്പോൾ ഞങ്ങൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞങ്ങൾ അങ്ങയെ കാണാതായി. അങ്ങയെ അന്വേഷിച്ചെങ്കിലും കണ്ടെത്തിയില്ല. അങ്ങനെ ജനങ്ങൾ കഴിച്ചുകൂട്ടിയതിൽ വെച്ചേറ്റവും മോശമായ ഒരു രാത്രിയാണ് ഞങ്ങൾ കഴിച്ചുകൂട്ടിയത്. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "ജിന്നുകളിൽ നിന്നൊരാൾ എന്നെ ക്ഷണിക്കാനായി വന്നു. അപ്പോൾ ഞാനദ്ദേഹത്തിന്റെ കൂടെപ്പോയി. അങ്ങനെ ഞാനവർക്ക് ഖുർആൻ ഓതിക്കൊടുത്തു." അദ്ദേഹം പറഞ്ഞു: അങ്ങനെ അവിടുന്ന് ഞങ്ങളെയും കൊണ്ട് പോകുകയും അവരുടെ അടയാളങ്ങളും അവരുടെ തീയിന്റെ അടയാളങ്ങളും ഞങ്ങൾക്ക് കാണിച്ചുതരികയും ചെയ്തു. ജിന്നുകൾ അവിടുത്തോട് ഭക്ഷണത്തിന് വേണ്ടി പ്രാർത്ഥിക്കാൻ പറഞ്ഞു. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "അല്ലാഹുവിന്റെ നാമം സ്മരിക്കപ്പെട്ട എല്ലാ എല്ലുകളും നിങ്ങൾക്കുള്ളതാണ്. പൂർണമായും ഇറച്ചിയുള്ളതായിട്ട് അത് നിങ്ങളുടെ കൈകളിലെത്തും. കന്നുകാലികളുടെ കാഷ്ടങ്ങൾ മുഴുവനും നിങ്ങളുടെ വാഹനങ്ങൾക്കുള്ള ഭക്ഷണമാണ്." എന്നിട്ട് റസൂൽ(സ) പറഞ്ഞു: അതിനാൽ നിങ്ങൾ അവരണ്ടുകൊണ്ടും മനോരം ചെയ്യരുത്. കാരണമവ നിങ്ങളുടെ സഹോദരന്മാരുടെ ഭക്ഷണമാണ്." (മു)', 'عَامِرٍ [هُوَ الشَّعْبِيُّ] قَالَ', 'ആമിർ(റ)', null, null, array['م']::text[], array['മു']::text[], 'هُوَ الشَّعْبِيُّ', null, 545, 546, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنْ مَعْنٍ قَالَ: سَمِعْتُ أَبِي قَالَ: سَأَلْتُ مَسْرُوقًا: مَنْ آذَنَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِالْجِنِّ لَيْلَةَ اسْتَمَعُوا الْقُرْآنَ؟ فَقَالَ: حَدَّثَنِي أَبُوكَ – يَعْنِي ابْنَ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ – أَنَّهُ آذَنَتْهُ بِهِمْ شَجَرَةٌ. (م)', 'മഅ്ൻ(റ): എന്റെ പിതാവ് പറയുന്നത് ഞാൻ കേട്ടു: ഞാൻ മസ്റൂഖ്(റ)വിനോട് ചോദിച്ചു: ജിന്നുകൾ ഖുർആൻ ശ്രവിച്ച രാത്രി അവരുടെ സാന്നിദ്ധ്യം ആരാണ് നബി(സ)യെ അറിയിച്ചത്. അപ്പോഴദ്ദേഹം പറഞ്ഞു: അവരുടെ സാന്നിദ്ധ്യം അവിടുത്തെ അറിയിച്ചത് ഒരു മരമാണെന്ന് നിന്റെ പിതാവ് - ഇബ്നുമസ്ഊദ്(റ) - എന്നെ അറിയിച്ചിട്ടുണ്ട്. (മു)', 'مَعْنٍ قَالَ', 'മഅ്ൻ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 546, 546, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنْ عَبْد اللَّه بْنِ مَسْعُود رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ لِي رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "اقْرَأْ عَلَيَّ الْقُرْآنَ". قَالَ: فَقُلْتُ: يَا رَسُولَ اللَّه، أَقْرَأُ عَلَيْكَ وَعَلَيْكَ أُنْزِلَ؟ قَالَ: "إِنِّي أَشْتَهِي أَنْ أَسْمَعَهُ مِنْ غَيْرِي". فَقَرَأْتُ النِّسَاءَ حَتَّى إِذَا بَلَغْتُ: {فَكَيْفَ إِذَا جِئْنَا مِنْ كُلِّ أُمَّة بِشَهِيد وَجِئْنَا بِكَ عَلَى هَؤُلَاءِ شَهِيدًا} [٤١] رَفَعْتُ رَأْسِي، أَوْ غَمَزَنِي رَجُلٌ إِلَى جَنْبِي، فَرَفَعْتُ رَأْسِي فَرَأَيْتُ دُمُوعَهُ تَسِيلُ. (م)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) എന്നോട് പറഞ്ഞു: "നീ എനിക്ക് ഖുർആൻ ഓതിത്തന്നാലും." അപ്പോൾ ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഖുർആൻ അങ്ങേക്കാണ് ഇറങ്ങിയത് എന്നിരിക്കെ ഞാൻ അങ്ങേക്ക് ഓതിത്തരികയോ? അവിടുന്ന് പറഞ്ഞു: "ഞാനല്ലാത്ത മറ്റൊരാളിൽനിന്ന് അത് കേൾക്കാൻ ഞാൻ ആഗ്രഹിക്കുന്നു." അപ്പോൾ ഞാൻ സൂറത്തുന്നിസാഅ് ഓതി. അങ്ങനെ ''എല്ലാ സമുദായത്തിൽ നിന്നും ഓരോ സാക്ഷികളെ നാം കൊണ്ടുവരികയും ഇക്കൂട്ടർക്ക് എതിരെയുള്ള സാക്ഷിയായി അങ്ങയെ നാം കൊണ്ടുവരികയും ചെയ്താൽ എങ്ങനെയുണ്ടാവും'' (4: 41) എന്ന സൂക്തം എത്തിയപ്പോൾ ഞാനെന്റെ തല ഉയർത്തി, അല്ലെങ്കിൽ ഒരാൾ എന്റെ ഒരു ഭാഗത്ത് തോണ്ടി. ഉടൻ ഞാൻ തലയുയർത്തി. അപ്പോൾ അവിടുത്തെ കണ്ണീർ ഒലിക്കുന്നത് ഞാൻ കണ്ടു. (മു)', 'عَبْد اللَّه بْنِ مَسْعُود', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['م']::text[], array['മു']::text[], '٤١', null, 546, 546, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنْ عَبْد اللَّه بْنِ مَسْعُود رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنْتُ بِحِمْصَ، فَقَالَ لِي بَعْضُ الْقَوْمِ: اقْرَأْ عَلَيْنَا، فَقَرَأْتُ عَلَيْهِمْ سُورَةَ يُوسُفَ [عليه السلام]. قَالَ: فَقَالَ رَجُلٌ مِنَ الْقَوْمِ: وَاللَّه مَا هَكَذَا أُنْزِلَتْ. قَالَ: قُلْتُ: وَيْحَكَ، وَاللَّه لَقَدْ قَرَأْتُهَا عَلَى رَسُول اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ فَقَالَ لِي: "أَحْسَنْتَ". فَبَيْنَمَا أَنَا أُكَلِّمُهُ إِذْ وَجَدْتُ مِنْهُ رِيحَ الْخَمْرِ، قَالَ: فَقُلْتُ: أَتَشْرَبُ الْخَمْرَ وَتُكَذِّبُ بِالْكِتَاب؟ لَا تَبْرَحُ حَتَّى أَجْلِدَكَ. قَالَ: فَجَلَدْتُهُ الْحَدَّ. (ق)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ഞാൻ ഹിംസ്വിലായിരുന്നപ്പോൾ ചില ആളുകൾ എന്നോട് പറഞ്ഞു: താങ്കൾ ഞങ്ങൾക്ക് ഖുർആൻ ഓതിത്തന്നാലും. അപ്പോൾ ഞാനവർക്ക് സൂറത്തുയൂസുഫ് ഓതിക്കൊടുത്തു. അപ്പോൾ അവരിൽ നിന്നൊരാൾ പറഞ്ഞു: അല്ലാഹുവാണെ, ഇത് ഇങ്ങനെയല്ല ഇറക്കപ്പെട്ടത്. ഞാൻ പറഞ്ഞു: നാശം, അല്ലാഹുവാണെ, ഞാനിത് റസൂൽ(സ)ക്ക് ഓതിക്കൊടുത്തിട്ടുണ്ട്. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "നന്നായിരിക്കുന്നു." അങ്ങനെ ഞാനയാളുമായി സംസാരിച്ചുകൊണ്ടിരിക്കെ അയാളിൽ മദ്യത്തിന്റെ വാസന കണ്ടെത്തി. അപ്പോൾ ഞാൻ ചോദിച്ചു: നീ മദ്യം കഴിച്ച് ഖുർആനെ കളവാക്കുകയാണോ? നിന്നെ ഞാൻ ഹദ്ദടിക്കുംവരെ നീ ഇപ്രകാരം തന്നെയിരിക്കും. നിവേദകൻ പറയുന്നു: അങ്ങനെ ഞാനയാളെ ഹദ്ദടിച്ചു. (ബു,മു)', 'عَبْد اللَّه بْنِ مَسْعُود', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], 'عليه السلام', null, 546, 547, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنْ مُعَاوِيَةَ بْنِ قُرَّةَ قَالَ: سَمِعْتُ عَبْدَ اللَّه بْنَ مُغَفَّلٍ الْمُزَنِيَّ رَضِيَ اللَّهُ عَنْهُ يَقُولُ: قَرَأَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ عَامَ الْفَتْحِ فِي مَسِيرٍ لَهُ سُورَةَ الْفَتْحِ عَلَى رَاحِلَته، فَرَجَّعَ فِي قِرَاءَته. قَالَ مُعَاوِيَةُ: لَوْلَا أَنِّي أَخَافُ أَنْ يَجْتَمِعَ عَلَيَّ النَّاسُ لَحَكَيْتُ لَكُمْ قِرَاءَتَهُ. (م)', 'മുആവിയതുബ്നു ഖുർറ(റ): അബുദല്ലാഹിബ്നുൽ മുഗഫൽ(റ) ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടു: മക്കാ വിജയ വർഷം നബി(സ) അവിടുത്തെ ഒരു യാത്രയിൽ വാഹനപ്പുറത്തിരുന്ന് ഖുർആൻ പാരായണം ചെയ്തു. അങ്ങനെ അവിടുന്ന് ആവർത്തിച്ചു പാരായണം ചെയ്തു. മുആവിയ(റ) പറഞ്ഞു: ജനങ്ങൾ എന്റടുത്ത് ഒരുമിച്ചുകൂടും എന്ന് ഭയപ്പെട്ടില്ലായിരുന്നുവെങ്കിൽ തിരുമേനി(സ)യുടെ പാരായണംപോലെ ഞാൻ നിങ്ങൾക്ക് ഓതിക്കേൾപ്പിക്കുമായിരുന്നു. (മു)', 'مُعَاوِيَةَ بْنِ قُرَّةَ قَالَ', 'മുആവിയതുബ്നു ഖുർറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 547, 547, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "خَيْرُ الدَّوَاءِ الْقُرْآنُ". (جه)', 'അലി(റ): റസൂൽ(സ) പറഞ്ഞു: "ഏറ്റവും നല്ല ഔഷധം ഖുർആനാണ്." (ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 547, 547, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: بَيْنَمَا جِبْرِيلُ قَاعِدٌ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ سَمِعَ نَقِيضًا مِنْ فَوْقِه، فَرَفَعَ رَأْسَهُ فَقَالَ: هَذَا بَابٌ مِنَ السَّمَاءِ فُتِحَ الْيَوْمَ، لَمْ يُفْتَحْ قَطُّ إِلَّا الْيَوْمَ، فَنَزَلَ مِنْهُ مَلَكٌ، فَقَالَ: هَذَا مَلَكٌ نَزَلَ إِلَى الْأَرْضِ لَمْ يَنْزِلْ قَطُّ إِلَّا الْيَوْمَ، فَسَلَّمَ وَقَالَ: أَبْشِرْ بِنُورَيْنِ أُوتِيتَهُمَا، لَمْ يُؤْتَهُمَا نَبِيٌّ قَبْلَكَ: فَاتِحَةُ الْكِتَاب، وَخَوَاتِيمُ سُورَة الْبَقَرَة، لَنْ تَقْرَأَ بِحَرْفٍ مِنْهُمَا إِلَّا أُعْطِيتَهُ. (م,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ജിബ്രീൽ(അ) നബി(സ)യുടെ സമീപത്തിരിക്കെ മുകളിൽ നിന്ന് വാതിൽ തുറക്കുന്ന ശബ്ദം കേട്ടു. ജിബ്രീൽ(അ) തലയുയർത്തിയിട്ട് പറഞ്ഞു: ഇത് ആകാശത്ത് ഇന്ന് തുറക്കപ്പെട്ടൊരു കവാടമാണ്. ഇതിനുമുമ്പ് ഇന്നുവരെ അത് തുറക്കപ്പെട്ടിട്ടില്ല. അതിൽ നിന്നൊരു മലക്ക് ഇറങ്ങി. അപ്പോൾ ജിബ്രീൽ(അ) പറഞ്ഞു: ഇത് ഭൂമിയിലേക്കിറങ്ങിയ ഒരു മലക്കാണ്. ഇതിനുമുമ്പ് ഇതുവരെ ഈ മലക്ക് ഇറങ്ങിയിട്ടില്ല. അങ്ങനെ ആ മലക്ക് സലാം പറഞ്ഞിട്ട് പറഞ്ഞു: അങ്ങേക്ക് നൽകപ്പെട്ട രണ്ട് പ്രകാശങ്ങൾ കൊണ്ട് അങ്ങ് സന്തോഷിക്കുക. അങ്ങേക്ക് മുമ്പുള്ള ഒരു പ്രവാചകനും അവ നൽകപ്പെട്ടിട്ടില്ല. അത് ഫാതിഹതുൽ കിതാബും സൂറത്തുൽ ബഖറയുടെ അവസാനത്തെ ഭാഗവുമാണ്. അവയിൽ നിന്നൊരു അക്ഷരമോതിയാൽ അതിനർഹതപ്പെട്ടത് തീർച്ചയായും അങ്ങേക്ക് നൽകപ്പെടും. (മു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 547, 547, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "{الْحَمْدُ لِلَّه رَبِّ الْعَالَمِينَ} أُمُّ الْقُرْآنِ وَأُمُّ الْكِتَابِ، وَالسَّبْعُ الْمَثَانِي". (خ,د,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അൽഹംദുലില്ലാഹിറബ്വിൽആലമീൻ (സർവലോകരക്ഷിതാവായ അല്ലാഹുവിനാണ് സർവസ്തുതിയും) എന്നത് (ഫാതിഹ) ഖുർആന്റെയും കിതാബിന്റെയും മാതാവും സബ്ളുൽ മസാനിയുമാണ്." (ബു,ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','د','ت']::text[], array['ബു','ദ','തു']::text[], null, null, 547, 548, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ أَبِي سَعِيدِ بْنِ الْمُعَلَّى رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَرَّ بِهِ وَهُوَ يُصَلِّي، فَدَعَاهُ، قَالَ: فَصَلَّيْتُ ثُمَّ أَتَيْتُهُ، قَالَ: فَقَالَ: "مَا مَنَعَكَ أَنْ تُجِيبَنِي". قَالَ: كُنْتُ أُصَلِّي. قَالَ: "أَلَمْ يَقُلِ اللهُ عَزَّ وَجَلَّ: {يَا أَيُّهَا الَّذِينَ آمَنُوا اسْتَجِيبُوا لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمْ لِمَا يُحْيِيكُمْ} [الأنفال: ٢٤]. لَأُعَلِّمَنَّكَ أَعْظَمَ سُورَةٍ مِنَ الْقُرْآنِ – أَوْ فِي الْقُرْآنِ – قَبْلَ أَنْ أَخْرُجَ مِنَ الْمَسْجِدِ". قَالَ: قُلْتُ: يَا رَسُولَ اللهِ قَوْلُكَ، قَالَ: "{الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ} وَهِيَ السَّبْعُ الْمَثَانِي الَّتِي أُوتِيتُ، وَالْقُرْآنُ الْعَظِيمُ". (خ,د,ن,جه)', 'അബൂസഈദുബ്നുൽ മുഅല്ല(റ): അദ്ദേഹം നിസ്കരിച്ചുകൊണ്ടിരിക്കെ അദ്ദേഹത്തിനരികിലൂടെ നബി(സ) നടന്നുപോയി. നബി(സ) അദ്ദേഹത്തെ വിളിച്ചു. അബൂസഈദ്(റ) പറയുന്നു: ഞാൻ നിസ്കരിച്ചതിന് ശേഷം റസൂൽ(സ)യുടെ അടുത്തുചെന്നു. അപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "എനിക്കുത്തരം നൽകാൻ നിനക്ക് തടസ്സമായതെന്താണ്?" അദ്ദേഹം പറഞ്ഞു: ഞാൻ നിസ്കരിക്കുകയായിരുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു പറഞ്ഞിട്ടില്ലേ: ''വിശ്വാസികളേ, നിങ്ങൾക്ക് ജീവൻ നൽകുന്ന കാര്യത്തിലേക്ക് വിളിച്ചാൽ നിങ്ങൾ അല്ലാഹുവിനും അവന്റെ റസൂലിനും ഉത്തരം ചെയ്യുക.'' (അൻഫാൽ: 24) ഞാൻ പള്ളിയിൽ നിന്ന് പുറത്തുപോകുന്നതിന് മുമ്പ് ഖുർആനിലുള്ള ഏറ്റവും മഹത്തായൊരു സൂറത്ത് നിനക്ക് പഠിപ്പിച്ചുതരാം." അബൂസഈദ്(റ) പറയുന്നു: ഞാൻ പറഞ്ഞു: റസൂലേ, അങ്ങ് പറഞ്ഞുതന്നാലും. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അൽഹംദുലില്ലാഹി റബ്വിൽ ആലമീൻ (ഫാതിഹാ സൂറത്ത്). അതാണ് എനിക്ക് നൽകപ്പെട്ട സബ്ഉൽ മസാനിയും മഹത്തായ ഖുർആനും." (ബു,ദ,ന,ജ)', 'أَبِي سَعِيدِ بْنِ الْمُعَلَّى', 'അബൂസഈദുബ്നുൽ മുഅല്ല(റ)', null, null, array['خ','د','ن','جه']::text[], array['ബു','ദ','ന','ജ']::text[], 'الأنفال: ٢٤', null, 548, 548, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ خَرَجَ عَلَى أُبَيِّ بْنِ كَعْبٍ، فَقَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "يَا أُبَيُّ". وَهُوَ يُصَلِّي، فَالْتَفَتَ أُبَيٌّ فَلَمْ يُجِبْهُ، وَصَلَّى أُبَيٌّ فَخَفَّفَ، ثُمَّ انْصَرَفَ إِلَى رَسُول اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ فَقَالَ: السَّلَامُ عَلَيْكَ يَا رَسُولَ اللَّه. فَقَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "وَعَلَيْكَ السَّلَامُ، مَا مَنَعَكَ يَا أُبَيُّ أَنْ تُجِيبَنِي إِذْ دَعَوْتُكَ". فَقَالَ: يَا رَسُولَ اللَّه، إِنِّي كُنْتُ فِي الصَّلَاة. قَالَ: "أَفَلَمْ تَجِدْ فِيمَا أَوْحَى اللَّهُ إِلَيَّ أَنْ: {اسْتَجِيبُوا لِلَّه وَلِلرَّسُول إِذَا دَعَاكُمْ لِمَا يُحْيِيكُمْ} [الأنفال: ٢٤]". قَالَ: بَلَى، وَلَا أَعُودُ إِنْ شَاءَ اللَّهُ. قَالَ: "أَتُحِبُّ أَنْ أُعَلِّمَكَ سُورَةً، لَمْ يَنْزِلْ فِي التَّوْرَاة وَلَا فِي الْإِنْجِيلِ وَلَا فِي الزَّبُورِ وَلَا فِي الْفُرْقَان مِثْلُهَا". قَالَ: نَعَمْ، يَا رَسُولَ اللَّه. فَقَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "كَيْفَ تَقْرَأُ فِي الصَّلَاة". قَالَ: فَقَرَأَ أُمَّ الْقُرْآن. فَقَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "وَالَّذِي نَفْسِي بِيَدِه، مَا أُنْزِلَتْ فِي التَّوْرَاة وَلَا فِي الْإِنْجِيلِ وَلَا فِي الزَّبُورِ وَلَا فِي الْفُرْقَان مِثْلُهَا، وَإِنَّهَا سَبْعٌ مِنَ الْمَثَانِي وَالْقُرْآنُ الْعَظِيمُ الَّذِي أُعْطِيتُهُ". (ت,ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) ഉബയ്യുബ്നു കഅ്ബ്(റ)വിന്റെ അടുത്ത് ചെന്നു. റസൂൽ(സ) വിളിച്ചു: "ഉബയ്യേ." അദ്ദേഹം നിസ്കരിക്കുകയായിരുന്നു. ഉബയ്യ്(റ) തിരിഞ്ഞുനോക്കിയെങ്കിലും നബി(സ)ക്ക് മറുപടി നൽകിയില്ല. ഉബയ്യ്(റ) ലഘുവാക്കി നിസ്കരിച്ചു. പിന്നീട് റസൂൽ(സ)യുടെ അടുത്തുചെന്ന്, അല്ലാഹുവിന്റെ ദൂതരേ, അവിടുത്തേക്ക് അല്ലാഹുവിന്റെ രക്ഷയുണ്ടാവട്ടെ (അസ്സലാമു അലൈക്ക യാ റസൂലല്ലാഹ്) എന്ന് പറഞ്ഞു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിന്റെ മേലും അല്ലാഹുവിന്റെ രക്ഷയുണ്ടാവട്ടെ. ഉബയ്യേ, ഞാൻ നിന്നെ വിളിച്ചപ്പോൾ എനിക്കുത്തരം ചെയ്യാൻ നിനക്ക് തടസ്സമായതെന്താണ്?" ഉബയ്യ്(റ) പറഞ്ഞു: തിരുദൂതരേ, ഞാൻ നിസ്കാരത്തിലായിരുന്നു. റസൂൽ(സ) പറഞ്ഞു: "എനിക്ക് അല്ലാഹു വഹ്‌യ് ഇറക്കിയതിൽ ''നിങ്ങൾക്ക് ജീവൻ നൽകുന്ന കാര്യത്തിലേക്ക് നിങ്ങളെ വിളിച്ചാൽ അല്ലാഹുവിനും റസൂലിനും നിങ്ങൾ ഉത്തരം ചെയ്യുക'' എന്നത് നീ കണ്ടിട്ടില്ലേ." ഉബയ്യ്(റ) പറഞ്ഞു: അതെ. ഇൻശാഅല്ലാഹ്, ഇനി ഞാൻ അത് ആവർത്തിക്കില്ല. റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ നിനക്കൊരു സൂറത്ത് പഠിപ്പിച്ചുതരാൻ നീ ഇഷ്ടപ്പെടുന്നോ? ഫുർഖാനിലോ സബൂറിലോ തൗറാത്തിലോ ഇഞ്ചീലിലോ അതുപോലെയുള്ളത് ഇറക്കപ്പെട്ടിട്ടില്ല." ഉബയ്യ്(റ) പറഞ്ഞു: അതെ, റസൂലേ. അപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "നീ എങ്ങനെയാണ് നിസ്കാരത്തിൽ ഓതാറ്?" അബൂഹുറൈറ(റ) പറയുന്നു: അങ്ങനെ ഉബയ്യ്(റ) ഉമ്മുൽ ഖുർആൻ (ഫാതിഹ) ഓതി. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "എന്റെ ശരീരം ആരുടെ കയ്യിലാണോ, അവൻ തന്നെ സത്യം, ഫുർഖാനിലോ സബൂറിലോ ഇഞ്ചീലിലോ തൗറാത്തിലോ അതുപോലെയുള്ളത് അവതരിച്ചിട്ടില്ല. അതുതന്നെയാണ് സബ്ഉൽ മസാനിയും എനിക്ക് നൽകപ്പെട്ട മഹത്തായ ഖുർആനും." (തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], 'الأنفال: ٢٤', null, 548, 549, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "قَالَ اللَّهُ عَزَّ وَجَلَّ: قَسَمْتُ الصَّلَاةَ بَيْنِي وَبَيْنَ عَبْدِي شَطْرَيْنِ، فَنِصْفُهَا لِي وَنِصْفُهَا لِعَبْدِي، وَلِعَبْدِي مَا سَأَلَ". قَالَ: فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اقْرَءُوا: يَقُولُ الْعَبْدُ {الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ} فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ: حَمِدَنِي عَبْدِي، وَلِعَبْدِي مَا سَأَلَ. فَيَقُولُ: {الرَّحْمَنِ الرَّحِيمِ} فَيَقُولُ: أَثْنَى عَلَيَّ عَبْدِي، وَلِعَبْدِي مَا سَأَلَ. يَقُولُ: {مَالك يَوْمِ الدِّينِ} فَيَقُولُ اللَّهُ: مَجَّدَنِي عَبْدِي، فَهَذَا لِي. وَهَذِهِ الْآيَةُ بَيْنِي وَبَيْنَ عَبْدِي نِصْفَيْنِ، يَقُولُ الْعَبْدُ: {إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ} يَعْنِي: فَهَذِهِ بَيْنِي وَبَيْنَ عَبْدِي، وَلِعَبْدِي مَا سَأَلَ. وَآخِرُ السُّورَةِ لِعَبْدِي، يَقُولُ الْعَبْدُ: {اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ. صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ. غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ} فَهَذَا لِعَبْدِي، وَلِعَبْدِي مَا سَأَلَ". (م,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "അല്ലാഹു പറഞ്ഞു: എന്റെയും എന്റെ അടിമയുടെയുമിടയിൽ നിസ്കാരത്തെ രണ്ട് ഭാഗമായി ഞാൻ ഭാഗിച്ചു. അതിൽ പകുതി എനിക്കും പകുതി എന്റെ അടിമക്കുമാണ്. എന്റെ അടിമക്ക് അവൻ ചോദിച്ചത് ലഭിക്കും." അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ഓതുക: അടിമ പറയും: ''അൽഹംദു ലില്ലാഹി റബ്ബിൽ ആലമീൻ'' (സർവ്വലോക രക്ഷിതാവായ അല്ലാഹുവിനാണ് സർവ്വ സ്തുതിയും). അപ്പോൾ അല്ലാഹു പറയും: എന്റെ അടിമ എന്നെ സ്തുതിച്ചിരിക്കുന്നു. എന്റെ അടിമക്ക് അവൻ ചോദിച്ചതുണ്ട്. അടിമ പറയും: ''മാലികി യൗമിദ്ദീൻ'' (പ്രതിഫലദിനത്തിനുടമസ്ഥനായ അല്ലാഹു). അപ്പോൾ അല്ലാഹു പറയും: എന്റെ അടിമ എന്നെ ആദരിച്ചിരിക്കുന്നു. ഇത് എനിക്കുള്ളതാണ്. ഈ സൂക്തം എന്റെയും അടിമയുടെയുമിടയിൽ പകുതി വീതമാണ്. അടിമ പറയും: ''ഇയ്യാക്ക നഅ്ബുദു വഇയ്യാക്ക നസ്തഇൗൻ'' (നിന്നെ മാത്രം ഞങ്ങൾ ആരാധിക്കുന്നു. നിന്നോട് മാത്രം ഞങ്ങൾ സഹായം തേടുന്നു). അഥവാ, ഇത് എന്റെയും എന്റെ അടിമയുടെയും ഇടയിലുള്ളതാണ്. എന്റെ അടിമക്ക് അവൻ ചോദിച്ചതുണ്ട്. സൂറത്തിന്റെ അവസാനഭാഗം എന്റെ അടിമക്കുള്ളതാണ്. അടിമ പറയും: ''ഇഹ്ദിനസ്സ്വിറാത്വൽ മുസ്തഖീം, സ്വിറാത്വല്ലദീന അൻഅംത അലൈഹിം, ഗൈരിൽ മഅ്ളൂബി അലൈഹിം വലള്ളാല്ലീൻ.'' (ഞങ്ങളെ നേരായ മാർഗത്തിലേക്ക് നയിക്കേണമേ. നീ അനുഗ്രഹം ചെയ്തവരുടെ വഴിയേ, കോപം ലഭിച്ചവരുടെയും പിഴച്ചവരുടെയും വഴിയിലല്ല). ഇത് എന്റെ അടിമക്കുള്ളതാണ്. എന്റെ അടിമക്ക് അവൻ ചോദിച്ചത് ലഭിക്കും." (മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 549, 549, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أُوتِيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَبْعًا مِنَ الْمَثَانِي: السَّبْعَ الطُّوَلَ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ആവർത്തിക്കപ്പെടുന്നവയിൽ നിന്ന് ഏഴെണ്ണം നബി(സ)ക്ക് നൽകപ്പെട്ടു. അഥവാ സുദീർഘമായ ഏഴ് (അധ്യായങ്ങൾ). (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 549, 550, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا، فِي قَوْلِهِ عَزَّ وَجَلَّ: {سَبْعًا مِنَ الْمَثَانِي} قَالَ: السَّبْعُ الطُّوَلُ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): സബ്ഉൽ മസാനി (ആവർത്തിക്കപ്പെടുന്നവയിൽ ഏഴെണ്ണം) എന്ന അല്ലാഹുവിന്റെ വചനത്തെ സംബന്ധിച്ച് അദ്ദേഹം പറയുന്നു: അവ സുദീർഘമായ ഏഴ് അധ്യായങ്ങളാണ്. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 550, 550, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أُوتِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَبْعًا مِنَ الْمَثَانِي الطُّوَلَ، وَأُوتِيَ مُوسَى عَلَيْهِ السَّلَام سِتًّا، فَلَمَّا أَلْقَى الْأَلْوَاحَ رُفِعَتْ ثِنْتَانِ وَبَقِيَ أَرْبَعٌ. (د,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ആവർത്തിക്കപ്പെടുന്ന സുദീർഘമായ ഏഴ് അധ്യായങ്ങൾ റസൂൽ(സ)ക്ക് നൽകപ്പെട്ടിട്ടുണ്ട്. മൂസാ(അ)ന് ആറെണ്ണവും നൽകപ്പെട്ടു. മൂസാ(അ) ആ പലകകളെ (തൗറാത്ത് എഴുതിയ പലകകൾ) നിലത്തിട്ടപ്പോൾ രണ്ടെണ്ണം ഉയർത്തപ്പെടുകയും നാലെണ്ണം ശേഷിക്കുകയും ചെയ്തു. (ദ,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 550, 550, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَيَعْجِزُ أَحَدُكُمْ أَنْ يَقْرَأَ فِي لَيْلَةٍ ثُلُثَ الْقُرْآنِ". قَالُوا: وَكَيْفَ يَقْرَأُ ثُلُثَ الْقُرْآنِ؟ قَالَ: "{قُلْ هُوَ اللَّهُ أَحَدٌ} تَعْدِلُ ثُلُثَ الْقُرْآنِ". (م)', 'അബുദ്ദർദാഅ്: നബി(സ) ചോദിച്ചു: "ഒരു രാത്രിയിൽ ഖുർആനിന്റെ മൂന്നിലൊന്ന് പാരായണം ചെയ്യാൻ നിങ്ങളിലാരെങ്കിലും പ്രാപ്തിയില്ലാത്തവനാകുമോ?" അവർ ചോദിച്ചു: എങ്ങനെയാണൊരാൾ ഖുർആന്റെ മൂന്നിലൊന്ന് പാരായണം ചെയ്യുക? നബി(സ) പറഞ്ഞു: "ഖുൽഹുവല്ലാഹു അഹദ് എന്ന അധ്യായം ഖുർആന്റെ മൂന്നിലൊന്നിന് തുല്യമാണ്." (മു)', 'أَبِي الدَّرْدَاءِ', 'അബുദ്ദർദാഅ്', null, null, array['م']::text[], array['മു']::text[], null, null, 550, 550, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ رَجُلًا عَلَى سَرِيَّةٍ، وَكَانَ يَقْرَأُ لِأَصْحَابِهِ فِي صَلَاتِهِمْ، فَيَخْتِمُ بِـ {قُلْ هُوَ اللَّهُ أَحَدٌ}، فَلَمَّا رَجَعُوا ذُكِرَ ذَلِكَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "سَلُوهُ لِأَيِّ شَيْءٍ يَصْنَعُ ذَلِكَ". فَسَأَلُوهُ، فَقَالَ: لِأَنَّهَا صِفَةُ الرَّحْمَنِ، فَأَنَا أُحِبُّ أَنْ أَقْرَأَ بِهَا. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَخْبِرُوهُ أَنَّ اللَّهَ يُحِبُّهُ". (م)', 'ആഇശ(റ): റസൂൽ(സ) ഒരാളെ യുദ്ധത്തിനയച്ചു. അയാൾ തന്റെ അനുചരർക്ക് അവരുടെ നിസ്കാരത്തിൽ ഖുർആൻ ഓതുമ്പോഴൊക്കെ സൂറത്തുൽ ഇഖ്ലാസ് കൊണ്ടായിരുന്നു അവസാനിപ്പിച്ചിരുന്നത്. അവർ തിരിച്ചുവന്നപ്പോൾ റസൂൽ(സ)യോട് വിവരം പറഞ്ഞു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "എന്തുകൊണ്ടാണദ്ദേഹം അങ്ങനെ ചെയ്യുന്നതെന്ന് നിങ്ങൾ അദ്ദേഹത്തോട് ചോദിക്കുക." അങ്ങനെ അവർ ചോദിച്ചപ്പോൾ അദ്ദേഹം പറഞ്ഞു: കാരണം, അത് പരമകാരുണികനായ അല്ലാഹുവിന്റെ വിശേഷണമാണ്. അതിനാൽ അത് പാരായണം ചെയ്യാൻ ഞാൻ താൽപര്യപ്പെടുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അദ്ദേഹത്തെ അല്ലാഹു ഇഷ്ടപ്പെടുന്നുവെന്ന് നിങ്ങളദ്ദേഹത്തോട് പറയുക." (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 550, 550, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنْ أَبِي سَعِيد الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَجُلًا سَمِعَ رَجُلًا يَقْرَأُ: {قُلْ هُوَ اللَّهُ أَحَدٌ} يُرَدِّدُهَا، فَلَمَّا أَصْبَحَ جَاءَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَ ذَلِكَ لَهُ، وَكَأَنَّ الرَّجُلَ يَتَقَالُّهَا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "وَالَّذِي نَفْسِي بِيَدِهِ، إِنَّهَا لَتَعْدِلُ ثُلُثَ الْقُرْآنِ". (خ)', 'അബൂസഇൗദിൽ ഖുദ്‌രി(റ): ഒരാൾ സൂറത്തുൽ ഇഖ്ലാസ് ആവർത്തിച്ച് പാരായണം ചെയ്യുന്നത് മറ്റൊരാൾ കേട്ടു. പ്രഭാതമായപ്പോൾ അയാൾ റസൂൽ(സ)യുടെ സന്നിധിയിൽ ചെന്ന് വിവരം പറഞ്ഞു. അയാൾ ഇഖ്ലാസിനെ ചെറുതായി കണക്കാക്കിയ പോലെയായിരുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "എന്റെ ശരീരം ആരുടെ കയ്യിലാണോ അവൻ തന്നെ സത്യം, ഇഖ്ലാസ് ഖുർആന്റെ മൂന്നിലൊന്നിന് തുല്യമാണ്." (ബു)', 'أَبِي سَعِيد الْخُدْرِيِّ', 'അബൂസഇൗദിൽ ഖുദ്‌രി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 550, 551, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَقْبَلْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَسَمِعَ رَجُلًا يَقْرَأُ: {قُلْ هُوَ اللَّهُ أَحَدٌ. اللَّهُ الصَّمَدُ. لَمْ يَلِدْ وَلَمْ يُولَدْ. وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ} فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "وَجَبَتْ". فَسَأَلْتُهُ: مَاذَا يَا رَسُولَ اللَّهِ؟ قَالَ: "الْجَنَّةُ". (ن)', 'അബൂഹുറൈറ(റ): ഞാൻ നബി(സ)യുടെ കൂടെ പോയപ്പോൾ ഒരാൾ, ''നബിയേ, അങ്ങ് പറയുക: അല്ലാഹു ഒരുവനാണ്. അല്ലാഹു നിരാശ്രയനാണ്. അവൻ പ്രസവിക്കുകയോ പ്രസവിക്കപ്പെടുകയോ ചെയ്തിട്ടില്ല. അവന് തുല്യനായി ഒരാളുമില്ല'' (സൂറത്തുൽ ഇഖ്ലാസ്) എന്ന് പാരായണം ചെയ്യുന്നത് കേട്ടു.. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിർബന്ധമായിരിക്കുന്നു." അപ്പോൾ ഞാൻ റസൂൽ(സ)യോട് ചോദിച്ചു: എന്താണ് തിരുദൂതരേ നിർബന്ധമായിരിക്കുന്നത്? റസൂൽ(സ) പറഞ്ഞു: "സ്വർഗം." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 551, 551, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنْ أَبِي أَيُّوبَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "{قُلْ هُوَ اللَّهُ أَحَدٌ} ثُلُثُ الْقُرْآنِ". (ن)', 'അബൂഅയ്യൂബ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഖുൽഹുവല്ലാഹു അഹദ് എന്നത് (സൂറതുൽ ഇഖ്ലാസ്) ഖുർആന്റെ മൂന്നിലൊന്നാണ്." (ന)', 'أَبِي أَيُّوبَ', 'അബൂഅയ്യൂബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 551, 551, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ قَرَأَ كُلَّ يَوْمٍ مائَتَيْ مَرَّةٍ: {قُلْ هُوَ اللَّهُ أَحَدٌ} مُحِيَ عَنْهُ ذُنُوبُ خَمْسِينَ سَنَةً، إِلَّا أَنْ يَكُونَ عَلَيْهِ دَيْنٌ". وَقَالَ: "مَنْ أَرَادَ أَنْ يَنَامَ عَلَى فِرَاشِهِ، فَنَامَ عَلَى يَمِينِهِ، ثُمَّ قَرَأَ: {قُلْ هُوَ اللَّهُ أَحَدٌ} مائَةَ مَرَّةٍ، فَإِذَا كَانَ يَوْمُ الْقِيَامَةِ يَقُولُ لَهُ الرَّبُّ تَبَارَكَ وَتَعَالَى: يَا عَبْدِيَ، ادْخُلْ عَلَى يَمِينِكَ الْجَنَّةَ". (ت)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും ഒരു ദിവസം ഇരുനൂറ് പ്രാവശ്യം ''ഖുൽഹുവല്ലാഹു അഹദ്'' (ഇഖ്ലാസ്) ഓതിയാൽ അവന്റെ അമ്പത് വർഷത്തെ പാപങ്ങൾ മായ്ക്കപ്പെടും, അവന് കടമുണ്ടായാലൊഴികെ." നബി(സ) തുടർന്ന് പറഞ്ഞു: "ആരെങ്കിലും തന്റെ വിരിപ്പിലുറങ്ങാൻ ഉദ്ദേശിച്ചാൽ, അങ്ങനെ അവൻ വലതുഭാഗം ചെരിഞ്ഞുകിടന്ന് നൂറ് പ്രാവശ്യം ''ഖുൽഹുവല്ലാഹു അഹദ്'' ഓതിയാൽ പുനരുത്ഥാന നാളിൽ അവനോട് ഉന്നതനും മഹത്വമേറിയവനുമായ അല്ലാഹു പറയും: എന്റെ അടിമേ, നിന്റെ വലതുഭാഗത്ത് കൂടെ നീ സ്വർഗത്തിൽ പ്രവേശിക്കുക." (തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 551, 551, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "احْشُدُوا، فَإِنِّي سَأَقْرَأُ عَلَيْكُمْ ثُلُثَ الْقُرْآنِ". قَالَ: فَحَشَدَ مَنْ حَشَدَ، ثُمَّ خَرَجَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَرَأَ: {قُلْ هُوَ اللَّهُ أَحَدٌ} ثُمَّ دَخَلَ، فَقَالَ بَعْضُنَا لِبَعْضٍ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "فَإِنِّي سَأَقْرَأُ عَلَيْكُمْ ثُلُثَ الْقُرْآنِ". إِنِّي لَأَرَى هَذَا خَبَرًا جَاءَ مِنَ السَّمَاءِ. ثُمَّ خَرَجَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "إِنِّي قُلْتُ: سَأَقْرَأُ عَلَيْكُمْ ثُلُثَ الْقُرْآنِ. أَلَا، وَإِنَّهَا تَعْدِلُ ثُلُثَ الْقُرْآنِ". (م,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ഒത്തുകൂടി ആളുകളെ ഒരുമിച്ചുകൂട്ടുക. ഞാൻ നിങ്ങൾക്ക് ഖുർആന്റെ മൂന്നിലൊരു ഭാഗം ഓതിത്തരാം." അബൂഹുറൈറ(റ) പറഞ്ഞു: അങ്ങനെ ഒരുമിച്ചുകൂടിയവരെല്ലാം കൂടിനിന്നു. പിന്നെ നബി(സ) ഇറങ്ങിവന്ന് ഇഖ്ലാസ് ഓതി. ശേഷം അകത്തുപോയി. അപ്പോൾ ചിലർ പറഞ്ഞു: റസൂൽ(സ) പറഞ്ഞിട്ടുണ്ടല്ലോ: "നിങ്ങൾക്ക് ഖുർആന്റെ മൂന്നിലൊന്ന് ഓതിത്തരാം" എന്ന്. ആകാശത്തുനിന്ന് ഇറങ്ങിയ ഒരു വാർത്തയാണ് ഇതെന്ന് എനിക്ക് തോന്നുന്നു. പിന്നീട് റസൂൽ(സ) ഇറങ്ങിവന്ന് പറഞ്ഞു: "ഞാൻ പറഞ്ഞിരുന്നു: നിങ്ങൾക്ക് ഞാൻ ഖുർആന്റെ മൂന്നിലൊന്ന് ഓതിത്തരാമെന്ന്. അറിയുക, അത് (ഇഖ്ലാസ്) ഖുർആന്റെ മൂന്നിലൊന്നിന് തുല്യമാണ്." (മു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 551, 552, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَجُلٌ مِنَ الْأَنْصَارِ يَؤُمُّهُمْ فِي مَسْجِدِ قُبَاءَ، فَكَانَ كُلَّمَا افْتَتَحَ سُورَةً يَقْرَأُ لَهُمْ فِي الصَّلَاةِ، فَقَرَأَ بِهَا، افْتَتَحَ بِـ {قُلْ هُوَ اللَّهُ أَحَدٌ} حَتَّى يَفْرُغَ مِنْهَا، ثُمَّ يَقْرَأُ بِسُورَةٍ أُخْرَى مَعَهَا، وَكَانَ يَصْنَعُ ذَلِكَ فِي كُلِّ رَكْعَةٍ، فَكَلَّمَهُ أَصْحَابُهُ فَقَالُوا: إِنَّكَ تَقْرَأُ بِهَذِهِ السُّورَةِ، ثُمَّ لَا تَرَى أَنَّهَا تُجْزِئُكَ حَتَّى تَقْرَأَ بِسُورَةٍ أُخْرَى، فَإِمَّا أَنْ تَقْرَأَ بِهَا، وَإِمَّا أَنْ تَدَعَهَا وَتَقْرَأَ بِسُورَةٍ أُخْرَى. قَالَ: مَا أَنَا بِتَارِكِهَا، إِنْ أَحْبَبْتُمْ أَنْ أَؤُمَّكُمْ بِهَا فَعَلْتُ، وَإِنْ كَرِهْتُمْ تَرَكْتُكُمْ. وَكَانُوا يَرَوْنَهُ أَفْضَلَهُمْ، وَكَرِهُوا أَنْ يَؤُمَّهُمْ غَيْرُهُ، فَلَمَّا أَتَاهُمُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخْبَرُوهُ الْخَبَرَ، فَقَالَ: "يَا فُلَانُ، مَا يَمْنَعُكَ مِمَّا يَأْمُرُ بِهِ أَصْحَابُكَ؟ وَمَا يَحْمِلُكَ أَنْ تَقْرَأَ هَذِهِ السُّورَةَ فِي كُلِّ رَكْعَةٍ". فَقَالَ: يَا رَسُولَ اللَّهِ، إِنِّي أُحِبُّهَا. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ حُبَّهَا أَدْخَلَكَ الْجَنَّةَ". (خ,ت)', 'അനസുബ്നു മാലിക്(റ): ഖുബാഅ് പള്ളിയിൽ ജനങ്ങൾക്ക് ഇമാമത്ത് നിന്നിരുന്ന അൻസാറുകളിൽപെട്ട ഒരാൾ ഉണ്ടായിരുന്നു. നിസ്കാരത്തിൽ വല്ല സൂറത്തും അദ്ദേഹം ഓതാൻ തുടങ്ങുകയാണെങ്കിൽ സൂറത്തുൽ ഇഖ്ലാസ് കൊണ്ട് തുടങ്ങുകയും അത് കഴിഞ്ഞാൽ അതിനോട് കൂടെ വേറൊരു സൂറത്ത് ഓതുകയും ചെയ്യും. എല്ലാ റക്അത്തിലും അദ്ദേഹം അങ്ങനെ ചെയ്യുമായിരുന്നു. അങ്ങനെ തന്റെ കൂട്ടുകാർ അദ്ദേഹത്തോട് സംസാരിച്ചു. അവർ പറഞ്ഞു: നീ ഈ സൂറത്ത് ഓതുന്നു, ശേഷം അത് മതിയാകുന്നില്ലെന്ന് നിനക്ക് തോന്നുകയും വേറൊരു സൂറത്ത് കൂടെ ഓതുകയും ചെയ്യുന്നുവല്ലോ? ഒന്നുകിൽ നീ അത് ഓതുക. അല്ലെങ്കിൽ അതൊഴിവാക്കി വേറെ സൂറത്ത് ഓതുക. അദ്ദേഹം പറഞ്ഞു: ഞാനത് ഒഴിവാക്കുകയില്ല. അതോതിക്കൊണ്ട് നിങ്ങൾക്ക് ഞാൻ ഇമാമത്ത് നിൽക്കുന്നത് നിങ്ങൾ ഇഷ്ടപ്പെടുന്നുവെങ്കിൽ ഞാനത് ചെയ്യും. നിങ്ങൾക്ക് വെറുപ്പാണെങ്കിൽ ഞാൻ നിങ്ങളെ വിട്ടുപോയേക്കാം. അവരിൽ ഏറ്റവും ശ്രേഷ്ഠനായി അദ്ദേഹത്തെയായിരുന്നു അവർ കണ്ടിരുന്നത്. അദ്ദേഹമല്ലാതെ മറ്റാരെങ്കിലും അവർക്ക് ഇമാമത്ത് നിൽക്കുന്നത് അവർ വെറുത്തു. അങ്ങനെ നബി(സ) അവരുടെ അടുത്തേക്ക് ചെന്നപ്പോൾ അവർ നബി(സ)യോട് വിവരം പറഞ്ഞു. അപ്പോൾ അവിടുന്ന് ചോദിച്ചു: "എടോ, നിന്റെ കൂട്ടുകാർ കൽപ്പിക്കുന്നതിൽ നിന്നും നിന്നെ തടയുന്നതെന്താണ്? എല്ലാ റക്അത്തിലും ഈ സൂറത്ത് തന്നെ ഓതാൻ നിന്നെ പ്രേരിപ്പിക്കുന്നതെന്താണ്?" ഉടനെ അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാനതിനെ ഇഷ്ടപ്പെടുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അതിനോടുള്ള പ്രേമം നിന്നെ സ്വർഗത്തിൽ പ്രവേശിപ്പിച്ചിരിക്കുന്നു." (ബു,തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ','ت']::text[], array['ബു','തു']::text[], null, null, 552, 552, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَلَمْ تَرَ آيَاتٍ أُنْزِلَتِ اللَّيْلَةَ، لَمْ يُرَ مِثْلُهُنَّ قَطُّ: {قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ} وَ{قُلْ أَعُوذُ بِرَبِّ النَّاسِ}". (م)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഈ രാത്രിയിൽ അവതരിക്കപ്പെട്ട സൂക്തങ്ങൾ നീ കണ്ടില്ലേ. അതുപോലെയുള്ളത് ഇതുവരെ കാണപ്പെട്ടിട്ടില്ല: ഖുൽ അഊദു ബിറബ്ബിൽ ഫലഖ് എന്ന സൂറത്തും ഖുൽ അഊദു ബിറബ്ബിന്നാസ് എന്ന സൂറത്തുമാണവ." (മു)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 552, 552, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أُهْدِيَتْ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَغْلَةٌ شَهْبَاءُ فَرَكِبَهَا، وَأَخَذَ عُقْبَةُ يَقُودُهَا بِهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِعُقْبَةَ: "اقْرَأْ". قَالَ: وَمَا أَقْرَأُ يَا رَسُولَ اللَّهِ؟ قَالَ: "اقْرَأْ: {قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ. مِنْ شَرِّ مَا خَلَقَ}". فَأَعَادَهَا عَلَيَّ حَتَّى قَرَأْتُهَا، فَعَرَفَ أَنِّي لَمْ أَفْرَحْ بِهَا جِدًّا، قَالَ: "لَعَلَّكَ تَهَاوَنْتَ بِهَا". فَمَا قُمْتُ بِمِثْلِهَا.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=11 and h.hadith_no=80), 1, 'وَفِي رِوَايَةٍ: أَنَّهُ سَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمُعَوِّذَتَيْنِ؟ قَالَ عُقْبَةُ: فَأَمَّنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِهِمَا فِي صَلَاةِ الْغَدَاةِ.', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ)യോട് മുഅവ്വിദതൈനിയെ സംബന്ധിച്ച് അദ്ദേഹം ചോദിച്ചു. ഉഖ്ബ(റ) പറയുന്നു: സുബ്ഹി നിസ്കാരത്തിന് റസൂൽ(സ) ഞങ്ങൾക്ക് ഇമാമത്ത് നിന്നത് ഇവ രണ്ടും ഓതിക്കൊണ്ടായിരുന്നു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=11 and h.hadith_no=80), 2, 'وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَرَأَ بِهِمَا فِي صَلَاةِ الصُّبْحِ.', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) അവ രണ്ടും സുബ്ഹി നിസ്കാരത്തിൽ ഓതി.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=11 and h.hadith_no=80), 3, 'وَفِي رِوَايَةٍ: كُنْتُ أَقُودُ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي السَّفَرِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَا عُقْبَةُ، أَلَا أُعَلِّمُكَ خَيْرَ سُورَتَيْنِ قُرِئَتَا". فَعَلَّمَنِي: {قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ} وَ{قُلْ أَعُوذُ بِرَبِّ النَّاسِ}. فَلَمْ يَرَنِي سُرِرْتُ بِهِمَا جِدًّا، فَلَمَّا نَزَلَ لِصَلَاةِ الصُّبْحِ صَلَّى بِهِمَا صَلَاةَ الصُّبْحِ لِلنَّاسِ، فَلَمَّا فَرَغَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الصَّلَاةِ الْتَفَتَ إِلَيَّ فَقَالَ: "يَا عُقْبَةُ، كَيْفَ رَأَيْتَ".', 'മറ്റൊരു നിവേദനം: യാത്രയിൽ ഞാൻ റസൂൽ(സ)യെ ആനയിച്ചുകൊണ്ടിരിക്കുകയായിരുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഉഖ്ബാ, ഓതപ്പെട്ട ഏറ്റവും നല്ല രണ്ട് സൂറത്തുകൾ നിനക്ക് ഞാൻ പഠിപ്പിച്ചുതരട്ടെയോ." അങ്ങനെ റസൂൽ(സ) എനിക്ക് ''ഖുൽ അഊദു ബിറബ്ബിൽ ഫലഖ്'', ''ഖുൽ അഊദു ബിറബ്ബിന്നാസ്'' എന്നീ സൂറത്തുകൾ പഠിപ്പിച്ചുതന്നു. റസൂൽ(സ) എന്നെ അതീവ സന്തുഷ്ടനായി കണ്ടില്ല. സുബ്ഹി നിസ്കാരത്തിനിറങ്ങിയപ്പോൾ റസൂൽ(സ) ജനങ്ങൾക്ക് ഇവകൊണ്ടാണ് സുബ്ഹി നിസ്കരിച്ചത്. നിസ്കാരത്തിൽ നിന്നും വിരമിച്ചപ്പോൾ റസൂൽ(സ) എന്നിലേക്ക് തിരിഞ്ഞുചോദിച്ചു: "ഉഖ്ബാ, നിനക്കെങ്ങനെയാണ് അനുഭവപ്പെട്ടത്."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=11 and h.hadith_no=80), 4, 'وَفِي رِوَايَةٍ: بَيْنَا أَقُودُ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي نَقَبٍ مِنْ تِلْكَ النِّقَابِ إِذْ قَالَ: "أَلَا تَرْكَبُ يَا عُقْبَةُ". فَأَجْلَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ أَرْكَبَ مَرْكَبَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ قَالَ: "أَلَا تَرْكَبُ يَا عُقْبَةُ". فَأَشْفَقْتُ أَنْ يَكُونَ مَعْصِيَةً، فَنَزَلَ وَرَكِبْتُ هُنَيْهَةً. وَنَزَلْتُ، وَرَكِبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ قَالَ: "أَلَا أُعَلِّمُكَ سُورَتَيْنِ مِنْ خَيْرِ سُورَتَيْنِ قَرَأَ بِهِمَا النَّاسُ". فَأَقْرَأَنِي: {قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ} وَ{قُلْ أَعُوذُ بِرَبِّ النَّاسِ}. فَأُقِيمَتِ الصَّلَاةُ فَتَقَدَّمَ فَقَرَأَ بِهِمَا، ثُمَّ مَرَّ بِي فَقَالَ: "كَيْفَ رَأَيْتَ يَا عُقْبَةَ بْنَ عَامِرٍ؟ اقْرَأْ بِهِمَا كُلَّمَا نِمْتَ وَقُمْتَ".', 'മറ്റൊരു നിവേദനം: ആ പർവതത്തിനടിയിലുള്ള ഒരു വഴിയിലൂടെ ഞാൻ റസൂൽ(സ)യെ നയിച്ചുകൊണ്ടിരിക്കുമ്പോൾ അവിടുന്ന് ചോദിച്ചു: "നീ കയറുന്നില്ലേ ഉഖ്ബാ?" അപ്പോൾ റസൂൽ(സ)യുടെ വാഹനത്തിൽ കയറുന്നത് എനിക്ക് പ്രയാസകരമായി തോന്നി. പിന്നെയും റസൂൽ(സ) ചോദിച്ചു: "നീ കയറുന്നില്ലേ, ഉഖ്ബാ?" അന്നേരം, കയറാതിരിക്കുന്നത് തെറ്റാകുമോ എന്ന് ഞാൻ പേടിച്ചു. അങ്ങനെ റസൂൽ(സ) ഇറങ്ങി. അൽപനേരം ഞാൻ കയറി. പിന്നെ ഞാനിറങ്ങി. റസൂൽ(സ) കയറി. പിന്നെ ചോദിച്ചു: "ജനങ്ങൾ പാരായണം ചെയ്ത രണ്ട് സൂറത്തുകളിൽ ഏറ്റവും നല്ല രണ്ട് സൂറത്തുകൾ നിനക്ക് ഞാൻ പഠിപ്പിച്ചുതരട്ടെയോ?" എന്നിട്ട് ''ഖുൽ അഊദു ബിറബ്ബിൽ ഫലഖും'' ''ഖുൽ അഊദു ബിറബ്ബിന്നാസും'' എനിക്ക് ഓതിത്തന്നു. നിസ്കാരത്തിന് ഇഖാമത്ത് വിളിച്ചു. റസൂൽ(സ) കയറിനിന്ന് ഈ രണ്ട് സൂറത്തുകളും ഓതി. പിന്നെ എന്റെ അരികിലൂടെ നടന്നു, ചോദിച്ചു: "ഉഖ്ബതുബ്നു ആമിറേ, എങ്ങനെയുണ്ട്? നീ ഉറങ്ങുമ്പോഴും എഴുന്നേൽക്കുമ്പോഴൊക്കെ ഇതോതുക."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=11 and h.hadith_no=80), 5, 'وَفِي رِوَايَةٍ: كُنْتُ أَمْشِي مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "يَا عُقْبَةُ، قُلْ". فَقُلْتُ: مَاذَا أَقُولُ يَا رَسُولَ اللَّهِ؟ فَسَكَتَ عَنِّي، ثُمَّ قَالَ: "يَا عُقْبَةُ، قُلْ". قُلْتُ: مَاذَا أَقُولُ يَا رَسُولَ اللَّهِ؟ فَسَكَتَ عَنِّي، فَقُلْتُ: اللَّهُمَّ ارْدُدْهُ عَلَيَّ. فَقَالَ: "يَا عُقْبَةُ، قُلْ". قُلْتُ: مَاذَا أَقُولُ يَا رَسُولَ اللَّهِ؟ فَقَالَ: {قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ}. فَقَرَأْتُهَا حَتَّى أَتَيْتُ عَلَى آخِرِهَا، ثُمَّ قَالَ: "قُلْ". قُلْتُ: مَاذَا أَقُولُ يَا رَسُولَ اللَّهِ؟ قَالَ: {قُلْ أَعُوذُ بِرَبِّ النَّاسِ}. فَقَرَأْتُهَا حَتَّى أَتَيْتُ عَلَى آخِرِهَا، ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَ ذَلِكَ: "مَا سَأَلَ سَائِلٌ بِمِثْلِهِمَا، وَلَا اسْتَعَاذَ مُسْتَعِيذٌ بِمِثْلِهِمَا".', 'മറ്റൊരു നിവേദനം: ഉഖ്ബ(റ) പറഞ്ഞു: ഞാൻ റസൂൽ(സ)യോട് കൂടെ നടക്കുകയായിരുന്നു. റസൂൽ(സ) പറഞ്ഞു: "ഉഖ്ബാ, നീ പറയുക." ഞാൻ ചോദിച്ചു: ഞാനെന്താണ് പറയുക, അല്ലാഹുവിന്റെ റസൂലേ? അവിടുന്ന് മിണ്ടാതിരുന്നു. പിന്നെ പറഞ്ഞു: "ഉഖ്ബാ, നീ പറയുക." ഞാൻ ചോദിച്ചു: ഞാനെന്താണ് പറയുക, അല്ലാഹുവിന്റെ ദൂതരേ? അപ്പോഴും റസൂൽ(സ) മിണ്ടാതിരുന്നു. അപ്പോൾ ഞാൻ പറഞ്ഞു: അല്ലാഹുവാണെ, ഒരിക്കൽ കൂടി എനിക്കത് പറഞ്ഞുതരിക. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഉഖ്ബാ, നീ പറയുക." ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, ഞാനെന്താണ് പറയുക? അല്ലാഹുവിന്റെ ദൂതർ(സ) പറഞ്ഞു: "ഖുൽ അഊദു ബിറബ്ബിൽ ഫലഖ്."അപ്പോൾ ആ സൂറത്ത് അവസാനം വരെ ഞാൻ ഓതി. പിന്നെ പറഞ്ഞു: "നീ പറയുക." ഞാൻ ചോദിച്ചു: റസൂലേ, ഞാനെന്താണ് പറയേണ്ടത്? റസൂൽ(സ) പറഞ്ഞു: "ഖുൽ അഊദു ബിറബ്ബിന്നാസ്." അങ്ങനെ അതും അവസാനം വരെ ഞാനോതി. ആ സമയത്ത് റസൂൽ(സ) പറഞ്ഞു: "അവ പോലെയുള്ളതുകൊണ്ട്, ചോദിക്കുന്ന ഒരാളും ചോദിച്ചിട്ടില്ല. അഭയം തേടുന്ന ഒരാളും അവ പോലെയുള്ളതുകൊണ്ട് അഭയം തേടിയിട്ടില്ല."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=11 and h.hadith_no=80), 6, 'وَفِي رِوَايَةٍ: أَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ رَاكِبٌ، فَوَضَعْتُ يَدِي عَلَى قَدَمِهِ، فَقُلْتُ: أَقْرِئْنِي سُورَةَ هُودٍ، أَقْرِئْنِي سُورَةَ يُوسُفَ. فَقَالَ: "لَنْ تَقْرَأَ شَيْئًا أَبْلَغَ عِنْدَ اللَّهِ عَزَّ وَجَلَّ مِنْ: {قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ}".', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) യാത്രക്കാരനായിരിക്കെ ഞാൻ ചെന്നു. അങ്ങനെ റസൂൽ(സ)യുടെ പാദത്തിൽ എന്റെ കൈ വെച്ചു. ഞാൻ പറഞ്ഞു: എനിക്ക് ''ഹൂദ്'' സൂറത്ത് ഓതിത്തരിക. ''യൂസുഫ്'' സൂറത്ത് എനിക്കോതിത്തരിക. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഖുൽ അഊദു ബിറബ്ബിൽ ഫലഖ്''നേക്കാൾ അല്ലാഹുവിങ്കൽ മഹത്തരമായ ഒന്നും തന്നെ നീ ഓതുകയില്ല."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=11 and h.hadith_no=80), 7, 'وَفِي رِوَايَةٍ: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أُنْزِلَ عَلَيَّ آيَاتٌ لَمْ يُرَ مِثْلُهُنَّ: {قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ} إِلَى آخِرِ السُّورَةِ، وَ{قُلْ أَعُوذُ بِرَبِّ النَّاسِ} إِلَى آخِرِ السُّورَةِ". (م,د,ت,ن)', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) പറഞ്ഞു: "എനിക്ക് കുറച്ച് ആയത്തുകൾ ഇറക്കപ്പെട്ടു. അവപോലെയുള്ളത് കാണപ്പെട്ടിട്ടില്ല: ''ഖുൽ അഊദു ബിറബ്ബിൽ ഫലഖി''ന്റെ അവസാനം വരെയും, ''ഖുൽ അഊദു ബിറബ്ബിന്നാസി!''ന്റെ അവസാനം വരെയും." (മു,ദ,തു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنْ عَبْدِ اللهِ بْنِ خُبَيْبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَصَابَنَا طَشٌّ وَظُلْمَةٌ، فَانْتَظَرْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِيُصَلِّيَ بِنَا، فَخَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِيُصَلِّيَ بِنَا فَقَالَ: "قُلْ". فَقُلْتُ: مَا أَقُولُ؟ قَالَ: "{قُلْ هُوَ اللَّهُ أَحَدٌ} وَالْمُعَوِّذَتَيْنِ حِينَ تُمْسِي وَحِينَ تُصْبِحُ، ثَلَاثًا، يَكْفِيكَ كُلَّ شَيْءٍ". وَفِي رِوَايَةٍ قَالَ: كُنْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي طَرِيقِ مَكَّةَ، فَأَصَبْتُ خُلْوَةً مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَدَنَوْتُ مِنْهُ، فَقَالَ: "قُلْ". فَقُلْتُ: مَا أَقُولُ؟ قَالَ: "قُلْ". قُلْتُ: مَا أَقُولُ؟ قَالَ: {قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ} حَتَّى خَتَمَهَا، ثُمَّ قَالَ: {قُلْ أَعُوذُ بِرَبِّ النَّاسِ} حَتَّى خَتَمَهَا، ثُمَّ قَالَ: "مَا تَعَوَّذَ النَّاسُ بِأَفْضَلَ مِنْهُمَا". (ن)', 'അബ്ദുല്ലാഹിബ്നു ഖുബൈബ്(റ): ഞങ്ങൾക്ക് നേരിയ മഴ വർഷിക്കുകയും കൂരിരുട്ട് പരക്കുകയും ചെയ്തു. ഞങ്ങൾക്ക് നിസ്കരിക്കാൻ വേണ്ടി റസൂൽ(സ)യെ ഞങ്ങൾ പ്രതീക്ഷിച്ചിരിക്കുകയായിരുന്നു. അങ്ങനെ നിസ്കരിക്കാൻ വേണ്ടി റസൂൽ(സ) പുറപ്പെട്ടു. അവിടുന്ന് പറഞ്ഞു: "നീ പറയുക." അപ്പോൾ ഞാൻ ചോദിച്ചു: ഞാനെന്താണ് പറയേണ്ടത്? റസൂൽ(സ) പറഞ്ഞു: "നീ പ്രഭാതത്തിലും പ്രദോഷത്തിലും മൂന്ന് പ്രാവശ്യം സൂറത്തുൽ ഇഖ്ലാസും മുഅവ്വിദതൈനിയും ഓതുക. എന്നാൽ അത് നിനക്ക് എല്ലാ വസ്തുക്കളെയും മതിയാക്കിത്തരുന്നതാണ്."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=11 and h.hadith_no=81), 1, 'وَفِي رِوَايَةٍ قَالَ: كُنْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي طَرِيقِ مَكَّةَ، فَأَصَبْتُ خُلْوَةً مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَدَنَوْتُ مِنْهُ، فَقَالَ: "قُلْ". فَقُلْتُ: مَا أَقُولُ؟ قَالَ: "قُلْ". قُلْتُ: مَا أَقُولُ؟ قَالَ: {قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ} حَتَّى خَتَمَهَا، ثُمَّ قَالَ: {قُلْ أَعُوذُ بِرَبِّ النَّاسِ} حَتَّى خَتَمَهَا، ثُمَّ قَالَ: "مَا تَعَوَّذَ النَّاسُ بِأَفْضَلَ مِنْهُمَا". (ن)', 'മറ്റൊരു നിവേദനിൽ: ഞാൻ റസൂൽ(സ)യുടെ കൂടെ മക്കയിലെ ഒരു ഊടുവഴിയിലായിരുന്നു. എനിക്ക് റസൂൽ(സ)യെ ഏകാന്തനായി ലഭിച്ചപ്പോൾ ഞാൻ റസൂൽ(സ)യോടടുത്തുനിന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നീ പറയുക." ഞാൻ ചോദിച്ചു: ഞാനെന്താണ് പറയേണ്ടത്? അവിടുന്ന് പറഞ്ഞു: "നീ പറയുക." ഞാൻ ചോദിച്ചു: ഞാനെന്താണ് പറയേണ്ടത്? അപ്പോൾ റസൂൽ(സ) ''ഖുൽ അഊദു ബിറബ്ബിൽ ഫലഖ്'' അവസാനം വരെയും പിന്നെ ''ഖുൽ അഊദു ബിറബ്ബിന്നാസ്'' അവസാനം വരെയും ഓതി. എന്നിട്ട് റസൂൽ(സ) പറഞ്ഞു: "ഇവ രണ്ടിനേക്കാൾ ശ്രേഷ്ഠമായത് കൊണ്ട് ജനങ്ങൾ അഭയം തേടിയിട്ടില്ല." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَيْنَا أَنَا أَقُودُ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَاحِلَتَهُ فِي غَزْوَةٍ إِذْ قَالَ: "يَا عُقْبَةُ، قُلْ". فَاسْتَمَعْتُ، ثُمَّ قَالَ: "يَا عُقْبَةُ، قُلْ". فَاسْتَمَعْتُ، فَقَالَهَا الثَّالِثَةَ، فَقُلْتُ: مَا أَقُولُ؟ فَقَالَ: {قُلْ هُوَ اللَّهُ أَحَدٌ}. فَقَرَأَ السُّورَةَ حَتَّى خَتَمَهَا، ثُمَّ قَرَأَ: {قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ}. وَقَرَأْتُ مَعَهُ حَتَّى خَتَمَهَا، ثُمَّ قَرَأَ: {قُلْ أَعُوذُ بِرَبِّ النَّاسِ}. فَقَرَأْتُ مَعَهُ حَتَّى خَتَمَهَا، ثُمَّ قَالَ: "مَا تَعَوَّذَ بِمِثْلِهِنَّ أَحَدٌ". وَفِي رِوَايَةٍ: "لَمْ يَتَعَوَّذِ النَّاسُ بِمِثْلِهِنَّ. أَوْ: لَا يَتَعَوَّذُ النَّاسُ بِمِثْلِهِنَّ". (ن)', 'ഉഖ്ബതുബ്നു ആമിറുൽ ജുഹനി(റ): ഒരു യുദ്ധത്തിൽ റസൂൽ(സ)യുമായി അവിടുത്തെ വാഹനത്തെ ഞാൻ നയിച്ചുകൊണ്ടിരിക്കെ റസൂൽ(സ) പറഞ്ഞു: "ഓ ഉഖ്ബാ, നീ പറയുക." അപ്പോൾ ഞാൻ ശ്രദ്ധിച്ചുകേട്ടു. പിന്നെയും റസൂൽ(സ) പറഞ്ഞു: "ഉഖ്ബാ നീ പറയുക." അപ്പോഴും ഞാൻ ശ്രദ്ധിച്ചു കേട്ടു. അവിടുന്ന് മൂന്നാം പ്രാവശ്യവും അപ്രകാരം പറഞ്ഞു. അപ്പോൾ ഞാൻ ചോദിച്ചു: ഞാൻ എന്താണ് പറയേണ്ടത്? അവിടുന്ന് പറഞ്ഞു: ''ഖുൽഹുവല്ലാഹു അഹദ്'' (പറയുക; അവൻ അല്ലാഹു ഏകനാകുന്നു). അങ്ങനെ തിരുമേനി(സ) ആ അധ്യായം മുഴുവൻ ഓതി. ശേഷം ''ഖുൽ അഊദു ബിറബ്ബിൽ ഫലഖ്'' എന്ന അധ്യായം അവസാനംവരെയും അവിടുന്ന് ഓതി, ഞാനും അവിടുത്തോടൊപ്പം ഓതി. ശേഷം ''ഖുൽ അഊദു ബിറബ്ബിന്നാസ്'' എന്ന അധ്യായം അവസാനംവരെ ഓതി, ഞാനും അവിടുത്തോടൊപ്പം ഓതി. ശേഷം പറഞ്ഞു: "ഇവ പോലെയുള്ളതുകൊണ്ട് ഒരാളും കാവൽ തേടിയിട്ടില്ല." മറ്റൊരു നിവേദനം: "ഇവ പോലെയുള്ളതുകൊണ്ട് ജനങ്ങൾ കാവൽ തേടിയിട്ടില്ല. അല്ലെങ്കിൽ: ഇവ പോലെയുള്ളതുകൊണ്ട് ജനങ്ങൾ കാവൽ തേടുകയില്ല." (ന)', 'عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ', 'ഉഖ്ബതുബ്നു ആമിറുൽ ജുഹനി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 555, 555, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=11 and h.hadith_no=82), 1, 'وَفِي رِوَايَةٍ: "لَمْ يَتَعَوَّذِ النَّاسُ بِمِثْلِهِنَّ. أَوْ: لَا يَتَعَوَّذُ النَّاسُ بِمِثْلِهِنَّ". (ن)', 'മറ്റൊരു നിവേദനം: "ഇവ പോലെയുള്ളതുകൊണ്ട് ജനങ്ങൾ കാവൽ തേടിയിട്ടില്ല. അല്ലെങ്കിൽ: ഇവ പോലെയുള്ളതുകൊണ്ട് ജനങ്ങൾ കാവൽ തേടുകയില്ല." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنِ ابْنِ عَابِسٍ الْجُهَنِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهُ: "يَا ابْنَ عَابِسٍ، أَلَا أَدُلُّكَ – أَوْ قَالَ: أَلَا أُخْبِرُكَ – بِأَفْضَلِ مَا يَتَعَوَّذُ بِهِ الْمُتَعَوِّذُونَ". قَالَ: بَلَى يَا رَسُولَ اللَّهِ. قَالَ: "{قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ} وَ{قُلْ أَعُوذُ بِرَبِّ النَّاسِ} هَاتَيْنِ السُّورَتَيْنِ". (ن)', 'ഇബ്നുആബിസുൽ ജുഹനി(റ): റസൂൽ(സ) അദ്ദേഹത്തോട് പറഞ്ഞു: "ഇബ്നുആബിസേ, കാവൽ തേടുന്നവർ കാവൽ തേടാറുള്ള ഏറ്റവും ശ്രേഷ്ഠമായത് നിനക്ക് ഞാൻ പറഞ്ഞുതരട്ടെയോ?" അദ്ദേഹം പറഞ്ഞു: അതെ, തിരുദൂതരേ. റസൂൽ(സ) പറഞ്ഞു: "ഖുൽ അഊദു ബിറബ്ബിൽ ഫലഖ്, ഖുൽ അഊദു ബിറബ്ബിന്നാസ് എന്നീ രണ്ട് സൂറത്തുകളാണത്." (ന)', 'ابْنِ عَابِسٍ الْجُهَنِيِّ', 'ഇബ്നുആബിസുൽ ജുഹനി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 555, 556, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَمَرَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ أَقْرَأَ بِالْمُعَوِّذَتَيْنِ فِي دُبُرِ كُلِّ صَلَاةٍ. (ت)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): എല്ലാ നിസ്കാരത്തിന് പിറകെയും മുഅവ്വിദതൈനി ഓതാൻ നബി(സ) എന്നോട് കൽപിച്ചു. (തു)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 556, 556, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا أَوَى إِلَى فِرَاشِهِ كُلَّ لَيْلَةٍ جَمَعَ كَفَّيْهِ، ثُمَّ نَفَثَ فِيهِمَا فَقَرَأَ فِيهِمَا: {قُلْ هُوَ اللَّهُ أَحَدٌ} وَ{قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ} وَ{قُلْ أَعُوذُ بِرَبِّ النَّاسِ} ثُمَّ يَمْسَحُ بِهِمَا مَا اسْتَطَاعَ مِنْ جَسَدِهِ، يَبْدَأُ بِهِمَا عَلَى رَأْسِهِ وَوَجْهِهِ، وَمَا أَقْبَلَ مِنْ جَسَدِهِ، يَفْعَلُ ذَلِكَ ثَلَاثَ مَرَّاتٍ. (خ)', 'ആഇശ(റ): നബി(സ) എല്ലാ രാത്രിയും തന്റെ വിരിപ്പിലേക്ക് ചെന്നാൽ ഇരു മുൻകൈകളും കൂട്ടി, അതിൽ ഊതുകയും ശേഷം അതിൽ ഇഖ്ലാസ്, ഖുൽ അഊദുബിറബ്ബിൽ ഫലഖ്, ഖുൽ അഊദു ബിറബ്ബിന്നാസ് എന്നീ സൂറത്തുകൾ ഓതുകയും ചെയ്യുമായിരുന്നു. പിന്നെ അവകൊണ്ട് ശിരസ്സിൽ നിന്നും മുഖത്തുനിന്നും തുടങ്ങി, ശരീരത്തിന്റെ മുൻഭാഗങ്ങളിലും അങ്ങനെ ശരീരത്തിന്റെ മുഴുവൻ ഭാഗവും കഴിവിന്റെ പരമാവധി തടവും. അപ്രകാരം മൂന്ന് പ്രാവശ്യം ചെയ്യും. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 556, 556, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَيْنَا أَنَا أَسِيرُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَ الْجُحْفَةِ وَالْأَبْوَاءِ، إِذًا غَشِيَتْنَا رِيحٌ وَظُلْمَةٌ شَدِيدَةٌ، فَجَعَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَعَوَّذُ: {أَعُوذُ بِرَبِّ الْفَلَقِ} وَ{أَعُوذُ بِرَبِّ النَّاسِ} وَيَقُولُ: "يَا عُقْبَةُ، تَعَوَّذْ بِهِمَا، فَمَا تَعَوَّذَ مُتَعَوِّذٌ بِمِثْلِهِمَا". قَالَ: وَسَمِعْتُهُ يَؤُمُّنَا بِهِمَا فِي الصَّلَاةِ. (د)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): ഞാൻ റസൂൽ(സ)യുടെ കൂടെ ജുഹ്ഫക്കും അബവാഇനുമിടയിൽ നടന്നുകൊണ്ടിരിക്കെ ശക്തമായ ഇരുട്ടും കാറ്റും ഞങ്ങളെ പൊതിഞ്ഞു. അപ്പോൾ റസൂൽ(സ) ''ഖുൽ അഊദുബിറബ്ബിൽ ഫലഖ്'' കൊണ്ടും ''ഖുൽ അഊദുബിറബ്ബിന്നാസ്'' കൊണ്ടും കാവൽ തേടാൻ തുടങ്ങി. നബി(സ) പറയുന്നുണ്ടായിരുന്നു: "ഉഖ്ബാ, ഇവ രണ്ടുകൊണ്ടും നീ കാവൽ തേടുക. കാരണം കാവൽ ചോദിക്കുന്ന ഒരാളും അവ പോലെയുള്ളതു കൊണ്ട് കാവൽ തേടിയിട്ടില്ല." ഉഖ്ബ(റ) പറയുന്നു: അവ രണ്ടും റസൂൽ(സ) ഞങ്ങൾക്ക് ഇമാമായി നിസ്കരിക്കുമ്പോൾ ഓതുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്. (ദ)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 556, 556, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَعَثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعْثًا، وَهُمْ ذُو عَدَدٍ، فَاسْتَقْرَأَهُمْ، فَاسْتَقْرَأَ كُلَّ رَجُلٍ مِنْهُمْ مَا مَعَهُ مِنَ الْقُرْآنِ، فَأَتَى عَلَى رَجُلٍ مِنْهُمْ مِنْ أَحْدَثِهِمْ سِنًّا، فَقَالَ: "مَا مَعَكَ يَا فُلَانُ". قَالَ: مَعِي كَذَا وَكَذَا، وَسُورَةُ الْبَقَرَةِ. قَالَ: "أَمَعَكَ سُورَةُ الْبَقَرَةِ". قَالَ: نَعَمْ. قَالَ: "فَاذْهَبْ فَأَنْتَ أَمِيرُهُمْ". فَقَالَ رَجُلٌ مِنْ أَشْرَافِهِمْ: وَاللَّهِ يَا رَسُولَ اللَّهِ، مَا مَنَعَنِي أَنْ أَتَعَلَّمَ سُورَةَ الْبَقَرَةِ إِلَّا خَشْيَةَ أَلَّا أَقُومَ بِهَا. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "تَعَلَّمُوا الْقُرْآنَ وَاقْرَءُوهُ، فَإِنَّ مَثَلَ الْقُرْآنِ – لِمَنْ تَعَلَّمَهُ فَقَرَأَهُ وَقَامَ بِهِ – كَمَثَلِ جِرَابٍ مَحْشُوٍّ مِسْكًا، يَفُوحُ رِيحُهُ فِي كُلِّ مَكَانٍ، وَمَثَلُ مَنْ تَعَلَّمَهُ – فَيَرْقُدُ وَهُوَ فِي جَوْفِهِ – كَمَثَلِ جِرَابٍ وُكِئَ عَلَى مِسْكٍ". (ت)', 'അബൂഹുറൈറ(റ): തിരുദൂതർ(സ) ഒരു യുദ്ധസംഘത്തെ അയച്ചു. അവർ ധാരാളം പേരുണ്ടായിരുന്നു. റസൂൽ(സ) അവരോട് ഓതാനാവശ്യപ്പെട്ടു. അങ്ങനെ ഓരോരുത്തരും ഖുർആനിൽ നിന്ന് തനിക്കറിയാവുന്നത് ഓതി. അങ്ങനെ അവരിലേറ്റവും ചെറുപ്പക്കാരനായ ഒരാളുടെ ഊഴമെത്തിയപ്പോൾ അയാളോട് റസൂൽ(സ) ചോദിച്ചു: "എടോ, നിനക്കെന്തെല്ലാമറിയും?" അയാൾ പറഞ്ഞു: എനിക്ക് സൂറത്തുൽ ബഖറയും ഇന്നാലിന്ന സൂറത്തുകളും അറിയാം. റസൂൽ(സ) ചോദിച്ചു: "നിനക്ക് സൂറത്തുൽ ബഖറയറിയുമോ?" അദ്ദേഹം പറഞ്ഞു: അതെ. റസൂൽ(സ) പറഞ്ഞു: "എന്നാൽ നീ പോകുക. നീയാണവരുടെ നേതാവ്." അപ്പോൾ അവരിലെ ഉന്നതരിൽപ്പെട്ട ഒരാൾ പറഞ്ഞു: അല്ലാഹു തന്നെ സത്യം, റസൂലേ, മുറപോലെ കൊണ്ടുനടക്കാൻ കഴിയില്ലെന്ന് ഭയന്നാണ് സൂറത്തുൽ ബഖറ ഞാൻ പഠിക്കാതിരുന്നത്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ഖുർആൻ പഠിക്കുകയും അത് പാരായണം ചെയ്യുകയും ചെയ്യുക. കാരണം ഖുർആൻ പഠിക്കുകയും പാരായണം ചെയ്യുകയും അത് മുറപോലെ പാലിച്ചുപോരുകയും ചെയ്യുന്നവനെ സംബന്ധിച്ചിടത്തോളം ഖുർആന്റെ ഉപമ കസ്തൂരി നിറക്കപ്പെട്ട പാത്രംപോലെയാണ്. അതിന്റെ ഗന്ധം എല്ലാ സ്ഥലത്തും പരക്കും. ഖുർആൻ പഠിക്കുകയും അതകത്തുണ്ടായിരിക്കെ കിടന്നുറങ്ങുകയും ചെയ്യുന്നവനെ സംബന്ധിച്ചിടത്തോളം ഖുർആന്റെ ഉപമ കസ്തൂരി ഉണ്ടായിരിക്കെ അടക്കപ്പെട്ട പാത്രം പോലെയാണ്." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 556, 557, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَجْعَلُوا بُيُوتَكُمْ مَقَابِرَ، وَإِنَّ الْبَيْتَ الَّذِي تُقْرَأُ فِيهِ الْبَقَرَةُ لَا يَدْخُلُهُ الشَّيْطَانُ". (م,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ നിങ്ങളുടെ വീടുകളെ ശ്മശാനങ്ങളാക്കരുത്. സൂറത്തുൽ ബഖറ പാരായണം ചെയ്യപ്പെടുന്ന വീട്ടിൽ പിശാച് പ്രവേശിക്കുകയില്ല." (മു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 557, 557, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لِكُلِّ شَيْءٍ سَنَامٌ، وَإِنَّ سَنَامَ الْقُرْآنِ سُورَةُ الْبَقَرَةِ، وَفِيهَا آيَةٌ هِيَ سَيِّدَةُ آيِ الْقُرْآنِ، هِيَ آيَةُ الْكُرْسِيِّ". (ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "എല്ലാ വസ്തുവിനും ഒരു പൂഞ്ഞയുണ്ട്. എന്നാൽ ഖുർആന്റെ പൂഞ്ഞ ''അൽബഖറ'' സൂറത്താണ്. അതിലൊരു സൂക്തമുണ്ട്. അത് ഖുർആൻ സൂക്തങ്ങളുടെ നേതാവാണ്. ആ സൂക്തം ''ആയത്തുൽ കുർസി'' ആകുന്നു." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 557, 557, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ قَرَأَ {حم} الْمُؤْمِنَ، إِلَى: {إِلَيْهِ الْمَصِيرُ} وَآيَةَ الْكُرْسِيِّ، حِينَ يُصْبِحُ حُفِظَ بِهِمَا حَتَّى يُمْسِيَ، وَمَنْ قَرَأَهُمَا حِينَ يُمْسِي حُفِظَ بِهِمَا حَتَّى يُصْبِحَ". (ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും ഹാമീം അൽ മുഅ്മിൻ (സൂറത്തുൽ ഗാഫിർ) ''ഇലൈഹിൽ മസ്വീർ'' വരെയും ആയത്തുൽ കുർസിയും പ്രഭാതത്തിൽ ഓതിയാൽ പ്രദോഷംവരെ അതുകാരണം അവൻ സംരക്ഷിക്കപ്പെടും. ആരെങ്കിലും പ്രദോഷത്തിൽ അവ ഓതിയാൽ പ്രഭാതമാകുംവരെ അതുമൂലം അവൻ സംരക്ഷിക്കപ്പെടും." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 557, 557, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنْ أُبَيِّ بْنِ كَعْبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَبَا الْمُنْذِرِ، أَيُّ آيَةٍ مَعَكَ مِنْ كِتَابِ اللَّهِ أَعْظَمُ". قَالَ: قُلْتُ: اللَّهُ وَرَسُولُهُ أَعْلَمُ. قَالَ: "أَبَا الْمُنْذِرِ، أَيُّ آيَةٍ مَعَكَ مِنْ كِتَابِ اللَّهِ أَعْظَمُ". قَالَ: قُلْتُ: {اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ} [البقرة: ٢٥٥] قَالَ: فَضَرَبَ فِي صَدْرِي وَقَالَ: "لِيَهْنَ لَكَ يَا أَبَا الْمُنْذِرِ الْعِلْمُ". (م,د)', 'ഉബയ്യുബ്നു കഅ്ബ്(റ): റസൂൽ(സ) ചോദിച്ചു: "അബുൽ മുൻദിറേ, അല്ലാഹുവിന്റെ ഗ്രന്ഥത്തിൽ ഏറ്റവും മഹത്തായ സൂക്തമായി നിനക്കേതാണ് തോന്നുന്നത്?" ഉബയ്യ്(റ) പറയുന്നു: ഞാൻ പറഞ്ഞു: അല്ലാഹുവിനും അവന്റെ റസൂലിനുമാണ് കൂടുതൽ അറിയുക. നബി(സ) ചോദിച്ചു: "അബുൽ മുൻദിറേ, അല്ലാഹുവിന്റെ ഗ്രന്ഥത്തിൽ ഏത് സൂക്തമാണ് നിനക്ക് ഏറ്റവും മഹത്തായതായി തോന്നുന്നത്?" ഞാൻ പറഞ്ഞു: ''അല്ലാഹു ലാഇലാഹ ഇല്ലാ ഹുവൽ ഹയ്യുൽ ഖയ്യൂം'' (അല്ലാഹു, അവനല്ലാതെ ആരാധ്യനില്ല, എന്നെന്നും ജീവിച്ചിരിക്കുന്നവനും എല്ലാം നിയന്ത്രിക്കുന്നവനുമാണവൻ) (ബഖറ: 255) എന്ന സൂക്തം. ഉബയ്യ്(റ) പറയുന്നു: അപ്പോൾ റസൂൽ(സ) എന്റെ നെഞ്ചിലടിക്കുകയും "അബുൽ മുൻദിറേ, നിനക്ക് വിജ്ഞാനം എളുപ്പമാകട്ടെ" എന്ന് ആശംസിക്കുകയും ചെയ്തു. (മു,ദ)', 'أُبَيِّ بْنِ كَعْبٍ', 'ഉബയ്യുബ്നു കഅ്ബ്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], 'البقرة: ٢٥٥', null, 557, 558, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنْ أَبِي أَيُّوبَ الْأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ كَانَتْ لَهُ سَهْوَةٌ فِيهَا تَمْرٌ، فَكَانَتْ تَجِيءُ الْغُولُ، فَتَأْخُذُ مِنْهُ. قَالَ: فَشَكَا ذَلِكَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: "فَاذْهَبْ، فَإِذَا رَأَيْتَهَا فَقُلْ: بِسْمِ اللَّهِ، أَجِيبِي رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ". قَالَ: فَأَخَذَهَا، فَحَلَفَتْ أَنْ لَا تَعُودَ، فَأَرْسَلَهَا، فَجَاءَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "مَا فَعَلَ أَسِيرُكَ". قَالَ: حَلَفَتْ أَنْ لَا تَعُودَ. فَقَالَ: "كَذَبَتْ، وَهِيَ مُعَاوِدَةٌ لِلْكَذِبِ". قَالَ: فَأَخَذَهَا مَرَّةً أُخْرَى، فَحَلَفَتْ أَنْ لَا تَعُودَ، فَأَرْسَلَهَا، فَجَاءَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "مَا فَعَلَ أَسِيرُكَ". قَالَ: حَلَفَتْ أَنْ لَا تَعُودَ. فَقَالَ: "كَذَبَتْ، وَهِيَ مُعَاوِدَةٌ لِلْكَذِبِ". فَأَخَذَهَا، فَقَالَ: مَا أَنَا بِتَارِكك حَتَّى أَذْهَبَ بِك إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَقَالَتْ: إِنِّي ذَاكِرَةٌ لَكَ شَيْئًا: آيَةَ الْكُرْسِيِّ، اقْرَأْهَا فِي بَيْتِكَ، فَلَا يَقْرَبُكَ شَيْطَانٌ وَلَا غَيْرُهُ. قَالَ: فَجَاءَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "مَا فَعَلَ أَسِيرُكَ". قَالَ: فَأَخْبَرَهُ بِمَا قَالَتْ، قَالَ: "صَدَقَتْ، وَهِيَ كَذُوبٌ". (ت)', 'അബൂഅയ്യൂബിൽ അൻസ്വാരി(റ): അദ്ദേഹത്തിന് കാരക്ക സൂക്ഷിച്ചിരുന്ന ഒരു ചെറിയ മുറിയുണ്ടായിരുന്നു. പൊട്ടിച്ചെകുത്താൻ വന്ന് അതിൽ നിന്ന് കാരക്ക എടുത്തുകൊണ്ടുപോകുമായിരുന്നു. അപ്പോൾ അദ്ദേഹം നബി(സ)യോട് പരാതി പറഞ്ഞു. നബി(സ) പറഞ്ഞു: "നീ പോവുക. ഇനി അവളെ കണ്ടാൽ നീ ബിസ്മില്ലാഹി എന്നും, നീ നബി(സ)ക്ക് മറുപടി കൊടുക്കൂ എന്നും പറയുക." അബൂഅയ്യൂബ്(റ) പറയുന്നു: അദ്ദേഹമവളെ പിടികൂടിയപ്പോൾ ഇനി ചെയ്യില്ല എന്നവൾ സത്യംചെയ്തു. അപ്പോൾ അദ്ദേഹമവളെ വിട്ടയച്ചു. അങ്ങനെ അദ്ദേഹം നബി(സ)യുടെ അടുത്തു ചെന്നപ്പോൾ നബി(സ) ചോദിച്ചു: "നിന്റെ തടവുകാരി എന്താണ് ചെയ്തത്?" അദ്ദേഹം പറഞ്ഞു: അവളിനി ചെയ്യില്ല എന്ന് സത്യംചെയ്തിരിക്കുന്നു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അവൾ കളവ് പറഞ്ഞിരിക്കുന്നു. അവൾ കളവ് ആവർത്തിക്കുന്നവളാണ്." അബൂഅയ്യൂബ്(റ) പറയുന്നു: അങ്ങനെ അദ്ദേഹം അവളെ മറ്റൊരു പ്രാവശ്യം പിടികൂടി. അപ്പോഴും, ഇനി മടങ്ങിവരില്ലെന്ന് സത്യം ചെയ്തപ്പോൾ അദ്ദേഹം വിട്ടയച്ചു. ശേഷം അദ്ദേഹം നബി(സ)യുടെ അടുത്തു ചെന്നപ്പോൾ നബി(സ) ചോദിച്ചു: "നിന്റെ തടവുകാരി എന്താണ് ചെയ്തത്?" അദ്ദേഹം പറഞ്ഞു: ഇനി മടങ്ങിവരില്ല എന്ന് സത്യംചെയ്തിരിക്കുന്നു. നബി(സ) പറഞ്ഞു: "അവൾ കളവ് പറഞ്ഞിരിക്കുന്നു. ഇനിയും കളവ് ആവർത്തിക്കുന്നതാണ്." അങ്ങനെ വീണ്ടും അദ്ദേഹമവളെ പിടികൂടി. അദ്ദേഹം പറഞ്ഞു: ഇന്ന് നിന്നെ ഞാൻ റസൂൽ(സ)യുടെ സന്നിധിയിൽ കൊണ്ടുപോകാതെ വിടുകയില്ല. അപ്പോൾ പൊട്ടിച്ചെകുത്താൻ പറഞ്ഞു: ഞാൻ നിനക്കൊരു കാര്യം പറഞ്ഞുതരാം. ആയത്തുൽ കുർസിയാണത്. നിന്റെ വീട്ടിൽ നീയത് പാരായണം ചെയ്യുക. എന്നാൽ അവിടെ പിശാചോ മറ്റോ കടന്നുവരില്ല. അദ്ദേഹം പറയുന്നു: അയാൾ റസൂൽ(സ)യുടെ സന്നിധിയിൽ ചെന്ന് വിവരം പറഞ്ഞു. അപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "നിന്റെ തടവുകാരി എന്തുചെയ്തു?" ചെകുത്താൻ പറഞ്ഞതെല്ലാം അദ്ദേഹം നബി(സ)യോട് പറഞ്ഞു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അവൾ സത്യം പറഞ്ഞിരിക്കുന്നു. പക്ഷേ, അവൾ കള്ളം പറയുന്നവളാണ്." (തു)', 'أَبِي أَيُّوبَ الْأَنْصَارِيِّ', 'അബൂഅയ്യൂബിൽ അൻസ്വാരി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 558, 558, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللَّهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ اللَّهَ كَتَبَ كِتَابًا قَبْلَ أَنْ يَخْلُقَ السَّمَوَاتِ وَالْأَرْضَ بِأَلْفَيْ عَامٍ، أَنْزَلَ مِنْهُ آيَتَيْنِ خَتَمَ بِهِمَا سُورَةَ الْبَقَرَةِ، وَلَا يُقْرَءَانِ فِي دَارٍ ثَلَاثَ لَيَالٍ فَيَقْرَبُهَا شَيْطَانٌ". (ت)', 'നുഅ്മാനുബ്നു ബഷീർ(റ): നബി(സ) പറഞ്ഞു: "ആകാശങ്ങളെയും ഭൂമിയെയും സൃഷ്ടിക്കുന്നതിന് രണ്ടായിരം വർഷങ്ങൾക്ക് മുമ്പ് അല്ലാഹു ഒരു എഴുത്ത് എഴുതി. അതിൽ നിന്ന് അവൻ രണ്ട് ആയത്തുകൾ ഇറക്കുകയും അവകൊണ്ട് സൂറത്തുൽ ബഖറക്ക് വിരാമമിടുകയും ചെയ്തു. അവ ഒരു വീട്ടിൽ മൂന്ന് രാത്രികളിൽ ഓതപ്പെട്ടാൽ ആ വീട്ടിലേക്ക് പിശാച് പ്രവേശിക്കുകയില്ല." (തു)', 'النُّعْمَانِ بْنِ بَشِيرٍ', 'നുഅ്മാനുബ്നു ബഷീർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 559, 559, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنْ عَبْدِ اللهِ بْنِ يَزِيدَ قَالَ: سَأَلْتُ أَبَا مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ وَهُوَ يَطُوفُ بِالْبَيْتِ، فَقَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ قَرَأَ الْآيَتَيْنِ مِنْ آخِرِ سُورَةِ الْبَقَرَةِ فِي لَيْلَةٍ كَفَتَاهُ". (ق,د,ت,جه)', 'അബ്ദുല്ലാഹിബ്നു യസീദ്(റ): അബൂമസ്ഊദ്(റ) കഅ്ബയെ ത്വവാഫ് ചെയ്തുകൊണ്ടിരിക്കുമ്പോൾ ഞാനദ്ദേഹത്തോട് ചോദിച്ചു: അപ്പോഴദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) പറഞ്ഞിരിക്കുന്നു: "ആരെങ്കിലും രാത്രിയിൽ സൂറത്തുൽ ബഖറയുടെ അവസാനത്തെ രണ്ട് സൂക്തങ്ങൾ ഓതിയാൽ അവ അവന് മതിയായതാണ്." (ബു,മു,ദ,തു,ജ)', 'عَبْدِ اللهِ بْنِ يَزِيدَ قَالَ', 'അബ്ദുല്ലാഹിബ്നു യസീദ്(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 559, 559, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنِ النَّوَّاسِ بْنِ سَمْعَانَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَأْتِي الْقُرْآنُ وَأَهْلُهُ الَّذِينَ يَعْمَلُونَ بِهِ فِي الدُّنْيَا، تَقْدُمُهُ سُورَةُ الْبَقَرَةِ وَآلُ عِمْرَانَ". قَالَ نَوَّاسٌ: وَضَرَبَ لَهُمَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثَلَاثَةَ أَمْثَالٍ مَا نَسِيتُهُنَّ بَعْدُ، قَالَ: "يَأْتِيَانِ كَأَنَّهُمَا غَيَابَتَانِ، وَبَيْنَهُمَا شَرْقٌ، أَوْ كَأَنَّهُمَا غَمَامَتَانِ سَوْدَاوَانِ، أَوْ كَأَنَّهُمَا ظُلَّةٌ مِنْ طَيْرٍ صَوَافَّ، تُجَادِلَانِ عَنْ صَاحِبِهِمَا". (م,ت)', 'നവാസുബ്നു സംആൻ(റ): നബി(സ) പറഞ്ഞു: "വിശുദ്ധ ഖുർആനും, ദുൻയാവിൽ വെച്ച് ഖുർആൻ അനുസരിച്ച് സൽകർമങ്ങൾ ചെയ്ത ഖുർആന്റെ ആളുകളും വരും. അതിന്റെ മുമ്പിൽ സൂറത്തുൽ ബഖറയും ആലുഇംറാനും ഉണ്ടായിരിക്കും." നവാസ്(റ) പറയുന്നു: നബി(സ) അവക്ക് രണ്ടിനും മൂന്ന് ഉദാഹരണങ്ങൾ പറഞ്ഞു. ശേഷം ഞാനവ മറന്നിട്ടേയില്ല: "നിഴൽ വിരിക്കുന്ന രണ്ട് പുകപടലങ്ങൾ പോലെ അവരണ്ടും വരും. അവരണ്ടിനുമിടയിൽ ഒരു പ്രകാശവുമുണ്ടാകും. അല്ലെങ്കിൽ കറുത്തിരുണ്ട രണ്ട് മേഘക്കൂട്ടങ്ങൾ പോലെ, അല്ലെങ്കിൽ അവരണ്ടും ചിറകുകൾ വിരിച്ച് പറക്കുന്ന പക്ഷികളുടെ ഒരു കൂട്ടം പോലെയുണ്ട്. അവരണ്ടും അവയുടെ ആളുകൾക്ക് വേണ്ടി തർക്കിക്കും." (മു,തു)', 'النَّوَّاسِ بْنِ سَمْعَانَ', 'നവാസുബ്നു സംആൻ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 559, 559, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: بَيْنَمَا رَجُلٌ يَقْرَأُ سُورَةَ الْكَهْفِ إِذْ رَأَى دَابَّتَهُ تَرْكُضُ، فَنَظَرَ فَإِذَا مِثْلُ الْغَمَامَةِ أَوِ السَّحَابَةِ، فَأَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَ ذَلِكَ لَهُ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "تِلْكَ السَّكِينَةُ، نَزَلَتْ مَعَ الْقُرْآنِ، أَوْ: نَزَلَتْ عَلَى الْقُرْآنِ". (ق,ت)', 'ബറാഉബ്നുൽ ആസിബ്(റ): ഒരാൾ അൽകഹ്ഫ് സൂറത്ത് ഓതിക്കൊണ്ടിരിക്കുന്നതിനിടയിൽ അദ്ദേഹത്തിന്റെ മൃഗം ചാടിക്കളിക്കാൻ തുടങ്ങി. അദ്ദേഹം നോക്കിയപ്പോൾ മേഘം പോലെയുള്ള ഒരു വസ്തു കണ്ടു. ഉടനെ അദ്ദേഹം നബി(സ)യുടെ അടുക്കൽ ചെന്ന് വിവരം പറഞ്ഞു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഖുർആനിനോടു കൂടെ ഇറങ്ങിയ, അല്ലെങ്കിൽ ഖുർആനിനു മേൽ ഇറങ്ങിയ സമാധാനമാണത്." (ബു,മു,തു)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നുൽ ആസിബ്(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 559, 560, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ حَفِظَ عَشْرَ آيَاتٍ مِنْ أَوَّلِ سُورَةِ الْكَهْفِ عُصِمَ مِنْ [فِتْنَةِ] الدَّجَّالِ". وَفِي رِوَايَةٍ: "مِنْ آخِرِ الْكَهْفِ". (م)', 'അബുദ്ദർദാഅ്(റ): നിശ്ചയം നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും അൽകഹ്ഫ് സൂറത്തിന്റെ ആദ്യത്തിലുള്ള പത്ത് സൂക്തങ്ങൾ മനഃപാഠമാക്കിയാൽ ദജ്ജാലിന്റെ നാശത്തിൽ നിന്ന് അവൻ സംരക്ഷിക്കപ്പെട്ടിരിക്കുന്നു." മറ്റൊരു നിവേദനത്തിൽ "കഹ്ഫിന്റെ അവസാനത്തിലുള്ള" എന്നാണ്. (മു)', 'أَبِي الدَّرْدَاءِ', 'അബുദ്ദർദാഅ്(റ)', null, null, array['م']::text[], array['മു']::text[], 'فِتْنَةِ', null, 560, 560, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=11 and h.hadith_no=97), 1, 'وَفِي رِوَايَةٍ: "مِنْ آخِرِ الْكَهْفِ". (م)', 'മറ്റൊരു നിവേദനത്തിൽ "കഹ്ഫിന്റെ അവസാനത്തിലുള്ള" എന്നാണ്. (മു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ قَرَأَ ثَلَاثَ آيَاتٍ مِنْ أَوَّلِ الْكَهْفِ عُصِمَ مِنْ فِتْنَةِ الدَّجَّالِ". (م,د,ت)', 'അബുദ്ദർദാഅ്(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും സൂറത്തുൽ കഹ്ഫിന്റെ ആദ്യഭാഗത്തുള്ള മൂന്ന് ആയത്തുകൾ ഓതിയാൽ ദജ്ജാലിന്റെ ഫിത്നയിൽ നിന്നവൻ സംരക്ഷിക്കപ്പെട്ടിരിക്കുന്നു." (മു,ദ,തു)', 'أَبِي الدَّرْدَاءِ', 'അബുദ്ദർദാഅ്(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 560, 560, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ لِكُلِّ شَيْءٍ قَلْبًا، وَقَلْبُ الْقُرْآنِ {يس}. وَمَنْ قَرَأَ {يس} كَتَبَ اللَّهُ لَهُ بِقِرَاءَتِهَا قِرَاءَةَ الْقُرْآنِ عَشْرَ مَرَّاتٍ". (ت)', 'അനസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "എല്ലാ വസ്തുക്കൾക്കും ഒരു ഹൃദയമുണ്ട്. ഖുർആനിന്റെ ഹൃദയം യാസീൻ ആകുന്നു. ആരെങ്കിലും യാസീൻ ഓതിയാൽ പത്ത് പ്രാവശ്യം ഖുർആൻ ഓതിയതായി, അത് ഓതിയ കാരണത്താൽ അല്ലാഹു എഴുതും." (തു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 560, 560, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ قَرَأَ {حم} الدُّخَانَ فِي لَيْلَةٍ، أَصْبَحَ يَسْتَغْفِرُ لَهُ سَبْعُونَ أَلْفَ مَلَكٍ". (ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും രാത്രിയിൽ ''ഹാമീം അദ്ദുഖാൻ'' ഓതിയാൽ പ്രഭാതംവരെ എഴുപതിനായിരം മലക്കുകൾ അവന് വേണ്ടി പൊറുക്കലിനെ തേടിക്കൊണ്ടിരിക്കും." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 560, 560, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ قَرَأَ {حم} الدُّخَانَ فِي لَيْلَةِ الْجُمُعَةِ غُفِرَ لَهُ". (ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും വെള്ളിയാഴ്ചരാവിൽ ''ഹാമീം അദ്ദുഖാൻ'' ഓതിയാൽ അവന് പാപമോചനം ലഭിക്കും." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 560, 560, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: ضَرَبَ بَعْضُ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خِبَاءَهُ عَلَى قَبْرٍ، وَهُوَ لَا يَحْسَبُ أَنَّهُ قَبْرٌ، فَإِذَا فِيهِ إِنْسَانٌ يَقْرَأُ سُورَةَ: {تَبَارَكَ الَّذِي بِيَدِهِ الْمُلْكُ} حَتَّى خَتَمَهَا، فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنِّي ضَرَبْتُ خِبَائِي عَلَى قَبْرٍ، وَأَنَا لَا أَحْسِبُ أَنَّهُ قَبْرٌ، فَإِذَا فِيهِ إِنْسَانٌ يَقْرَأُ سُورَةَ: {تَبَارَكَ ...الْمُلْكُ} حَتَّى خَتَمَهَا؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هِيَ الْمَانِعَةُ، هِيَ الْمُنْجِيَةُ، تُنْجِيهِ مِنْ عَذَابِ الْقَبْرِ". (ت)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ)യുടെ അനുചരരിലൊരാൾ ഒരു ഖബറിന്മേൽ തനിക്ക് കുടിൽ പണിതു. അതൊരു ഖബ്റാണെന്ന് അദ്ദേഹമറിഞ്ഞിരുന്നില്ല. അപ്പോഴതാ ഒരു മനുഷ്യൻ ആ ഖബ്റിൽ നിന്ന് ''തബാറക..'' എന്നുതുടങ്ങുന്ന സൂറത്ത് ഓതുന്നു. അങ്ങനെ അദ്ദേഹം അതുമുഴുവൻ ഓതിത്തീർത്തു. സ്വഹാബി നബി(സ)യുടെ സന്നിധിയിൽ ചെന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാൻ ഒരു ഖബ്റിന്മേൽ എന്റെ കൂടാരം പണിതു. അതൊരു ഖബ്റാണെന്ന് ഞാനറിഞ്ഞിരുന്നില്ല. അപ്പോഴുണ്ട് ഒരു മനുഷ്യൻ അതിൽ നിന്ന് ''തബാറകല്ലദീ..'' എന്ന് തുടങ്ങുന്ന സൂറത്ത് ഓതുന്നു. അങ്ങനെ അദ്ദേഹം അത് മുഴുവൻ ഓതിത്തീർത്തു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ആ സൂറത്താണ് മാനിഅ (പ്രതിരോധിക്കുന്നത്), അതാണ് മുൻജിയ (രക്ഷപ്പെടുത്തുന്നത്). അത് അയാളെ ഖബ്ർ ശിക്ഷയിൽ നിന്ന് രക്ഷിക്കും." (തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 560, 561, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ سُورَةً مِنَ الْقُرْآنِ ثَلَاثُونَ آيَةً، شَفَعَتْ لِرَجُلٍ حَتَّى غُفِرَ لَهُ، وَهِيَ سُورَةُ: {تَبَارَكَ الَّذِي بِيَدِهِ الْمُلْكُ}". (د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഖുർആനിലെ ഒരു സൂറത്ത് മുപ്പത് ആയത്തുകളാണ്. അത് ഒരാൾക്ക് വേണ്ടി ശുപാർശ ചെയ്യുകയും അങ്ങനെ അയാളുടെ ദോഷങ്ങൾ പൊറുക്കപ്പെടുകയും ചെയ്തു. അത് ''തബാറകല്ലദീ...'' എന്ന സൂറത്താണ്." (ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 561, 561, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ لَا يَنَامُ حَتَّى يَقْرَأَ: {الم تَنْزِيلُ} وَ{تَبَارَكَ ...الْمُلْكُ}. (ت)', 'ജാബിർ(റ): ''അലിഫ് ലാം മീം തൻസീൽ'' സൂറത്തും ''തബാറകല്ലദീ..മുൽകു'' സൂറത്തും ഓതാതെ നബി(സ) ഉറങ്ങാറുണ്ടായിരുന്നില്ല. (തു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 561, 561, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ قَرَأَ {إِذَا زُلْزِلَتْ} عُدِلَتْ لَهُ بِنِصْفِ الْقُرْآنِ، وَمَنْ قَرَأَ: {قُلْ يَا أَيُّهَا الْكَافِرُونَ} عُدِلَتْ لَهُ بِرُبُعِ الْقُرْآنِ، وَمَنْ قَرَأَ: {قُلْ هُوَ اللَّهُ أَحَدٌ} عُدِلَتْ لَهُ بِثُلُثِ الْقُرْآنِ". (ت)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും ''ഇദാസുൽസിലത്'' ഓതിയാൽ അതവന് ഖുർആന്റെ പകുതിക്ക് തുല്യമാകും. ആരെങ്കിലും ''ഖുൽ യാ അയ്യുഹൽ കാഫിറൂൻ'' ഓതിയാൽ അത് അയാൾക്ക് ഖുർആനിന്റെ നാലിലൊന്നിന് തുല്യമാകും. ആരെങ്കിലും ''ഖുൽ ഹുവല്ലാഹു അഹദ്'' ഓതിയാൽ അത് അയാൾക്ക് ഖുർആനിന്റെ മൂന്നിലൊന്നിന് തുല്യമാകും." (തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 561, 561, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 106, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لِرَجُلٍ مِنْ أَصْحَابِهِ: "هَلْ تَزَوَّجْتَ يَا فُلَانُ". قَالَ: لَا وَاللَّهِ يَا رَسُولَ اللَّهِ، وَلَا عِنْدِي مَا أَتَزَوَّجُ بِهِ. قَالَ: "أَلَيْسَ مَعَكَ {قُلْ هُوَ اللَّهُ أَحَدٌ}". قَالَ: بَلَى. قَالَ: "ثُلُثُ الْقُرْآنِ". قَالَ: "أَلَيْسَ مَعَكَ {إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ}". قَالَ: بَلَى. قَالَ: "رُبُعُ الْقُرْآنِ". قَالَ: "أَلَيْسَ مَعَكَ {قُلْ يَا أَيُّهَا الْكَافِرُونَ}". قَالَ: بَلَى. قَالَ: "رُبُعُ الْقُرْآنِ". قَالَ: "أَلَيْسَ مَعَكَ {إِذَا زُلْزِلَتِ الْأَرْضُ}". قَالَ: بَلَى. قَالَ: "رُبُعُ الْقُرْآنِ". قَالَ: "تَزَوَّجْ، وَتَزَوَّجْ". (ت)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) അവിടുത്തെ ഒരു അനുയായിയോട് ചോദിച്ചു: "മനുഷ്യാ, താങ്കൾ വിവാഹം കഴിച്ചിട്ടുണ്ടോ?" അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവാണെ, ഞാൻ വിവാഹം കഴിച്ചിട്ടില്ല, റസൂലേ. വിവാഹം കഴിക്കാനാവശ്യമായ ഒന്നും എന്റെ കയ്യിലില്ല താനും. അവിടുന്ന് ചോദിച്ചു: "ഖുൽ ഹുവല്ലാഹു അഹദ്'' നിന്റെ കൂടെയില്ലേയോ?" അദ്ദേഹം പറഞ്ഞു: അതെ. അവിടുന്ന് പറഞ്ഞു: "അത് ഖുർആന്റെ മൂന്നിലൊന്നാണ്." തിരുമേനി(സ) ചോദിച്ചു: "ഇദാ ജാഅ നസ്റുല്ലാഹി വൽ ഫത്ഹ്'' നിന്റെ കൂടെയില്ലേയോ?" അദ്ദേഹം പറഞ്ഞു: അതെ. നബി(സ) പറഞ്ഞു: "അത് ഖുർആന്റെ നാലിലൊന്നാണ്." അവിടുന്ന് ചോദിച്ചു: "ഖുൽയാ അയ്യുഹൽ കാഫിറൂൻ'' നിന്റെ കൂടെയില്ലേയോ?" അദ്ദേഹം പറഞ്ഞു: അതെ. അവിടുന്ന് പറഞ്ഞു: "അത് ഖുർആന്റെ നാലിലൊന്നാണ്." അവിടുന്ന് ചോദിച്ചു: "ഇദാ സുൽസിലത്'' നിന്റെ കൂടെയില്ലേയോ?" അദ്ദേഹം പറഞ്ഞു: അതെ. അവിടുന്ന് പറഞ്ഞു: "അത് ഖുർആന്റെ നാലിലൊന്നാണ്." തുടർന്ന് പറഞ്ഞു: "നീ വിവാഹം കഴിക്കുക. നീ വിവാഹം കഴിക്കുക." ഹദീസ് ഹസനാകുന്നു. (തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 561, 562, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 107, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أَتَى رَجُلٌ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: أَقْرِئْنِي يَا رَسُولَ اللَّهِ، فَقَالَ: "اقْرَأْ ثَلَاثًا مِنْ ذَوَاتِ {الر}". فَقَالَ: كَبُرَتْ سِنِّي وَاشْتَدَّ قَلْبِي وَغَلُظَ لِسَانِي. قَالَ: "فَاقْرَأْ ثَلَاثًا مِنْ ذَوَاتِ {حم}". فَقَالَ مِثْلَ مَقَالَتِهِ، فَقَالَ: "اقْرَأْ ثَلَاثًا مِنَ الْمُسَبِّحَاتِ". فَقَالَ مِثْلَ مَقَالَتِهِ، فَقَالَ الرَّجُلُ: يَا رَسُولَ اللَّهِ، أَقْرِئْنِي سُورَةً جَامِعَةً. فَأَقْرَأَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: {إِذَا زُلْزِلَتِ الْأَرْضُ} حَتَّى فَرَغَ مِنْهَا، فَقَالَ الرَّجُلُ: وَالَّذِي بَعَثَكَ بِالْحَقِّ، لَا أَزِيدُ عَلَيْهَا أَبَدًا. ثُمَّ أَدْبَرَ الرَّجُلُ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَفْلَحَ الرُّوَيْجِلُ". مَرَّتَيْنِ. (د,ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): ഒരാൾ റസൂൽ(സ)യുടെ അടുക്കൽ വന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാൻ എന്താണ് ഓതേണ്ടതെന്ന് അവിടുന്ന് എനിക്ക് പറഞ്ഞുതന്നാലും. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "അലിഫ് ലാം റാഅ് എന്നു തുടങ്ങുന്ന സൂറത്തുകളിൽ നിന്ന് മൂന്നെണ്ണം നീ ഓതുക." അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: നിശ്ചയം എനിക്ക് വാർദ്ധക്യം പിടിപെട്ടിരിക്കുന്നു. എന്റെ ഹൃദയം ക്ഷീണിച്ചിരിക്കുന്നു. എന്റെ നാവ് കഠിനമായിരിക്കുന്നു. റസൂൽ(സ) പറഞ്ഞു: "ഹാമീം എന്ന് തുടങ്ങുന്ന സൂറത്തുകളിൽ നിന്ന് മൂന്നെണ്ണം നീ ഓതുക." അപ്പോഴുമദ്ദേഹം മുമ്പ് പറഞ്ഞതുപോലെ പറഞ്ഞു. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "മുസബ്ബിഹാത്തിൽ നിന്ന് (സബ്ബഹ, യുസബ്ബിഹു എന്നിവ കൊണ്ട് തുടങ്ങുന്ന സൂറത്തുകൾ) മൂന്നെണ്ണം നീ ഓതുക." അപ്പോഴുമദ്ദേഹം മുമ്പുപറഞ്ഞത് പോലെ പറഞ്ഞു. എന്നിട്ടദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എല്ലാത്തിന്റെയും രത്നച്ചുരുക്കമായ ഒരു സൂറത്ത് അങ്ങെനിക്ക് പറഞ്ഞുതന്നാലും. അപ്പോൾ റസൂൽ(സ) അദ്ദേഹത്തിന് ''ഇദാസുൽസിലത്'' എന്ന സൂറത്ത് മുഴുവനായും ഓതിക്കൊടുത്തു. അപ്പോഴദ്ദേഹം പറഞ്ഞു: സത്യവുമായി അങ്ങയെ അയച്ചവൻ തന്നെയാണ്, ഇതിനേക്കാൾ ഞാൻ ഒന്നും വർദ്ധിപ്പിക്കുകയില്ല. പിന്നെയദ്ദേഹം തിരിച്ചുപോയി. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ആ മനുഷ്യൻ വിജയിച്ചിരിക്കുന്നു." അവിടുന്ന് ഇത് രണ്ട് പ്രാവശ്യം പറഞ്ഞു. (ദ,ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 562, 562, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 108, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَا يَنَامُ عَلَى فِرَاشِهِ حَتَّى يَقْرَأَ بَنِي إِسْرَائِيلَ وَالزُّمَرَ. (ت,ن)', 'ആഇശ(റ): ബനൂഇസ്റാഈൽ, സുമർ എന്നീ സൂറത്തുകൾ ഓതാതെ നബി(സ) തന്റെ വിരിപ്പിൽ ഉറങ്ങാറുണ്ടായിരുന്നില്ല. (തു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 562, 562, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 109, 'عَنْ عِرْبَاضِ بْنِ سَارِيَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقْرَأُ الْمُسَبِّحَاتِ قَبْلَ أَنْ يَرْقُدَ، وَيَقُولُ: "إِنَّ فِيهِنَّ آيَةً خَيْرٌ مِنْ أَلْفِ آيَةٍ". (ت)', 'ഇർബാളുബ്നു സാരിയ(റ): നബി(സ) ഉറങ്ങുന്നതിന് മുമ്പായി മുസബ്ബിഹാത് ഓതാറുണ്ടായിരുന്നു. അവിടുന്ന് പറയുമായിരുന്നു: "ആയിരം സൂക്തങ്ങളേക്കാൾ ശ്രേഷ്ഠമായ ഒരു സൂക്തം അവയിലുണ്ട്." (തു)', 'عِرْبَاضِ بْنِ سَارِيَةَ', 'ഇർബാളുബ്നു സാരിയ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 563, 563, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 110, 'عَنْ مَعْقِلِ بْنِ يَسَارٍ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ قَالَ حِينَ يُصْبِحُ ثَلَاثَ مَرَّاتٍ: أَعُوذُ بِاللَّهِ السَّمِيعِ الْعَلِيمِ مِنَ الشَّيْطَانِ الرَّجِيمِ، وَقَرَأَ ثَلَاثَ آيَاتٍ مِنْ آخِرِ سُورَةِ الْحَشْرِ، وَكَّلَ اللَّهُ بِهِ سَبْعِينَ أَلْفَ مَلَكٍ يُصَلُّونَ عَلَيْهِ حَتَّى يُمْسِيَ، وَإِنْ مَاتَ فِي ذَلِكَ الْيَوْمِ مَاتَ شَهِيدًا، وَمَنْ قَالَهَا حِينَ يُمْسِي كَانَ بِتِلْكَ الْمَنْزِلَةِ". (ت)', 'മഅ്ഖലുബ്നു യസാർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും പ്രഭാതസമയത്ത് ''അഊദുബില്ലാഹിസ്സമീഇൽ അലീം, മിനശ്ശൈത്വാനി റജീം'' (എല്ലാം കേൾക്കുന്നവനും സർവജ്ഞനുമായ അല്ലാഹുവിനെക്കൊണ്ട് ഞാൻ ആട്ടിയോടിക്കപ്പെട്ട പിശാചിൽ നിന്ന് കാവൽതേടുന്നു) എന്ന് മൂന്ന് പ്രാവശ്യം പറയുകയും ഹശ്ർ സൂറത്തിന്റെ അവസാനത്തിലുള്ള മൂന്ന് സൂക്തങ്ങൾ ഓതുകയും ചെയ്താൽ, പ്രദോശം വരേക്കും അവന് നന്മകൾ നേരുന്ന എഴുപതിനായിരം മലക്കുകളെ അല്ലാഹു അവന് ഏൽപിച്ചുകൊടുക്കും. അവൻ ആ ദിവസം മരിക്കുകയാണെങ്കിൽ ശഹീദിന്റെ സ്ഥാനത്തായിരിക്കും. ആരെങ്കിലും ഈ സൂക്തം പ്രദോശസമയത്ത് പറഞ്ഞാൽ അവനും അതേ സ്ഥാനത്താണ്." (തു)', 'مَعْقِلِ بْنِ يَسَارٍ', 'മഅ്ഖലുബ്നു യസാർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 563, 563, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 111, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُقْرِئُنَا الْقُرْآنَ عَلَى كُلِّ حَالٍ، مَا لَمْ يَكُنْ جُنُبًا. (د,ت,ن,جه)', 'അലി(റ): വലിയ അശുദ്ധിയില്ലാത്ത എല്ലാ സമയത്തും നബി(സ) ഞങ്ങൾക്ക് ഖുർആൻ പാരായണം ചെയ്തു തരാറുണ്ടായിരുന്നു. (ദ,തു,ന,ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 563, 563, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 112, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَمِعَ رَجُلًا يَقْرَأُ مِنَ اللَّيْلِ، فَقَالَ: "يَرْحَمُهُ اللَّهُ، لَقَدْ أَذْكَرَنِي كَذَا وَكَذَا آيَةً، كُنْتُ أَسْقَطْتُهَا مِنْ سُورَةِ كَذَا وَكَذَا". (م)', 'ആഇശ(റ): ഒരാൾ രാത്രി ഖുർആൻ ഓതുന്നത് നബി(സ) കേട്ടു: അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "അദ്ദേഹത്തിനല്ലാഹു കരുണ ചെയ്യട്ടെ. അയാളെന്നെ ഇന്ന സൂക്തം ഓർമിപ്പിച്ചിരിക്കുന്നു. ഇന്ന സൂറത്തിൽ നിന്ന് ഞാനത് (അറിയാതെ) വിട്ടുകളഞ്ഞിരുന്നു." (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 563, 563, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 113, 'عَنْ فَاطِمَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: أَسَرَّ إِلَيَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَنَّ جِبْرِيلَ كَانَ يُعَارِضُنِي بِالْقُرْآنِ كُلَّ سَنَةٍ، وَإِنَّهُ عَارَضَنِي الْعَامَ مَرَّتَيْنِ، وَلَا أُرَاهُ إِلَّا حَضَرَ أَجَلِي". (خ)', 'ഫാത്തിമ(റ): നബി(സ) എന്നോട് ഇപ്രാകാരം രഹസ്യം പറഞ്ഞു: "ജിബ്രീൽ(അ) എല്ലാ വർഷവും ഒരു പ്രാവശ്യം ഖുർആൻ എനിക്ക് വെളിവാക്കിത്തരാറുണ്ട്. ഈ വർഷം ജിബ്രീൽ(അ) രണ്ട് പ്രാവശ്യം എനിക്കത് വെളിവാക്കിത്തന്നിട്ടുണ്ട്. എന്റെ വേർപാട് അടുത്തിരിക്കുന്നുവെന്നതല്ലാതെ മറ്റൊരഭിപ്രായവും അതേക്കുറിച്ച് എനിക്കില്ല." (ബു)', 'فَاطِمَةَ', 'ഫാത്തിമ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 563, 564, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 114, 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: وَاللَّهِ لَقَدْ أَخَذْتُ مِنْ فِي رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِضْعًا وَسَبْعِينَ سُورَةً. (خ)', 'ഇബ്നുമസ്ഊദ്(റ): അല്ലാഹുവാണെ, റസൂൽ(സ)യുടെ വായിൽ നിന്ന് ഞാൻ എഴുപതിൽ പരം സൂറത്തുകൾ കരസ്ഥമാക്കിയിട്ടുണ്ട്. (ബു)', 'ابْنِ مَسْعُودٍ', 'ഇബ്നുമസ്ഊദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 564, 564, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 115, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: هَجَّرْتُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمًا، قَالَ: فَسَمِعَ أَصْوَاتَ رَجُلَيْنِ اخْتَلَفَا فِي آيَةٍ، فَخَرَجَ عَلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُعْرَفُ فِي وَجْهِهِ الْغَضَبُ، فَقَالَ: "إِنَّمَا هَلَكَ مَنْ كَانَ قَبْلَكُمْ بِاخْتِلَافِهِمْ فِي الْكِتَابِ". (م)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): ഞാനൊരു ദിവസം റസൂൽ(സ)യുടെ സമീപം ചെന്നു. നിവേദകൻ പറയുന്നു: ഒരു സൂക്തത്തെക്കുറിച്ച് രണ്ടുപേർ പരസ്പരം തർക്കിക്കുന്ന ശബ്ദം അവിടുന്ന് കേട്ടു. ഉടനെ അവിടുന്ന് ഞങ്ങളുടെയടുത്തേക്ക് വന്നു. അവിടുത്തെ മുഖത്ത് ദേഷ്യം പ്രകടമായിരുന്നു. അവിടുന്ന് പറഞ്ഞു: "നിശ്ചയം നിങ്ങളുടെ മുൻഗാമികൾ നശിച്ചത് അല്ലാഹുവിന്റെ ഗ്രന്ഥത്തിൽ അവർ ഭിന്നാഭിപ്രായക്കാരായത് കൊണ്ടുമത്രമാണ്." (മു)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 564, 564, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 116, 'عَنْ جُنْدَبِ بْنِ عَبْدِ اللَّهِ الْبَجَلِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اقْرَءُوا الْقُرْآنَ مَا ائْتَلَفَتْ عَلَيْهِ قُلُوبُكُمْ، فَإِذَا اخْتَلَفْتُمْ فِيهِ فَقُومُوا". (ق)', 'ജുൻദുബുബ്നു അബ്ദില്ലാഹിൽ ബജലി(റ): റസൂൽ(സ) പറഞ്ഞു: "ഖുർആനിൽ നിന്ന് നിങ്ങളുടെ ഹൃദയങ്ങൾ പരസ്പരം യോജിച്ചത് നിങ്ങൾ ഓതുക. നിങ്ങൾ പരസ്പരം ഭിന്നാഭിപ്രായക്കാരായാൽ നിങ്ങൾ എഴുന്നേറ്റുപോകുക." (ബു,മു)', 'جُنْدَبِ بْنِ عَبْدِ اللَّهِ الْبَجَلِيِّ', 'ജുൻദുബുബ്നു അബ്ദില്ലാഹിൽ ബജലി(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 564, 564, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 117, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ نَامَ عَنْ حِزْبِهِ – أَوْ عَنْ شَيْءٍ مِنْهُ – فَقَرَأَهُ فِيمَا بَيْنَ صَلَاةِ الْفَجْرِ وَصَلَاةِ الظُّهْرِ، كُتِبَ لَهُ كَأَنَّمَا قَرَأَهُ مِنَ اللَّيْلِ". (م,د,ت,ن,جه)', 'ഉമറുബ്നുൽ ഖത്താബ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും രാത്രി ഓതാറുള്ളത് - അല്ലെങ്കിൽ അതിൽനിന്നെന്തെങ്കിലും - ഒഴിവാക്കി ഉറങ്ങുകയും പ്രഭാത നിസ്കാരത്തിന്റെയും ളുഹ്ർ നിസ്കാരത്തിന്റെയും ഇടയിലായി അത് ഓതുകയും ചെയ്താൽ അവൻ രാത്രി ഓതിയതുപോലെ അത് എഴുതപ്പെടും." (മു,ദ,തു,ന,ജ)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമറുബ്നുൽ ഖത്താബ്(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 564, 564, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 118, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللَّهُ عَنْهُ، يَبْلُغُ بِهِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أَتَى فِرَاشَهُ، وَهُوَ يَنْوِي أَنْ يَقُومَ فَيُصَلِّيَ مِنَ اللَّيْلِ، فَغَلَبَتْهُ عَيْنُهُ حَتَّى يُصْبِحَ، كُتِبَ لَهُ مَا نَوَى، وَكَانَ نَوْمُهُ صَدَقَةً عَلَيْهِ مِنْ رَبِّهِ". (ن,جه)', 'അബുദ്ദർദാഅ്(റ): നബി(സ) പറഞ്ഞു: "രാത്രി എഴുന്നേറ്റ് നിസ്കരിക്കണമെന്ന ഉദ്ദേശ്യത്തോടെ ഒരാൾ തന്റെ വിരിപ്പിലേക്ക് വരികയും അങ്ങനെ പ്രഭാതമാകുവോളം അവന്റെ കണ്ണുകൾ അവനെ അതിജയിക്കുകയും ചെയ്താൽ അവൻ കരുതിയിരുന്നത് അവന് എഴുതപ്പെടും. അവന്റെ ഉറക്കം തന്റെ രക്ഷിതാവിൽ നിന്നുള്ള ഒരു സ്വദഖയാവുകയും ചെയ്യും." (ന,ജ)', 'أَبِي الدَّرْدَاءِ', 'അബുദ്ദർദാഅ്(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 564, 565, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 119, 'عَنْ عَبْدِاللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أَنْكَحَنِي أَبِي امْرَأَةً ذَاتَ حَسَبٍ، فَكَانَ يَتَعَاهَدُ كَنَّتَهُ فَيَسْأَلُهَا عَنْ بَعْلِهَا، فَتَقُولُ: نِعْمَ الرَّجُلُ مِنْ رَجُلٍ لَمْ يَطَأْ لَنَا فِرَاشًا، وَلَمْ يُفَتِّشْ لَنَا كَنَفًا مُنْذُ أَتَيْنَاهُ، فَلَمَّا طَالَ ذَلِكَ عَلَيْهِ ذَكَرَ ذَلِكَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "الْقَنِي بِهِ". فَلَقِيتُهُ بَعْدُ، فَقَالَ: "كَيْفَ تَصُومُ؟" قُلْتُ: كُلَّ يَوْمٍ. قَالَ: "فَكَيْفَ تَخْتِمُ؟" قُلْتُ: كُلَّ لَيْلَةٍ، قَالَ: "صُمْ فِي كُلِّ شَهْرٍ ثَلَاثَةً، وَاقْرَإِ الْقُرْآنَ فِي كُلِّ شَهْرٍ". قُلْتُ: أُطِيقُ أَكْثَرَ مِنْ ذَلِكَ، قَالَ: "صُمْ ثَلَاثَةَ أَيَّامٍ فِي الْجُمُعَةِ". قُلْتُ: أُطِيقُ أَكْثَرَ مِنْ هَذَا، قَالَ: "أَفْطِرْ يَوْمَيْنِ وَصُمْ يَوْمًا". قُلْتُ: أُطِيقُ أَكْثَرَ مِنْ ذَلِكَ، قَالَ: "صُمْ أَفْضَلَ الصَّوْمِ صَوْمَ دَاوُدَ، صِيَامَ يَوْمٍ وَإِفْطَارَ يَوْمٍ، وَاقْرَأْ فِي كُلِّ سَبْعِ لَيَالٍ مَرَّةً". فَلَيْتَنِي قَبِلْتُ رُخْصَةَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَذَاكَ أَنِّي كَبِرْتُ وَضَعُفْتُ، فَكَانَ يَقْرَأُ عَلَى بَعْضِ أَهْلِهِ السُّبُعَ مِنَ الْقُرْآنِ بِالنَّهَارِ، وَالَّذِي يَقْرَؤُهُ يَعْرِضُهُ مِنَ النَّهَارِ، لِيَكُونَ أَخَفَّ عَلَيْهِ بِاللَّيْلِ، وَإِذَا أَرَادَ أَنْ يَتَقَوَّى أَفْطَرَ أَيَّامًا وَأَحْصَى، وَصَامَ مِثْلَهُنَّ كَرَاهِيَةَ أَنْ يَتْرُكَ شَيْئًا فَارَقَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَيْهِ. (خ)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): എന്റെ പിതാവ് എനിക്ക് നല്ല തറവാടിൽ നിന്നുള്ള ഒരു സ്ത്രീയെ വിവാഹം ചെയ്തുതന്നു. അദ്ദേഹം മരുമകളുടെ കാര്യങ്ങൾ ശ്രദ്ധിക്കുകയും ഭർത്താവിനെക്കുറിച്ച് അവളോട് അന്വേഷിക്കുകയും ചെയ്യുമായിരുന്നു. അപ്പോൾ അവൾ പറയും: അദ്ദേഹം നല്ലയാളാണ്. ഞാനദ്ദേഹത്തിന്റടുത്ത് വന്നതുമുതൽ എന്നോട് അദ്ദേഹം ബന്ധപ്പെടുകയോ എന്റെ മറകളെ പരിശോധിക്കുകയോ ചെയ്തിട്ടില്ല. അങ്ങനെ കുറെ കാലം ഇതേ മറുപടി തന്നെ അദ്ദേഹത്തിന് ലഭിച്ചപ്പോൾ നബി(സ)യോട് അദ്ദേഹം വിവരം പറഞ്ഞു. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "നിങ്ങൾ അവനെയും കൂട്ടി എന്റടുത്ത് വരിക." പിന്നീട് ഞാൻ തിരുമേനി(സ)യെ കണ്ടുമുട്ടി. അപ്പോൾ അവിടുന്ന് ചോദിച്ചു: "നിങ്ങൾ എങ്ങനെയാണ് നോമ്പനുഷ്ഠിക്കാറ്?" ഞാൻ പറഞ്ഞു: എല്ലാ ദിവസവും. അവിടുന്ന് ചോദിച്ചു: "നിങ്ങൾ എങ്ങനെയാണ് ഖുർആൻ ഓതാറുള്ളത്?" ഞാൻ പറഞ്ഞു: എല്ലാ രാത്രികളിലും. അവിടുന്ന് പറഞ്ഞു: "എല്ലാ മാസവും മൂന്ന് ദിവസം നീ നോമ്പനുഷ്ഠിക്കുക. ഓരോ മാസവും ഖുർആൻ ഓതിത്തീർക്കുകയും ചെയ്യുക." ഞാൻ പറഞ്ഞു: എനിക്ക് അതിലേറെ സാധിക്കും. അവിടുന്ന് പറഞ്ഞു: "എങ്കിൽ ഒരാഴ്ച മൂന്ന് ദിവസം നോമ്പനുഷ്ഠിക്കുക." ഞാൻ പറഞ്ഞു: എനിക്ക് അതിലേറെ സാധിക്കും. അവിടുന്ന് പറഞ്ഞു: "ഒരു ദിവസം നോമ്പനുഷ്ഠിക്കുക. രണ്ട് ദിവസം നോമ്പനുഷ്ഠിക്കാതിരിക്കുക." ഞാൻ പറഞ്ഞു: എനിക്കതിലേറെ ചെയ്യാൻ കഴിയും. അവിടുന്ന് പറഞ്ഞു: "ഏറ്റവും ഉന്നത നോമ്പായ ദാവുദ്(അ)മിന്റെ നോമ്പ് നീ അനുഷ്ഠിക്കുക. അഥവാ ഒരു ദിവസം നോമ്പനുഷ്ഠിക്കുക. അടുത്ത ദിവസം ഒഴിവാക്കുക. എല്ലാ ഏഴ് രാത്രികളിലും ഒരു പ്രാവശ്യം ഖുർആൻ ഓതിത്തീർക്കുക." അബ്ദുല്ല(റ) പറയുന്നു: അന്ന് തിരുമേനി(സ) നിർദ്ദേശിച്ചുതന്ന ഇളവ് ഞാൻ സ്വീകരിച്ചിരുന്നുവെങ്കിൽ എത്ര നന്നായിരുന്നു. എനിക്ക് വാർദ്ധക്യം ബാധിച്ചു, ഞാൻ ബലഹീനനായിത്തീർന്നിരിക്കുന്നു. പിൽക്കാലങ്ങളിൽ അദ്ദേഹം ഖുർആന്റെ ഏഴിലൊരു ഭാഗം പകൽ സമയത്തുതന്നെ വീട്ടുകാരിൽ ചിലർക്ക് ഓതിക്കേൾപിച്ചുകൊടുക്കാറുണ്ടായിരുന്നു. രാത്രി ഭാരം കുറഞ്ഞുകിട്ടാൻ വേണ്ടിയായിരുന്നു അത്. ക്ഷീണം അനുഭവപ്പെടുമ്പോൾ കുറെ ദിവസം തുടർച്ചയായി അദ്ദേഹം നോമ്പുപേക്ഷിക്കും. ആ ദിവസങ്ങൾ കണക്കാക്കി അത്രയും നോമ്പ് നോറ്റുവീട്ടുകയും ചെയ്യും. തിരുമേനി(സ)യുടെ കാലശേഷം, അവിടുത്തെ കാലത്ത് അനുഷ്ഠിച്ചുപോന്നിരുന്ന ഒരു കാര്യം ഉപേക്ഷിക്കുന്നതിലുള്ള വൈമനസ്യം മൂലമാണ് അങ്ങനെ ചെയ്തിരുന്നത്. (ബു)', 'عَبْدِاللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 565, 566, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 120, 'عَنْ أَوْسِ بْنِ حُذَيْفَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَدِمْنَا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي وَفْدِ ثَقِيفٍ، فَنَزَّلُوا الْأَحْلَافَ عَلَى الْمُغِيرَةِ بْنِ شُعْبَةَ، وَأَنْزَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَنِي مَالِكٍ فِي قُبَّةٍ لَهُ، فَكَانَ يَأْتِينَا كُلَّ لَيْلَةٍ بَعْدَ الْعِشَاءِ فَيُحَدِّثُنَا قَائِمًا عَلَى رِجْلَيْهِ، حَتَّى يُرَاوِحَ بَيْنَ رِجْلَيْهِ، وَأَكْثَرُ مَا يُحَدِّثُنَا مَا لَقِيَ مِنْ قَوْمِهِ مِنْ قُرَيْشٍ، وَيَقُولُ: "وَلَا سَوَاءَ، كُنَّا مُسْتَضْعَفِينَ مُسْتَذَلِّينَ، فَلَمَّا خَرَجْنَا إِلَى الْمَدِينَةِ كَانَتْ سِجَالُ الْحَرْبِ بَيْنَنَا وَبَيْنَهُمْ، نُدَالُ عَلَيْهِمْ وَيُدَالُونَ عَلَيْنَا". فَلَمَّا كَانَ ذَاتَ لَيْلَةٍ أَبْطَأَ عَنِ الْوَقْتِ الَّذِي كَانَ يَأْتِينَا فِيهِ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، لَقَدْ أَبْطَأْتَ عَلَيْنَا اللَّيْلَةَ. قَالَ: "إِنَّهُ طَرَأَ عَلَيَّ حِزْبِي مِنَ الْقُرْآنِ، فَكَرِهْتُ أَنْ أَخْرُجَ حَتَّى أُتِمَّهُ".
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 121, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: جَمَعْتُ الْقُرْآنَ فَقَرَأْتُهُ كُلَّهُ فِي لَيْلَةٍ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنِّي أَخْشَى أَنْ يَطُولَ عَلَيْكَ الزَّمَانُ، وَأَنْ تَمَلَّ، فَاقْرَأْهُ فِي شَهْرٍ". فَقُلْتُ: دَعْنِي أَسْتَمْتِعْ مِنْ قُوَّتِي وَشَبَابِي، قَالَ: "فَاقْرَأْهُ فِي عَشْرَةٍ". قُلْتُ: دَعْنِي أَسْتَمْتِعْ مِنْ قُوَّتِي وَشَبَابِي. قَالَ: "فَاقْرَأْهُ فِي سَبْعٍ". قُلْتُ: دَعْنِي أَسْتَمْتِعْ مِنْ قُوَّتِي وَشَبَابِي، فَأَبَى. (جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): ഞാൻ ഖുർആൻ മുഴുവൻ മനഃപാഠമാക്കുകയും ഒറ്റ രാത്രി അത് മുഴുവൻ ഓതിത്തീർക്കുകയും ചെയ്തു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നീ ഒരുപാട് കാലം ജീവിക്കുകയും നിനക്ക് ക്ഷീണം പറ്റുകയും ചെയ്യുമെന്ന് ഞാൻ ഭയപ്പെടുന്നു. അതിനാൽ നീ മാസത്തിൽ ഒരു പ്രാവശ്യം അത് ഓതിത്തീർക്കുക." അപ്പോൾ ഞാൻ പറഞ്ഞു: എന്റെ ആരോഗ്യവും യുവത്വവും ഉപയോഗപ്പെടുത്തി ദീർഘകാലം അത് ആസ്വദിക്കാൻ അങ്ങെനിക്ക് സമ്മതം നൽകിയാലും. അവിടുന്ന് പറഞ്ഞു: "എങ്കിൽ പത്ത് ദിവസത്തിലൊരിക്കൽ നീ അത് ഓതിത്തീർക്കുക." ഞാൻ പറഞ്ഞു: എന്റെ ആരോഗ്യവും യുവത്വവും ഉപയോഗപ്പെടുത്തി ദീർഘകാലം അത് ആസ്വദിക്കാൻ അങ്ങെനിക്ക് സമ്മതം നൽകിയാലും. അവിടുന്ന് പറഞ്ഞു: "എങ്കിൽ ഏഴു ദിവസത്തിലൊരിക്കൽ നീ അത് ഓതിത്തീർക്കുക." ഞാൻ പറഞ്ഞു: എന്റെ ആരോഗ്യവും യുവത്വവും ഉപയോഗപ്പെടുത്തി ദീർഘകാലം അതാസ്വദിക്കാൻ അങ്ങെന്നെ സമ്മതിച്ചാലും. അപ്പോൾ അവിടുന്ന് വിസമ്മതിച്ചു. (ജ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 566, 567, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 122, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَمْ يَفْقَهْ مَنْ قَرَأَ الْقُرْآنَ فِي أَقَلَّ مِنْ ثَلاَثٍ". (د,ت,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "മൂന്ന് ദിവസം തികയുന്നതിന് മുമ്പുതന്നെ ഖുർആൻ മുഴുവൻ ഓതിത്തീർത്തവൻ ജ്ഞാനമുൾക്കൊണ്ടിട്ടില്ല." (ദ,തു,ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 567, 567, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 123, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: لَا أَعْلَمُ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَرَأَ الْقُرْآنَ كُلَّهُ حَتَّى الصَّبَاحِ. (ن,جه)', 'ആഇശ(റ): പ്രഭാതം വരേയിരുന്ന് നബി(സ) ഖുർആൻ മുഴുവൻ ഓതിത്തീർത്തതായി എനിക്കറിയില്ല. (ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 567, 567, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 124, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، فِي كَمْ أَقْرَأُ الْقُرْآنَ؟ قَالَ: "اخْتِمْهُ فِي شَهْرٍ". قُلْتُ: إِنِّي أُطِيقُ أَفْضَلَ مِنْ ذَلِكَ. قَالَ: "اخْتِمْهُ فِي عِشْرِينَ". قُلْتُ: إِنِّي أُطِيقُ أَفْضَلَ مِنْ ذَلِكَ. قَالَ: "اخْتِمْهُ فِي خَمْسَةَ عَشَرَ". قُلْتُ: إِنِّي أُطِيقُ أَفْضَلَ مِنْ ذَلِكَ. قَالَ: "اخْتِمْهُ فِي عَشْرٍ". قُلْتُ: إِنِّي أُطِيقُ أَفْضَلَ مِنْ ذَلِكَ. قَالَ: "اخْتِمْهُ فِي خَمْسٍ". قُلْتُ: إِنِّي أُطِيقُ أَفْضَلَ مِنْ ذَلِكَ. قَالَ: فَمَا رَخَّصَ لِي. (ت,ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, എത്ര ദിവസം കൂടുമ്പോഴാണ് ഞാൻ ഖുർആൻ മുഴുവൻ ഓതിത്തീർക്കേണ്ടത്? അവിടുന്ന് പറഞ്ഞു: "മാസത്തിലൊരിക്കൽ നീയത് ഓതിത്തീർക്കുക." ഞാൻ പറഞ്ഞു: അതിനേക്കാൾ ഉത്തമമായത് ചെയ്യാൻ എനിക്ക് സാധിക്കും. അവിടുന്ന് പറഞ്ഞു: "എങ്കിൽ ഇരുപത് ദിവസത്തിലൊരിക്കൽ നീയത് ഓതിത്തീർക്കുക." ഞാൻ പറഞ്ഞു: അതിനേക്കാൾ ഉത്തമമായത് ചെയ്യാൻ എനിക്ക് സാധിക്കും. അവിടുന്ന് പറഞ്ഞു: "എങ്കിൽ നീ പതിനഞ്ച് ദിവസത്തിലൊരിക്കൽ അത് ഓതിത്തീർക്കുക." ഞാൻ പറഞ്ഞു: അതിനേക്കാൾ ഉത്തമമായത് ചെയ്യാൻ എനിക്ക് സാധിക്കും. അവിടുന്ന് പറഞ്ഞു: "എങ്കിൽ പത്ത് ദിവസത്തിലൊരിക്കൽ നീയത് ഓതിത്തീർക്കുക." ഞാൻ പറഞ്ഞു: അതിനേക്കാൾ ഉത്തമമായത് ചെയ്യാൻ എനിക്ക് സാധിക്കും. അവിടുന്ന് പറഞ്ഞു: "എങ്കിൽ അഞ്ച് ദിവസത്തിലൊരിക്കൽ നീയത് ഓതിത്തീർക്കുക." ഞാൻ പറഞ്ഞു: അതിലേറെ ഉത്തമമായത് ചെയ്യാൻ എനിക്ക് സാധിക്കും. അദ്ദേഹം പറയുന്നു: അവിടുന്ന് പിന്നീടെനിക്ക് ഇളവ് നൽകിയില്ല. (തു,ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 567, 567, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 125, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهُ: "اقْرَإِ الْقُرْآنَ فِي أَرْبَعِينَ". (د,ت,ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) അദ്ദേഹത്തോട് പറഞ്ഞു: "നാൽപത് ദിവസത്തിലൊരിക്കൽ നീ ഖുർആൻ ഓതിത്തീർക്കുക." (ദ,തു,ന)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 567, 567, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 126, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَجُلٌ: يَا رَسُولَ اللَّهِ، أَيُّ الْعَمَلِ أَحَبُّ إِلَى اللَّهِ؟ قَالَ: "الْحَالُّ الْمُرْتَحِلُ". قَالَ: وَمَا الْحَالُّ الْمُرْتَحِلُ؟ قَالَ: "الَّذِي يَضْرِبُ مِنْ أَوَّلِ الْقُرْآنِ إِلَى آخِرِهِ، كُلَّمَا حَلَّ ارْتَحَلَ". (ت)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരാൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, ഏത് കർമ്മമാണ് അല്ലാഹുവിന് ഏറ്റവും ഇഷ്ടപ്പെട്ടത്? അവിടുന്ന് പറഞ്ഞു: "അൽ ഹാലുൽ മുർതഹിൽ (ഇറങ്ങിയയുടൻ യാത്ര തടുരുന്നവൻ)." അദ്ദേഹം ചോദിച്ചു: എന്താണ് ''അൽ ഹാലുൽ മുർതഹിൽ?'' അവിടുന്ന് പറഞ്ഞു: "ഖുർആൻ തുടക്കം മുതൽ ഒടുക്കം വരെ ഓതിത്തീർക്കുന്നവനാണവൻ. ഓതിക്കഴിയുമ്പോഴേക്കവൻ വീണ്ടും തുടങ്ങും." (തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 567, 568, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 127, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهُ: "اقْرَإِ الْقُرْآنَ فِي شَهْرٍ". قَالَ: إِنِّي أَجِدُ قُوَّةً. قَالَ: "اقْرَأْ فِي عِشْرِينَ". قَالَ: إِنِّي أَجِدُ قُوَّةً. قَالَ: "اقْرَأْ فِي خَمْسَ عَشْرَةَ". قَالَ: إِنِّي أَجِدُ قُوَّةً. قَالَ: "اقْرَأْ فِي عَشْرٍ". قَالَ: إِنِّي أَجِدُ قُوَّةً. قَالَ: "اقْرَأْ فِي سَبْعٍ، وَلَا تَزِيدَنَّ عَلَى ذَلِكَ". (ق,د)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) അദ്ദേഹത്തോട് പറഞ്ഞു: "നിങ്ങൾ മാസത്തിലൊരിക്കൽ ഖുർആൻ ഓതിത്തീർക്കുക." അദ്ദേഹം പറഞ്ഞു: (അതിലേറെ ഓതാനുള്ള) ആരോഗ്യം എനിക്കുണ്ട്. അവിടുന്ന് പറഞ്ഞു: "എങ്കിൽ ഇരുപത് ദിവസത്തിലൊരിക്കൽ നീ അത് ഓതിത്തീർക്കുക." അദ്ദേഹം പറഞ്ഞു: ആരോഗ്യം എനിക്കുണ്ട്. അവിടുന്ന് പറഞ്ഞു: "എങ്കിൽ നീ പതിനഞ്ച് ദിവസത്തിലൊരിക്കൽ അത് ഓതിത്തീർക്കുക." അദ്ദേഹം പറഞ്ഞു: എനിക്ക് ആരോഗ്യമുണ്ട്. അവിടുന്ന് പറഞ്ഞു: "എങ്കിൽ പത്ത് ദിവസത്തിലൊരിക്കൽ നീയത് ഓതിത്തീർക്കുക." അദ്ദേഹം പറഞ്ഞു: എനിക്ക് ആരോഗ്യമുണ്ട്. അവിടുന്ന് പറഞ്ഞു: "എങ്കിൽ ഏഴ് ദിവസത്തിലൊരിക്കൽ നീയത് ഓതിത്തീർക്കുക. അതിലേറെ തീർച്ചയായും നീ വർധിപ്പിക്കരുത്." (ബു,മു,ദ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 568, 568, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 128, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "صُمْ مِنْ كُلِّ شَهْرٍ ثَلَاثَةَ أَيَّامٍ، وَاقْرَأِ الْقُرْآنَ فِي شَهْرٍ". فَنَاقَصَنِي وَنَاقَصْتُهُ، فَقَالَ: "صُمْ يَوْمًا وَأَفْطِرْ يَوْمًا". (د)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) എന്നോട് പറഞ്ഞു: "നീ എല്ലാ മാസവും മൂന്ന് ദിവസം നോമ്പനുഷ്ഠിക്കുക. മാസത്തിലൊരിക്കൽ ഖുർആൻ മുഴുവൻ ഓതിത്തീർക്കുക." അപ്പോൾ അത് കുറവാണെന്നതിനെക്കുറിച്ച സംസാരം എന്റെയും തിരുമേനി(സ)യുടെയും ഇടയിൽ നടന്നു. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "നീ ഒന്നിടവിട്ട് നോമ്പനുഷ്ഠിക്കുക." (ദ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 568, 568, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 129, 'عَنِ ابْنِ الْهَادِ قَالَ: سَأَلَنِي نَافِعُ بْنُ جُبَيْرِ بْنِ مُطْعِمٍ فَقَالَ لِي: فِي كَمْ تَقْرَأُ الْقُرْآنَ؟ فَقُلْتُ: مَا أُحَزِّبُهُ، فَقَالَ لِي نَافِعٌ: لَا تَقُلْ مَا أُحَزِّبُهُ، فَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "قَرَأْتُ جُزْءًا مِنَ الْقُرْآنِ". قَالَ: حَسِبْتُ أَنَّهُ ذَكَرَهُ عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ رَضِيَ اللَّهُ عَنْهُ. (د)', 'ഇബ്നുൽ ഹാദ്(റ): നാഫിഉബ്നു ജുബൈറുബ്നു മുത്ഇം(റ) എന്നോട് ചോദിച്ചു: എത്ര ദിവസം കൊണ്ടാണ് താങ്കൾ ഖുർആൻ ഓതിത്തീർക്കാറുള്ളത്? അപ്പോൾ ഞാൻ പറഞ്ഞു: ഞാനതിനെ ഭാഗങ്ങളാക്കി തിരിക്കാറില്ല. അപ്പോൾ നാഫിഅ്(റ) എന്നോട് പറഞ്ഞു: ഞാനതിനെ ഭാഗങ്ങളായി തിരിക്കാറില്ലെന്ന് നീ പറയരുത്. കാരണം, റസൂൽ(സ) പറഞ്ഞിട്ടുണ്ട്: "ഖുർആനിലെ ഒരു ജുസ്അ് ഞാൻ ഓതി." നിവേദകൻ പറയുന്നു: മുഗീറതുബ്നു ശുഅ്ബ(റ)വിനെക്കുറിച്ചാണ് അദ്ദേഹമത് പറഞ്ഞതെന്ന് ഞാൻ വാചാരിക്കുന്നു. (ദ)', 'ابْنِ الْهَادِ قَالَ', 'ഇബ്നുൽ ഹാദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 568, 568, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 130, 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ، وَقَدْ أَتَاهُ رَجُلٌ فَقَالَ: إِنِّي أَقْرَأُ الْمُفَصَّلَ فِي رَكْعَةٍ. فَقَالَ: أَهَذًّا كَهَذِّ الشِّعْرِ، وَنَثْرًا كَنَثْرِ الدَّقَلِ؟ لَكِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقْرَأُ النَّظَائِرَ السُّورَتَيْنِ فِي رَكْعَةٍ: {النَّجْمَ} وَ{الرَّحْمَنَ} فِي رَكْعَةٍ، وَ{اقْتَرَبَتْ} وَ{الْحَاقَّةَ} فِي رَكْعَةٍ، وَ{الطُّورَ} وَ{الذَّارِيَاتِ} فِي رَكْعَةٍ، وَ{إِذَا وَقَعَتْ} وَ{نُونَ} فِي رَكْعَةٍ، وَ{سَأَلَ سَائِلٌ} وَ{النَّازِعَاتِ} فِي رَكْعَةٍ، وَ{وَيْلٌ لِلْمُطَفِّفِينَ} وَ{عَبَسَ} فِي رَكْعَةٍ، وَ{الْمُدَّثِّرَ} وَ{الْمُزَّمِّلَ} فِي رَكْعَةٍ، وَ{هَلْ أَتَى} وَ{لَا أُقْسِمُ بِيَوْمِ الْقِيَامَةِ} فِي رَكْعَةٍ، وَ{عَمَّ يَتَسَاءَلُونَ} وَ{الْمُرْسَلَاتِ} فِي رَكْعَةٍ، وَ{الدُّخَانَ} وَ{إِذَا الشَّمْسُ كُوِّرَتْ} فِي رَكْعَةٍ. (م,د)', 'ഇബ്നുമസ്ഊദ്(റ): ഒരാൾ അദ്ദേഹത്തിന്റെയടുക്കൽ വന്ന് പറഞ്ഞു: ഞാൻ ഒറ്റ റക്അത്തിൽ തന്നെ മുഫസ്സ്വൽ (സൂറത്തുൽ ഹുജ്റാത്ത് മുതൽ അവസാനം വരെ) മുഴുവൻ ഓതാറുണ്ട്. അപ്പോഴദ്ദേഹം ചോദിച്ചു: കവിത പോലെ വേഗത്തിലും ഈത്തപ്പന കുലുക്കിയാൽ കുലയിൽ നിന്ന് കാരക്ക വീഴുന്നത് പോലെ മനസ്സിലാവാത്ത രൂപത്തിലുമാണോ നീ ഓതുന്നത്? പക്ഷേ, റസൂൽ(സ) ഒരു പോലെയുള്ള രണ്ട് സൂറത്തുകളായിരുന്നു ഒരു റക്അത്തിൽ ഓതിയിരുന്നത്: ഒരു റക്അത്തിൽ സൂറത്തുന്നജ്മും സൂറത്തുർറഹ്മാനും ഓതും. ''ഇഖ്തറബ്''യും ''അൽഹാഖ്''യും ഒരു റക്അത്തിൽ ഓതും. ''ഥൂറും'' ''അദ്ദാരിയാത്തും'' ഒരു റക്അത്തിൽ ഓതും. ''ഇദാ വഖഅ''യും ''നൂനും'' ഒരു റക്അത്തിൽ ഓതും. ''സഅലസാഇലും'' ''അന്നാസിആത്തും'' ഒരു റക്അത്തിൽ ഓതും. ''വൈലുൻ ലിൽ മുത്വഫിഫീനും'' ''അബസ''യും ഒരു റക്അത്തിൽ ഓതും. ''മുദ്ദസ്സിറും'' ''മുസമ്മിലും'' ഒരു റക്അത്തിൽ ഓതും. ''ഹൽ അതാ''യും ''ലാ ഉഖ്സിമു ബിയൗമിൽ ഖിയാമ''യും ഒരു റക്അത്തിൽ ഓതും. ''അമ്മ യതസാഅലൂനും'' ''അൽ മുർസലാതും'' ഒരു റക്അത്തിൽ ഓതും. ''ദുഖാനും'' ''ഇദശ്ശംസു കുവ്വിറത്തും'' ഒരു റക്അത്തിൽ ഓതും. (മു,ദ)', 'ابْنِ مَسْعُودٍ', 'ഇബ്നുമസ്ഊദ്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 568, 569, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 131, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ قَامَ بِعَشْرِ آيَاتٍ لَمْ يُكْتَبْ مِنَ الْغَافِلِينَ، وَمَنْ قَامَ بِمِائَةِ آيَةٍ كُتِبَ مِنَ الْقَانِتِينَ، وَمَنْ قَامَ بِأَلْفِ آيَةٍ كُتِبَ مِنَ الْمُقَنْطِرِينَ". (د)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ പത്ത് ആയത്തുകൾ സ്ഥിരമായി ഓതിയാൽ അവൻ അശ്രദ്ധവാന്മാരിൽ എഴുതപ്പെടില്ല. ഒരാൾ നൂറ് സൂക്തങ്ങൾ സ്ഥിരമായി ഓതിയാൽ, അനുസരണശീലരുടെ കൂട്ടത്തിൽ അവൻ എഴുതപ്പെടും. ഒരാൾ ആയിരം സൂക്തങ്ങൾ സ്ഥിരമായി ഓതിയാൽ, ധാരാളം പ്രതിഫലം ലഭിച്ചവരിൽ അവൻ എഴുതപ്പെടും." (ദ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 569, 569, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 132, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا حَسَدَ إِلَّا فِي اثْنَتَيْنِ، رَجُلٌ عَلَّمَهُ اللَّهُ الْقُرْآنَ فَهُوَ يَتْلُوهُ آنَاءَ اللَّيْلِ وَآنَاءَ النَّهَارِ، فَسَمِعَهُ جَارٌ لَهُ، فَقَالَ: لَيْتَنِي أُوتِيتُ مِثْلَ مَا أُوتِيَ فُلَانٌ، فَعَمِلْتُ مِثْلَ مَا يَعْمَلُ، وَرَجُلٌ آتَاهُ اللَّهُ مَالًا، فَهُوَ يُهْلِكُهُ فِي الْحَقِّ، فَقَالَ رَجُلٌ: لَيْتَنِي أُوتِيتُ مِثْلَ مَا أُوتِيَ فُلَانٌ، فَعَمِلْتُ مِثْلَ مَا يَعْمَلُ". (ق)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "രണ്ടു കാര്യങ്ങളിലല്ലാതെ അസൂയ പാടില്ല. അല്ലാഹു ഖുർആൻ പഠിപ്പിച്ചുകൊടുത്ത ഒരാൾ. അങ്ങനെ അയാൾ രാപ്പകൽ ഭേദമന്യേ അത് പാരായണം ചെയ്തുകൊണ്ടിരിക്കുന്നു. അപ്പോൾ അദ്ദേഹത്തിന്റെ ഒരു അയൽവാസി അത് കേട്ടുകൊണ്ട് പറയുന്നു: ഈ വ്യക്തിക്ക് നൽകപ്പെട്ടതുപോലെ എനിക്കും നൽകപ്പെടുകയും അങ്ങനെ അയാൾ പ്രവർത്തിക്കുന്നത് പോലെ ഞാനും പ്രവർത്തിക്കുകയും ചെയ്തിരുന്നെങ്കിൽ എത്ര നന്നായിരുന്നു. അല്ലാഹു സമ്പത്ത് നൽകിയ മറ്റൊരാൾ. അയാളത് സത്യമാർഗത്തിൽ ചെലവഴിക്കുന്നു. അപ്പോൾ മറ്റൊരാൾ പറഞ്ഞു: ഇയാൾക്ക് നൽകപ്പെട്ടതുപോലെ എനിക്കും നൽകപ്പെടുകയും അയാൾ പ്രവർത്തിക്കുന്നതു പോലെ ഞാനും പ്രവർത്തിക്കുകയും ചെയ്തിരുന്നെങ്കിൽ എത്ര നന്നായിരുന്നു." (ബു,മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 569, 569, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 133, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّمَا مَثَلُ صَاحِبِ الْقُرْآنِ كَمَثَلِ الْإِبِلِ الْمُعَقَّلَةِ، إِنْ عَاهَدَ عَلَيْهَا أَمْسَكَهَا، وَإِنْ أَطْلَقَهَا ذَهَبَتْ". (ق)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഖുർആൻ മനഃപാഠമാക്കിയവന്റെ ഉദാഹരണം, ബന്ധിക്കപ്പെട്ട ഒട്ടകത്തെപ്പോലെയാണ്. അതിനെ സൂക്ഷിച്ചാൽ അതിനെ പിടിച്ചുവെക്കാം. കെട്ടഴിച്ചുവിട്ടാൽ അത് പോവുകയും ചെയ്യും." (ബു,മു)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 569, 570, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 134, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "بِئْسَمَا لِأَحَدِكُمْ يَقُولُ: نَسِيتُ آيَةَ كَيْتَ وَكَيْتَ، بَلْ هُوَ نُسِّيَ. اسْتَذْكِرُوا الْقُرْآنَ، فَلَهُوَ أَشَدُّ تَفَصِّيًا مِنْ صُدُورِ الرِّجَالِ مِنَ النَّعَمِ بِعُقُلِهَا". (ق,ت,ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഇന്നാലിന്ന സൂക്തം ഞാൻ മറന്നുവെന്ന് പറയുന്നവൻ നിങ്ങളിൽ എത്ര മോശപ്പെട്ടവൻ! അവനത് മറപ്പിക്കപ്പെട്ടതാണ്. നിങ്ങൾ ഖുർആൻ ഓർത്തുവെക്കാൻ ശ്രമിക്കുക. കാരണം ഒട്ടകം അതിന്റെ കയറിൽ നിന്ന് ഓടിപ്പോകുന്നതിനേക്കാൾ വേഗത്തിൽ ആളുകളുടെ ഹൃദയത്തിൽനിന്ന് അത് ഓടിപ്പോകുന്നതാണ്." (ബു,മു,തു,ന)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 570, 570, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 135, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "عُرِضَتْ عَلَيَّ أُجُورُ أُمَّتِي، حَتَّى الْقَذَاةُ يُخْرِجُهَا الرَّجُلُ مِنَ الْمَسْجِدِ، وَعُرِضَتْ عَلَيَّ ذُنُوبُ أُمَّتِي، فَلَمْ أَرَ ذَنْبًا أَعْظَمَ مِنْ سُورَةٍ مِنَ الْقُرْآنِ أَوْ آيَةٍ، أُوتِيهَا رَجُلٌ ثُمَّ نَسِيَهَا". (ت)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "എന്റെ സമുദായത്തിന്റെ പ്രതിഫലങ്ങൾ, ഒരാൾ പള്ളിയിൽ നിന്ന് മാലിന്യങ്ങൾ പുറത്തുകളയുന്നത് പോലും, എനിക്ക് കാണിക്കപ്പെട്ടു. എന്റെ സമുദായത്തിന്റെ ദോഷങ്ങളും എനിക്ക് കാണിക്കപ്പെട്ടു. അപ്പോൾ ഖുർആനിൽ നിന്നുള്ള ഒരു സൂറത്തോ ഒരു സൂക്തമോ ഒരാൾക്ക് നൽകപ്പെടുകയും പിന്നീട് അയാളത് മറക്കുകയും ചെയ്യുന്നതിനേക്കാൾ വലിയ ഒരു ദോഷവും ഞാൻ കണ്ടില്ല." (തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 570, 570, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 136, 'عَنْ سَعْدِ بْنِ عُبَادَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا مِنِ امْرِئٍ يَقْرَأُ الْقُرْآنَ ثُمَّ يَنْسَاهُ، إِلَّا لَقِيَ اللَّهَ عَزَّ وَجَلَّ يَوْمَ الْقِيَامَةِ أَجْذَمَ". (د)', 'സഅ്ദുബ്നു ഉബാദ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഖുർആൻ പാരായണം ചെയ്യുകയും പിന്നീടത് മറക്കുകയും ചെയ്യുന്ന ഒരാളും അന്ത്യനാളിൽ കുഷ്ഠരോഗിയായിട്ടല്ലാതെ അല്ലാഹുവിനെ കണ്ടുമുട്ടുകയില്ല." (ദ)', 'سَعْدِ بْنِ عُبَادَةَ', 'സഅ്ദുബ്നു ഉബാദ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 570, 570, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 137, 'عَنْ أُبَيِّ بْنِ كَعْبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَا أُبَيُّ، إِنِّي أُقْرِئْتُ الْقُرْآنَ، فَقِيلَ لِي: عَلَى حَرْفٍ أَوْ حَرْفَيْنِ؟ فَقَالَ الْمَلَكُ الَّذِي مَعِي: قُلْ: عَلَى حَرْفَيْنِ، قُلْتُ: عَلَى حَرْفَيْنِ، فَقِيلَ لِي: عَلَى حَرْفَيْنِ أَوْ ثَلَاثَةٍ؟ فَقَالَ الْمَلَكُ الَّذِي مَعِي: قُلْ: عَلَى ثَلَاثَةٍ، قُلْتُ: عَلَى ثَلَاثَةٍ، حَتَّى بَلَغَ سَبْعَةَ أَحْرُفٍ، ثُمَّ قَالَ: لَيْسَ مِنْهَا إِلَّا شَافٍ كَافٍ، إِنْ قُلْتَ: سَمِيعًا عَلِيمًا عَزِيزًا حَكِيمًا، مَا لَمْ تَخْتِمْ آيَةَ عَذَابٍ بِرَحْمَةٍ، أَوْ آيَةَ رَحْمَةٍ بِعَذَابٍ". (د)', 'ഉബയ്യുബ്നു കഅ്ബ്(റ): നബി(സ) പറഞ്ഞു: "ഉബയ്യേ, നിശ്ചയം ഞാൻ ഖുർആൻ പാരായണം ചെയ്യിപ്പിക്കപ്പെട്ടു. അപ്പോൾ എന്നോട് ചോദിക്കപ്പെട്ടു: ഒരു ഹർഫിന് (ഒരു പാരായണശൈലിയുടെ മേലാണോ അതോ രണ്ട് ഹർഫിന് മേലാണോ? അപ്പോൾ എന്റെ കൂടെയുണ്ടായിരുന്ന മലക് പറഞ്ഞു: താങ്കൾ പറയുക, രണ്ട് ഹർഫുകൾക്കു മേലിലാണെന്ന്. അന്നേരം ഞാൻ പറഞ്ഞു: രണ്ട് ഹർഫുകൾക്കുമേലാണ്. അപ്പോൾ എന്നോട് ചോദിക്കപ്പെട്ടു: രണ്ട് ഹർഫുകൾക്കു മേലാണോ അതോ മൂന്ന് ഹർഫുകൾക്കു മേലാണോ? അപ്പോൾ എന്റെ കൂടെയുള്ള മലക് പറഞ്ഞു: താങ്കൾ പറയുക, മൂന്ന് ഹർഫുകൾക്കു മേലാണെന്ന്. ഞാൻ പറഞ്ഞു: മൂന്ന് ഹർഫുകൾക്കു മേലാണ്. അങ്ങനെ ഏഴ് ഹർഫുകൾ വരെ എത്തി. പിന്നെ മലക്ക് പറഞ്ഞു: ''എല്ലാം കേൾക്കുന്നവൻ, എല്ലാം അറിയുന്നവൻ, അത്യുന്നതൻ, മഹാതന്ത്രശാലി'' എന്നെല്ലാം അങ്ങ് പറയുമ്പോൾ പൂർണ്ണമായതും മതിയായതുമല്ലാത്ത ഒന്നും അതിലില്ല. ശിക്ഷയെ സൂചിപ്പിക്കുന്ന സൂക്തം അനുഗ്രഹം കൊണ്ടും അനുഗ്രഹം സൂചിപ്പിക്കുന്ന സൂക്തം ശിക്ഷകൊണ്ടും അവസാനിപ്പിക്കാത്തപ്പോഴാണിത്." (ദ)', 'أُبَيِّ بْنِ كَعْبٍ', 'ഉബയ്യുബ്നു കഅ്ബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 570, 571, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 138, 'عَنْ أُبَيِّ بْنِ كَعْبٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ عند أضاة بني غفار، فَأَتَاهُ جبريلُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "إِنَّ اللهَ عَزَّ وَجَلَّ يَأْمُرُكَ أَنْ تُقْرِئَ أُمَّتَكَ عَلَى حرف". قَالَ: أَسْأَلُ اللهَ مُعَافَاتَهُ وَمَغْفِرَتَهُ، إِنَّ أُمَّتِي لَا تُطِيقُ ذَلِكَ". ثُمَّ أَتَاهُ ثانية فذكر نحوَ هذا، حَتَّى بَلَغَ سَبْعَةَ أَحْرُفٍ، قَالَ: "إِنَّ اللهَ يَأْمُرُكَ أَنْ تُقْرِئَ أُمَّتَكَ عَلَى سَبْعَةِ أَحْرُفٍ، فَأَيُّمَا حرف قرءوا عَلَيْهِ فَقَدْ أصابوا". (ق,د,ن)', 'ഉബയ്യുബ്നു കഅ്ബ്(റ): ബനൂഗിഫാറിലെ തടാകത്തിനടുത്തിരിക്കെ നബി(സ)യുടെ അടുക്കൽ ജിബ്രീൽ(അ) വന്നുപറഞ്ഞു: അങ്ങയുടെ സമുദായത്തിന് ഒറ്റ ഹർഫിനുമേൽ ഖുർആൻ ഓതിക്കൊടുക്കാൻ അല്ലാഹു അങ്ങയോട് കൽപിക്കുന്നു. നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിനോട് ഞാൻ അവന്റെ മാപ്പും പാപമോചനവും തേടുന്നു. നിശ്ചയം എന്റെ സമുദായത്തിനൊരിക്കലുമത് സാധിക്കില്ല." രണ്ടാമതും ജിബ്രീൽ(അ) വരികയും മുമ്പ് പറഞ്ഞതുപോലെ പറയുകയും ചെയ്തു. അങ്ങനെ ഏഴ് ഹർഫുകൾ വരെ എത്തി. ജിബ്രീൽ(അ) പറഞ്ഞു: "അങ്ങയുടെ സമുദായത്തിന് ഏഴ് ഹർഫുകളിൽ (പാരായണശൈലികളിൽ) ഖുർആൻ ഓതിക്കൊടുക്കാൻ അല്ലാഹു അങ്ങയോട് കൽപ്പിക്കുന്നു. ഏതു ഹർഫിനുമേൽ ഓതിയാലും അവർക്ക് നന്മ ലഭിച്ചിരിക്കുന്നു." (ബു,മു,ദ,ന)', 'أُبَيِّ بْنِ كَعْبٍ', 'ഉബയ്യുബ്നു കഅ്ബ്(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 571, 571, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 139, 'عَنِ المسور بن مخرمة – رَضِيَ اللهُ عَنْهُمَا – وعبد الرحمن بن عبد القاري: أَنَّهُمَا سمعا عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ يقول: مررت بهشام بن حكيم بن حزام، وَهُوَ يقرأ سُورَةَ الْفُرْقَانِ فِي حياة رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فاستمعت قراءته، فَإِذَا هُوَ يقرأ عَلَى حُرُوف كثيرة لَمْ يُقْرِئْنِيهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فكدت أساوره في الصلاة، فنظرت حَتَّى سَلَّمَ، فَلَمَّا سَلَّمَ لَبَّبْتُهُ بِرِدَائِهِ فَقُلْتُ: مَنْ أَقْرَأَكَ هَذِهِ السُّورَةَ الَّتِي سمعتك تَقْرَؤُهَا؟ فَقَالَ: أَقْرَأَنِيهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. قُلْتُ لَهُ: كَذَبْتَ، وَاللهِ إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَهُوَ أَقْرَأَنِي هَذِهِ السُّورَةَ الَّتِي تَقْرَؤُهَا. فَانْطَلَقْتُ أَقُودُهُ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقُلْتُ: يَا رَسُولَ اللهِ، إِنِّي سمعت هَذَا يقرأ سُورَةَ الْفُرْقَانِ عَلَى حُرُوف لَمْ تُقْرِئْنِيهَا، وَأَنْتَ أَقْرَأْتَنِي سُورَةَ الْفُرْقَانِ؟ فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَرْسِلْهُ يَا عُمَرُ، اقْرَأْ يَا هِشَامُ". فَقَرَأَ عَلَيْهِ الْقِرَاءَةَ الَّتِي سمعت، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "هَكَذَا أُنْزِلَتْ". ثُمَّ قَالَ لِي النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اقْرَأْ يَا عُمَرُ". فَقَرَأْتُ بِالْقِرَاءَةِ الَّتِي أَقْرَأَنِي النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "هَكَذَا أُنْزِلَتْ". ثُمَّ قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ هَذَا الْقُرْآنَ أُنْزِلَ عَلَى سَبْعَةِ أَحْرُفٍ، فَاقْرَءُوا مَا تَيَسَّرَ مِنْهُ". (ق,د,ت,ن)', 'മിസ്വറുബ്നു മഖ്റമ(റ)വും അബ്ദുർറഹ്മാനുബ്നു അബ്ദിൽ ഖാരിയ്യ്(റ)വും ഉദ്ധരിക്കുന്നു: അവർ ഉമറുബ്നുൽ ഖത്താബ്(റ) പറയുന്നത് കേട്ടു: റസൂൽ(സ)യുടെ ജീവിതകാലത്ത്, ഒരിക്കൽ, ഹിശാമുബ്നു ഹകീമുബ്നു ഹിസാം(റ)വിന്റെ അടുത്തുകൂടെ ഞാൻ നടന്നുപോയി. അദ്ദേഹം സൂറത്തുൽ ഫുർഖാൻ ഓതുകയായിരുന്നു. ഞാനദ്ദേഹത്തിന്റെ പാരായണം സാകൂതം ശ്രദ്ധിച്ചു. എനിക്ക് റസൂൽ(സ) ഓതിത്തന്നിട്ടില്ലാത്ത ധാരാളം ഹർഫുകൾക്കുമേലാണ് (ശൈലികളിലാണ്) അദ്ദേഹമത് ഓതുന്നത്. നിസ്കരിച്ചു കൊണ്ടിരിക്കെത്തന്നെ അദ്ദേഹത്തിന്റെ മേൽ ചാടിവീഴാൻ ഞാൻ കരുതി. പക്ഷേ, അദ്ദേഹം സലാം വീട്ടുന്നതുവരെ ഞാൻ കാത്തുനിന്നു. അങ്ങനെയദ്ദേഹം സലാം വീട്ടിയപ്പോൾ ഞാനദ്ദേഹത്തിന്റെ വസ്ത്രത്തിൽ പിടിച്ചുകൊണ്ട് ചോദിച്ചു: താങ്കൾ ഓതുന്നതായി ഞാനിപ്പോൾ കേട്ട രൂപത്തിൽ ആരാണ് നിങ്ങൾക്ക് ഓതിത്തന്നത്? അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ)യാണ് എനിക്കങ്ങനെ ഓതിത്തന്നത്. ഞാൻ പറഞ്ഞു: താങ്കൾ കളവാണ് പറയുന്നത്. അല്ലാഹുവാണെ, നിങ്ങളിപ്പോൾ ഓതിയ ഈ സൂറത്ത് റസൂൽ(സ) തന്നെയാണ് എനിക്ക് ഓതിത്തന്നിട്ടുള്ളത്. അങ്ങനെ ഞാനദ്ദേഹത്തെയും കൊണ്ട് റസൂൽ(സ)യുടെ അടുക്കൽ പോയി. ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങെനിക്ക് ഓതിത്തന്നിട്ടില്ലാത്ത വിവിധ ഹർഫുകളിന്മേൽ ഇദ്ദേഹം ഫുർഖാൻ സൂറത്ത് ഓതുന്നത് ഞാൻ കേട്ടു. സൂറത്തുൽ ഫുർഖാൻ അങ്ങാണെനിക്ക് ഓതിത്തന്നതും. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഉമരേ, നിങ്ങളദ്ദേഹത്തെ വിടുക. ഹിശാമേ, നിങ്ങൾ ഓതുക." അപ്പോഴദ്ദേഹം ഞാൻ കേട്ടതുപോലെ ഓതിക്കൊടുത്തു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഇപ്രകാരമത് ഇറക്കപ്പെട്ടിരിക്കുന്നു." പിന്നീട് നബി(സ) എന്നോട് പറഞ്ഞു: "ഉമരേ, നിങ്ങൾ ഓതുക." അപ്പോൾ ഞാൻ, നബി(സ) എനിക്ക് ഓതിത്തന്നതു പോലെ ഓതി. നബി(സ) പറഞ്ഞു: "ഇപ്രകാരമത് ഇറക്കപ്പെട്ടിട്ടുണ്ട്." പിന്നെ നബി(സ) പറഞ്ഞു: "നിശ്ചയം ഈ ഖുർആൻ ഏഴ് ഹർഫുകൾക്കുമേൽ ഇറക്കപ്പെട്ടിരിക്കുന്നു. അതിനാൽ അതിൽനിന്നേറ്റവും എളുപ്പമായത് നിങ്ങൾ ഓതുക." (ബു,മു,ദ,തു,ന)', 'المسور بن مخرمة –', 'മിസ്വറുബ്നു മഖ്റമ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 571, 572, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 140, 'عَنْ أُبَيِّ بْنِ كَعْبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَقِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جِبْرِيلَ، فَقَالَ: "يَا جِبْرِيلُ، إِنِّي بُعِثْتُ إِلَى أُمَّةٍ أُمِّيِّينَ، مِنْهُمُ الْعَجُوزُ وَالشَّيْخُ الْكَبِيرُ وَالْغُلَامُ وَالْجَارِيَةُ وَالرَّجُلُ الَّذِي لَمْ يَقْرَأْ كِتَابًا قَطُّ، قَالَ: يَا مُحَمَّدُ، إِنَّ الْقُرْآنَ أُنْزِلَ عَلَى سَبْعَةِ أَحْرُفٍ". (ت)', 'ഉബയ്യുബ്നു കഅ്ബ്(റ): റസൂൽ(സ) ജിബ്രീൽ(അ)നെ കണ്ടുമുട്ടി. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "ജിബ്രീലേ, നിശ്ചയം വൃദ്ധകളും വൃദ്ധന്മാരും അടിമകളായ ആൺകുട്ടികളും പെൺകുട്ടികളും, ഒരെഴുത്തു പോലും വായിച്ചിട്ടില്ലാത്തവനും ഉൾപെട്ട നിരക്ഷരരായ ഒരു സമുദായത്തിലേക്കാണ് ഞാൻ അയക്കപ്പെട്ടിട്ടുള്ളത്. ജിബ്രീൽ(അ) പറഞ്ഞു: മുഹമ്മദ്, നിശ്ചയം ഖുർആൻ ഏഴ് ഹർഫുകൾക്കുമേൽ (ശൈലികളിൽ) ഇറക്കപ്പെട്ടിരിക്കുന്നു." (തു)', 'أُبَيِّ بْنِ كَعْبٍ', 'ഉബയ്യുബ്നു കഅ്ബ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 572, 572, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 141, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا، عَنْ أُبَيِّ بْنِ كَعْبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَقْرَأَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُورَةً، فَبَيْنَا أَنَا فِي الْمَسْجِدِ جَالِسٌ إِذْ سَمِعْتُ رَجُلًا يَقْرَؤُهَا يُخَالِفُ قِرَاءَتِي، فَقُلْتُ لَهُ: مَنْ عَلَّمَكَ هَذِهِ السُّورَةَ؟ فَقَالَ: رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَقُلْتُ: لَا تُفَارِقْنِي حَتَّى نَأْتِيَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَأَتَيْتُهُ فَقُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّ هَذَا خَالَفَ قِرَاءَتِي فِي السُّورَةِ الَّتِي عَلَّمْتَنِي. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اقْرَأْ يَا أُبَيُّ". فَقَرَأْتُهَا، فَقَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَحْسَنْتَ". ثُمَّ قَالَ لِلرَّجُلِ: "اقْرَأْ". فَقَرَأَ فَخَالَفَ قِرَاءَتِي، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَحْسَنْتَ". ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَا أُبَيُّ، إِنَّهُ أُنْزِلَ الْقُرْآنُ عَلَى سَبْعَةِ أَحْرُفٍ، كُلُّهُنَّ شَافٍ كَافٍ". (ن)', 'ഉബയ്യുബ്നു കഅ്ബ്(റ)വിൽ നിന്ന് ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) എനിക്കൊരു സൂറത്ത് ഓതിത്തന്നു. ഞാൻ പള്ളിയിലിരിക്കുമ്പോൾ ഒരാൾ അതേ സൂറത്ത് എന്റെ പാരായണത്തിന് എതിരായി ഓതുന്നത് ഞാൻ കേട്ടു. അപ്പോൾ ഞാനദ്ദേഹത്തോട് ചോദിച്ചു: ആരാണ് നിനക്ക് ഈ സൂറത്ത് പഠിപ്പിച്ചു തന്നത്? അപ്പോഴദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂൽ(സ). അപ്പോൾ ഞാൻ പറഞ്ഞു: റസൂൽ(സ)യുടെ അടുത്തെത്തുന്നതുവരെ താങ്കളെന്നെ വിട്ടുപിരിയരുത്. അങ്ങനെ ഞാൻ റസൂൽ(സ)യുടെ അടുക്കൽ വന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, നിശ്ചയം ഇദ്ദേഹം, അങ്ങെനിക്ക് പഠിപ്പിച്ചുതന്ന സൂറത്തിൽ എന്റെ ഓത്തിന് എതിരായിരിക്കുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഉബയ്യേ നീ ഓതുക." അപ്പോൾ ഞാനത് ഓതി. അപ്പോൾ എന്നോട് റസൂൽ(സ) പറഞ്ഞു: "വളരെ നന്നായിരിക്കുന്നു." പിന്നെയവിടുന്ന് ആ വ്യക്തിയോട് പറഞ്ഞു: "നിങ്ങൾ ഓതുക." അപ്പോഴദ്ദേഹം എന്റെ ഓത്തിന് വിപരീതമായി ഓതി. അപ്പോഴദ്ദേഹത്തോട് റസൂൽ(സ) പറഞ്ഞു: "വളരെ നന്നായിരിക്കുന്നു." പിന്നെ റസൂൽ(സ) പറഞ്ഞു: "ഉബയ്യേ, നിശ്ചയം ഖുർആൻ ഏഴ് ഹർഫുകൾക്കുമേൽ (പാരായണ ശൈലികളിൽ) ഇറക്കപ്പെട്ടിരിക്കുന്നു. അവയെല്ലാം മതിയായതും പൂർണ്ണമായതുമാണ്." (ന)', 'ابْنِ عَبَّاسٍ', 'ഉബയ്യുബ്നു കഅ്ബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 572, 573, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 142, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ، عَنْ أُبَيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: مَا حَاكَ فِي صَدْرِي مُنْذُ أَسْلَمْتُ، إِلَّا أَنِّي قَرَأْتُ آيَةً وَقَرَأَهَا آخَرُ غَيْرَ قِرَاءَتِي، فَقُلْتُ: أَقْرَأَنِيهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. وَقَالَ الْآخَرُ: أَقْرَأَنِيهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. فَأَتَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: يَا نَبِيَّ اللهِ، أَقْرَأْتَنِي آيَةَ كَذَا وَكَذَا؟ قَالَ: "نَعَمْ". وَقَالَ الْآخَرُ: أَلَمْ تُقْرِئْنِي آيَةَ كَذَا وَكَذَا. قَالَ: "نَعَمْ، إِنَّ جبريل وَمِيكَائِيلَ عَلَيْهِمَا السَّلَامُ أَتَيَانِي، فَقَعَدَ جبريلُ عَنْ يميني وَمِيكَائِيلُ عَنْ يَسَارِي، فَقَالَ جِبْرِيلُ عَلَيْهِ السَّلَامُ: اقْرَأِ الْقُرْآنَ عَلَى حَرْفٍ. قَالَ مِيكَائِيلُ: اسْتَزِدْهُ اسْتَزِدْهُ، حَتَّى بَلَغَ سَبْعَةَ أَحْرُفٍ، فَكُلُّ حَرْفٍ شَافٍ كَافٍ". (ن)', 'ഉബയ്യ്(റ)വിൽനിന്ന് അനസ്(റ): ഞാൻ ഒരു ആയത്ത് ഓതുകയും മറ്റൊരാൾ അതേ ആയത്ത് മറ്റൊരു രൂപത്തിൽ ഓതുകയും ചെയ്തപ്പോഴല്ലാതെ, ഞാൻ മുസ്ലിമായതു മുതൽ എന്റെ ഹൃദയത്തിൽ എനിക്കൊരു സംശയവും ഉണ്ടായിട്ടില്ല. അപ്പോൾ ഞാൻ പറഞ്ഞു: എനിക്ക് റസൂൽ(സ) ആ ആയത്ത് ഓതിത്തന്നിട്ടുണ്ട്. മറ്റെയാളും പറഞ്ഞു: എനിക്കും റസൂൽ(സ) ആ ആയത്ത് ഓതിത്തന്നിട്ടുണ്ട്. ഉടനെ ഞാൻ റസൂൽ(സ)യുടെ അടുക്കൽ ചെന്ന് ചോദിച്ചു: അല്ലാഹുവിന്റെ നബിയേ, ഇന്നാലിന്ന ആയത്ത് അങ്ങെനിക്ക് ഓതിത്തന്നിട്ടില്ലെയോ? അവിടുന്ന് പറഞ്ഞു: "അതെ." മറ്റെയാളും ചോദിച്ചു: നബിയേ, ഇന്നാലിന്ന ആയത്ത് അങ്ങെനിക്ക് ഓതിത്തന്നിട്ടില്ലെയോ? അവിടുന്ന് പറഞ്ഞു: "അതെ, നിശ്ചയം ജിബ്രീലും മീകാഈലും എന്റെയടുക്കൽ വരികയും ജിബ്രീൽ(അ) എന്റെ വലതുഭാഗത്തും മീകാഈൽ(അ) എന്റെ ഇടതു ഭാഗത്തും ഇരിക്കുകയും ചെയ്തു. അപ്പോൾ ജിബ്രീൽ(അ) പറഞ്ഞു: അങ്ങ് ഖുർആൻ ഒരു ഹർഫിനുമേൽ ഓതിയാലും. മീകാഈൽ(അ) പറഞ്ഞു: അങ്ങ് കൂട്ടിത്തരാൻ പറഞ്ഞാലും. അങ്ങ് കൂട്ടിത്തരാൻ പറഞ്ഞാലും. അങ്ങനെ ഏഴ് ഹർഫ് വരെ എത്തി. അതിലോരോ ഹർഫും മതിയായതും പൂർണ്ണവുമാണ്." (ന)', 'أَنَسٍ', 'ഉബയ്യ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 573, 573, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 143, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُقَطِّعُ قِرَاءَتَهُ يَقُولُ: {الحمد لله رب الْعَالَمِينَ} ثُمَّ يَقِفُ. {الرَّحْمَنِ الرَّحِيمِ} ثُمَّ يَقِفُ. وَكَانَ يَقْرَؤُهَا: {مَالِكِ يَوْمِ الدِّينِ}. (د,ت)', 'ഉമ്മുസലമ(റ): നബി(സ) മുറിച്ചു മുറിച്ചായിരുന്നു ഓതിയിരുന്നത്. അവിടുന്ന് ''അൽഹംദുലില്ലാഹി റബ്ബിൽ ആലമീൻ'' എന്ന് ഓതി നിർത്തും. പിന്നെ ''അർറഹ്മാനി റഹീം'' എന്ന് ഓതി നിർത്തും. അവിടുന്ന് ''മാലികി യൗമിദ്ദീൻ'' എന്നായിരുന്നു ഓതിയിരുന്നത്. (ദ,തു)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 573, 573, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 144, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَبَا بَكْرٍ وَعُمَرَ وَعُثْمَانَ – رَضِيَ اللهُ عَنْهُمْ – كَانُوا يَقْرَؤُونَ: {مَالِكِ يَوْمِ الدِّينِ}. (ت)', 'അനസ്(റ): നിശ്ചയം, നബി(സ)യും അബൂബക്കർ(റ)വും ഉമർ(റ)വും ''മാലികി യൗമിദ്ദീൻ'' എന്നായിരുന്നു ഓതിയിരുന്നത്. (തു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 573, 574, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 145, 'عَنِ ابْنِ الْمُسَيِّبِ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَبُو بَكْرٍ وَعُمَرُ وَعُثْمَانُ يَقْرَؤُونَ: {مَالِكِ يَوْمِ الدِّينِ}. وَأَوَّلُ مَنْ قَرَأَهَا: {مَلِكِ يَوْمِ الدِّينِ} مَرْوَانُ. (د,ت)', 'ഇബ്നുൽ മുസയ്യബ്(റ): നബി(സ)യും അബൂബക്കർ(റ)വും ഉമർ(റ)വും ''മാലികി യൗമിദ്ദീൻ'' എന്നായിരുന്നു ഓതിയിരുന്നത്. ആദ്യമായി ''മലികി യൗമിദ്ദീൻ'' എന്ന് ഓതിയത് മർവാനാണ്. (ദ,തു)', 'ابْنِ الْمُسَيِّبِ', 'ഇബ്നുൽ മുസയ്യബ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 574, 574, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 146, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا: ذَكَرَتْ قِرَاءَةَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: {بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ. الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ. الرَّحْمَنِ الرَّحِيمِ. مَلِكِ يَوْمِ الدِّينِ} يُقَطِّعُ قِرَاءَتَهُ آيَةً آيَةً. (د,ت)', 'ഉമ്മുസലമ(റ): നബി(സ)യുടെ ഖുർആൻ പാരായണത്തെക്കുറിച്ച് മഹതി പറയുന്നു: ''ബിസ്മില്ലാഹി റഹ്മാനി റഹീം. അൽഹംദു ലില്ലാഹി റബ്ബിൽ ആലമീൻ. അർറഹ്മാനി റഹീം. മലികി യൗമിദ്ദീൻ.'' എന്നിങ്ങനെ ഓരോ ആയത്തും മുറിച്ച് മുറിച്ചായിരുന്നു അവിടുത്തെ പാരായണം. (ദ,തു)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 574, 574, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 147, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَرَأَ: {وَاتَّخِذُوا مِنْ مَقَامِ إِبْرَاهِيمَ مُصَلًّى} [البقرة: ١٢٥]. (د,ت,جه)', 'ജാബിർ(റ): നബി(സ) (ഇപ്രകാരം) ഓതി: ''ഇബ്റാഹീം(അ) നിന്ന് പ്രാർത്ഥിച്ച സ്ഥാനത്തെ നിങ്ങളും പ്രാർത്ഥനാവേദിയാക്കുക.'' (''ഇത്തഖിദൂ'' എന്ന് കൽപനയായിട്ട്) (ബഖറ: 15) (ദ,തു,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], 'البقرة: ١٢٥', null, 574, 574, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 148, 'عَنْ وَاثِلَةَ بْنِ الْأَسْقَعِ رَضِيَ اللَّهُ عَنْهُ قَالَ: إِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَاءَهُمْ فِي صُفَّةِ الْمُهَاجِرِينَ، فَسَأَلَهُ إِنْسَانٌ: أَيُّ آيَةٍ فِي الْقُرْآنِ أَعْظَمُ؟ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: {اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ} [البقرة: ٢٥٥]. (د)', 'വാസിലതുബ്നുൽ അസ്ഖഅ്(റ): മുഹാജിറുകളുടെ തിണ്ണയിലിരിക്കുമ്പോൾ നബി(സ) അവരുടെ അടുത്തേക്ക് വന്നു. അപ്പോൾ അവിടുത്തോട് ഒരാൾ ചോദിച്ചു: ഖുർആനിൽ ഏറ്റവും മഹത്തായ സൂക്തം ഏതാണ്? നബി(സ) പറഞ്ഞു: "അത് ''അല്ലാഹു, അവനല്ലാതെ ഒരു ആരാധ്യനുമില്ല. എന്നെന്നും ജീവിച്ചിരിക്കുന്നവൻ, എല്ലാം നിയന്ത്രിക്കുന്നവൻ. മയക്കമോ ഉറക്കമോ അവനെ ബാധിക്കുകയില്ല'' എന്ന സൂക്തമാണ്." (അൽബഖറ: 255) (ദ)', 'وَاثِلَةَ بْنِ الْأَسْقَعِ', 'വാസിലതുബ്നുൽ അസ്ഖഅ്(റ)', null, null, array['د']::text[], array['ദ']::text[], 'البقرة: ٢٥٥', null, 574, 574, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 149, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "قَالَ اللَّهُ عَزَّ وَجَلَّ لِبَنِي إِسْرَائِيلَ: {ادْخُلُوا الْبَابَ سُجَّدًا وَقُولُوا حِطَّةٌ تُغْفَرْ لَكُمْ خَطَايَاكُمْ} [البقرة: ٥٨]". (د)', 'അബൂസഈദിൽ ഖുദ്രി(റ): റസൂൽ(സ) പറഞ്ഞു: "മഹോന്നതനായ അല്ലാഹു ബനൂഇസ്റാഈലിനോട് പറഞ്ഞു: ''നിങ്ങൾ സാഷ്ടാംഗം നമിക്കുന്നവരായി കവാടം കടക്കുകയും പശ്ചാത്താപ വചനം ഉരുവിടുകയും ചെയ്യുവീൻ. എങ്കിൽ നിങ്ങൾക്ക് പാപങ്ങൾ പൊറുക്കപ്പെടും.'' (ബഖറ: 58) (''തുഗ്ഫർ ലകും'' എന്ന് ''താ''യാണ് ഉപയോഗിച്ചത്, ''നഗ്ഫിർ ലകും'' എന്നല്ല.) (ദ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['د']::text[], array['ദ']::text[], 'البقرة: ٥٨', null, 574, 574, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 150, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ رَجُلًا قَامَ مِنَ اللَّيْلِ فَقَرَأَ، فَرَفَعَ صَوْتَهُ بِالْقُرْآنِ، فَلَمَّا أَصْبَحَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَرْحَمُ اللَّهُ فُلَانًا، كَائِنْ مِنْ آيَةٍ أَذْكَرَنِيهَا اللَّيْلَةَ، كُنْتُ قَدْ أَسْقَطْتُهَا". (ق,د)', 'ആഇശ(റ): ഒരാൾ രാത്രിയിൽ എഴുന്നേറ്റ് നിസ്കരിക്കവെ ശബ്ദമുയർത്തി ഖുർആൻ ഓതി. നേരം പുലർന്നപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഇന്നയാൾക്ക് അല്ലാഹു റഹ്മത്ത് ചെയ്യട്ടെ. ഒരു സൂക്തത്തിലെ ''കാഇൻ'' (കഅയ്യിൻ എന്നും വന്നിട്ടുണ്ട്) എന്ന പദം രാത്രിയിൽ അദ്ദേഹമെന്നെ ഓർമിപ്പിച്ചുതന്നു. ഞാൻ അത് വിട്ടുപോകാറുണ്ടായിരുന്നു." (ബു,മു,ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 574, 575, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 151, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: نَزَلَتْ هَذِهِ الْآيَةُ: {وَمَا كَانَ لِنَبِيٍّ أَنْ يَغُلَّ} [آل عمران: ١٦١] فِي قَطِيفَةٍ حَمْرَاءَ فُقِدَتْ يَوْمَ بَدْرٍ، فَقَالَ بَعْضُ النَّاسِ: لَعَلَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخَذَهَا، فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ: {وَمَا كَانَ لِنَبِيٍّ أَنْ يَغُلَّ} إِلَى آخِرِ الْآيَةِ. (د,ت)', 'ഇബ്നുഅബ്ബാസ്(റ): ''(വല്ല വസ്തുവും) വഞ്ചിച്ചെടുക്കൽ ഒരു പ്രവാചകന്നും ചേർന്നതല്ല.'' (ഇവിടെ ''യഗുല്ല'' എന്നാണ് പ്രയോഗിച്ചത്, ''യുഗല്ല'' എന്നല്ല) (ആലുഇംറാൻ: 161) എന്ന ഈ സൂക്തം ഒരു ചുവന്ന വില്ലൂസ് പട്ടുകൊണ്ടുള്ള വസ്ത്രത്തിന്റെ കാര്യത്തിലാണ് അവതീർണമായത്. ബദ്ർ ദിനം അത് നഷ്ടപ്പെട്ടു. അപ്പോൾ ചിലയാളുകൾ പറഞ്ഞു: റസൂൽ(സ) അതെടുത്തിട്ടുണ്ടായിരിക്കാം. അപ്പോഴാണ് മഹോന്നതനായ അല്ലാഹു, ''(ഒരു വസ്തുവും) വഞ്ചിച്ചെടുത്തുവെക്കൽ ഒരു പ്രവാചകന്നും ചേർന്നതല്ല'' എന്ന സൂക്തം അവസാനം വരെ അവതരിപ്പിച്ചത്. (ദ,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], 'آل عمران: ١٦١', null, 575, 575, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 152, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: لَحِقَ الْمُسْلِمُونَ رَجُلًا فِي غُنَيْمَةٍ لَهُ، فَقَالَ: السَّلَامُ عَلَيْكُمْ، فَقَتَلُوهُ، وَأَخَذُوا تِلْكَ الْغُنَيْمَةَ، فَنَزَلَتْ: {وَلَا تَقُولُوا لِمَنْ أَلْقَى إِلَيْكُمُ السَّلَامَ لَسْتَ مُؤْمِنًا تَبْتَغُونَ عَرَضَ الْحَيَاةِ الدُّنْيَا} [النساء: ٩٤] تِلْكَ الْغُنَيْمَةَ. (خ,د)', 'ഇബ്നുഅബ്ബാസ്(റ): തന്റെ ഒരു ചെറിയ ആട്ടിൻപറ്റവുമായി ഒരാളെ മുസ്ലിംകൾ കണ്ടുമുട്ടി. അപ്പോൾ അയാൾ പറഞ്ഞു: അസ്സലാമു അലൈക്കും. അന്നേരം അവരയാളെ വധിക്കുകയും ആട്ടിൻപറ്റത്തെ എടുക്കുകയും ചെയ്തു. ''നിങ്ങൾക്ക് സലാം അർപ്പിച്ചവനോട്, ഇഹലോകജീവിതത്തിലെ നേട്ടം കൊതിച്ചുകൊണ്ട് (ആട്ടിൻപറ്റത്തെയാണ് ഇതുകൊണ്ട് ഉദ്ദേശിക്കുന്നത്) നീ സത്യവിശ്വാസിയല്ല എന്ന് നിങ്ങൾ പറയരുത്'' (''സലം'' എന്നതിനു പകരം ''സലാം'' എന്ന്) എന്ന സൂക്തം അന്നേരം അവതരിച്ചു. (ബു,ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], 'النساء: ٩٤', null, 575, 575, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 153, 'عَنْ لَقِيطِ بْنِ صَبِرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ وَافِدَ بَنِي الْمُنْتَفِقِ – أَوْ: فِي وَفْدِ بَنِي الْمُنْتَفِقِ – إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَذَكَرَ الْحَدِيثَ، فَقَالَ – يَعْنِي النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ –: {لَا تَحْسِبَنَّ} وَلَمْ يَقُلْ: {لَا تَحْسَبَنَّ}. (د,ت,ن,جه)', 'ലഖീതുബ്നു സ്വബ്റ(റ): റസൂൽ(സ)യുടെ സമീപത്തേക്ക് നിയുക്തനായ ബനുൽ മുൻതഫഖിന്റെ ദൂതൻ - അല്ലെങ്കിൽ, അവരുടെ ദൗത്യസംഘത്തിൽപ്പെട്ടവൻ - ആയിരുന്നു ഞാൻ. എന്നിട്ട് ഹദീസ് പറഞ്ഞു: അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: ''ലാ തഹ്സിബന്ന'' (തീർച്ചയായും താങ്കൾ കരുതേണ്ട). അവിടുന്ന് ''ലാ തഹ്സബന്ന'' എന്ന് (''സീനി''ന്ന് ഫത്ഹാക്കി) പറഞ്ഞില്ല. (ദ,തു,ന,ജ)', 'لَقِيطِ بْنِ صَبِرَةَ', 'ലഖീതുബ്നു സ്വബ്റ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 575, 575, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 154, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْبَخَلِ وَالْهَرَمِ". (ق,د,ن)', 'അനസുബ്നു മാലിക്(റ): നബി(സ)പറഞ്ഞു: "പിശുക്കിൽ നിന്നും വാർധക്യസഹജമായ ബുദ്ധിമുട്ടുകളിൽ നിന്നും അല്ലാഹുവേ, നിന്നോട് ഞാൻ കാവൽ തേടുന്നു." (''ബുഖ്ൽ'' എന്നതിനു പകരം ''ബഖൽ'' എന്ന്) (ബു,മു,ദ,ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 575, 576, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 155, 'عَنْ زَيْدِ بْنِ حَارِثَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقْرَأُ: {غَيْرَ أُولِي الضَّرَرِ} [النساء: ٩٥]. (د)', 'സൈദുബ്നു ഹാരിസ(റ): നബി(സ) ഓതാറുണ്ടായിരുന്നു: ''(ന്യായമായ) വിഷമമില്ലാതെ.'' (''ഗൈറ'' എന്ന പദത്തിൽ റാഇന് ഫത്ഹ് നൽകിക്കൊണ്ട്) (നിസാഅ്: 95). (ദ)', 'زَيْدِ بْنِ حَارِثَةَ', 'സൈദുബ്നു ഹാരിസ(റ)', null, null, array['د']::text[], array['ദ']::text[], 'النساء: ٩٥', null, 576, 576, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 156, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَرَأَ: {أَنَّ النَّفْسَ بِالنَّفْسِ وَالْعَيْنَ بِالْعَيْنِ} [المائدة: ٤٥]. (د,ت)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) ഓതി: (നാം തൗറാത്തിൽ നിയമമായി വെച്ചു) ''ജീവന് പകരം ജീവൻ, കണ്ണിന് പകരം കണ്ണ്.'' (''ഐൻ'' എന്നതിന് ''ഫത്ഹ്'') (മാഇദ: 45). (ദ,തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], 'المائدة: ٤٥', null, 576, 576, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 157, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَرَأَ: {وَكَتَبْنَا عَلَيْهِمْ فِيهَا أَنَّ النَّفْسَ بِالنَّفْسِ وَالْعَيْنُ بِالْعَيْنِ}. (د)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) ഓതി: ''നാം അതിൽ (തൗറാത്തിൽ) നിയമമായി വെച്ചു: ജീവന് പകരം ജീവൻ, കണ്ണിന് പകരം കണ്ണ്.'' (ഇതിൽ ''ഐൻ'' എന്നതിന് ''ഉമ്മ്'' ആണുള്ളത്) (മാഇദ: 45). (ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 576, 576, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 158, 'عَنْ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَرَأَ: {هَلْ تَسْتَطِيعُ رَبَّكَ} [المائدة: ١١٢]. (ت)', 'മുആദുബ്നു ജബൽ(റ): നബി(സ) പാരായണം ചെയ്തു: ''താങ്കൾക്ക് താങ്കളുടെ രക്ഷിതാവിനോട് ചോദിക്കാൻ സാധിക്കുമോ'' (''റബ്ബുക'' എന്നതിനു പകരം ''റബ്ബക'' എന്നും ''യസ്തതവീള'' എന്നതിനു പകരം ''തസ്തതവീള എന്നും''). (മാഇദ: 112). (തു)', 'مُعَاذِ بْنِ جَبَلٍ', 'മുആദുബ്നു ജബൽ(റ)', null, null, array['ت']::text[], array['തു']::text[], 'المائدة: ١١٢', null, 576, 576, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 159, 'عَنْ أُبَيِّ بْنِ كَعْبٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَرَأَ: {بِفَضْلِ اللَّهِ وَبِرَحْمَتِهِ فَبِذَلِكَ فَلْتَفْرَحُوا هُوَ خَيْرٌ مِمَّا تَجْمَعُونَ} [يونس: ٥٨]. (د)', 'ഉബയ്യുബ്നു കഅ്ബ്(റ): നബി(സ) ഓതി: ''അല്ലാഹുവിന്റെ അനുഗ്രഹംകൊണ്ടും കാരുണ്യംകൊണ്ടും ആണത്. അതുകൊണ്ട് നിങ്ങൾ സന്തോഷിച്ചുകൊള്ളുക. അതാണ് നിങ്ങൾ ഒരുമിച്ചു കൂട്ടുന്നതിനേക്കാൾ (ഐഹിക നേട്ടങ്ങളേക്കാൾ) ഉത്തമമായിട്ടുള്ളത്.'' (യൂനുസ്: 58) (''തജ്മഉൗൻ'' എന്നത് ''താ''ഓടെ). (ദ)', 'أُبَيِّ بْنِ كَعْبٍ', 'ഉബയ്യുബ്നു കഅ്ബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], 'يونس: ٥٨', null, 576, 576, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 160, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقْرَؤُهَا: {إِنَّهُ عَمَلٌ غَيْرُ صَالِحٍ} [هود: ٤٦]. (د,ت)', 'ഉമ്മുസലമ(റ): ''നിശ്ചയം അവൻ ശരിയല്ലാത്ത കർമ്മമാണ്'' (ഹുദ്: 46) എന്നായിരുന്നു നബി(സ) ഓതിയിരുന്നത്. (ദ,തു)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], 'هود: ٤٦', null, 576, 577, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 161, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا، وَسُئِلَتْ: كَيْفَ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ هَذِهِ الْآيَةَ: {إِنَّهُ عَمَلٌ غَيْرُ صَالِحٍ} فَقَالَتْ: قَرَأَهَا: {إِنَّهُ عَمِلَ غَيْرَ صَالِحٍ} [هود: ٤٦]. (د,ت)', 'ഉമ്മുസലമ(റ): മഹതിയോട് ചോദിക്കപ്പെട്ടു: ''നിശ്ചയം അവൻ ശരിയല്ലാത്ത ഒരു കർമ്മമാണ്'' എന്ന സൂക്തം റസൂൽ(സ) എങ്ങനെയാണ് ഓതിയിരുന്നത്? മഹതി പറഞ്ഞു: ''നിശ്ചയം അവൻ ശരിയല്ലാത്ത കർമ്മം ചെയ്തു'' (''അമലുൻ ഗൈറു സ്വാലിഹ്'' എന്നിടത്ത് ''അമില ഗൈറ സ്വാലിഹിൻ'') എന്നാണ് അവിടുന്ന് പാരായണം ചെയ്തത്. (ഹൂദ്: 46). (ദ,തു)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], 'هود: ٤٦', null, 577, 577, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 162, 'عَنْ شَقِيقٍ، عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ قَرَأَ: {هَيْتَ لَكَ} [يوسف: ٢٣]. فَقَالَ شَقِيقٌ: إِنَّا نَقْرَؤُهَا: {هِئْتُ لَكَ}. قَالَ ابْنُ مَسْعُودٍ: أَقْرَؤُهَا كَمَا عُلِّمْتُ أَحَبُّ إِلَيَّ. (خ,د)', 'ഇബ്നുമസ്ഊദ്(റ)വിൽനിന്ന് ശഖീഖ്(റ): അദ്ദേഹം ഓതി: ''ഹൈതലക്'' (ഇങ്ങോട്ട് വാ) (യൂസുഫ്: 23) അപ്പോൾ ശഖീഖ്(റ) പറഞ്ഞു: ഞങ്ങളത് ഓതാറുള്ളത്: ''ഹിഅ്തുലക'' എന്നാണ്. ഇബ്നുമസ്ഊദ്(റ) പറഞ്ഞു: എനിക്ക് പഠിപ്പിക്കപ്പെട്ടതുപോലെ ഓതുന്നതാണ് എനിക്ക് ഏറ്റവും ഇഷ്ടപ്പെട്ടത്. (ബു,ദ)', 'شَقِيقٍ، عَنِ ابْنِ مَسْعُودٍ', 'ഇബ്നുമസ്ഊദ്(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], 'يوسف: ٢٣', null, 577, 577, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 163, 'عَنْ شَقِيقٍ قَالَ: قِيلَ لِعَبْدِ اللهِ: إِنَّ أُنَاسًا يَقْرَءُونَ هَذِهِ الْآيَةَ: {وَقَالَتْ هَيْتَ لَكَ} فَقَالَ: إِنِّي أَقْرَأُ كَمَا عُلِّمْتُ أَحَبُّ إِلَيَّ: {وَقَالَتْ هَيْتَ لَكَ}. (د)', 'ശഖീഖ്(റ): അബ്ദുല്ല(റ)വിനോട് പറയപ്പെട്ടു: നിശ്ചയം ചിലയാളുകൾ ഈ സൂക്തം ഓതുന്നത്: ''വഖാലത് ഹീതലക'' (അവൾ പറഞ്ഞു: ഇങ്ങോട്ടു വരിക) എന്നാണ്. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: എനിക്ക് പഠിപ്പിക്കപ്പെട്ടതുപോലെ ഞാൻ ഓതുന്നതാണ് എനിക്ക് ഏറ്റവും ഇഷ്ടപ്പെട്ടത്: ''വഖാലത് ഹൈതലക''. (ദ)', 'شَقِيقٍ قَالَ', 'ശഖീഖ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 577, 577, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 164, 'عَنِ ابْنِ عَبَّاسٍ، عَنْ أُبَيِّ بْنِ كَعْبٍ – رَضِيَ اللهُ عَنْهُمْ – قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا دَعَا بَدَأَ بِنَفْسِهِ، وَقَالَ: "رَحْمَةُ اللهِ عَلَيْنَا وَعَلَى مُوسَى، لَوْ صَبَرَ لَرَأَى مِنْ صَاحِبِهِ الْعَجَبَ، وَلَكِنَّهُ قَالَ: {إِنْ سَأَلْتُكَ عَنْ شَيْءٍ بَعْدَهَا فَلَا تُصَاحِبْنِي قَدْ بَلَغْتَ مِنْ لَدُنِّي} [الكهف: ٧٦]". طَوَّلَهَا حَمْزَةُ. وَفِي رِوَايَةٍ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَرَأَهَا: {قَدْ بَلَغْتَ مِنْ لَدُنِّي} وَثَقَّلَهَا. (د,ت)', 'ഉബയ്യുബ്നു കഅ്ബ്(റ)വിൽ നിന്ന് ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പ്രാർത്ഥിക്കുകയാണെങ്കിൽ സ്വന്തത്തെക്കൊണ്ട് തുടങ്ങുമായിരുന്നു. അവിടുന്ന് പറയും: "നമുക്കും മൂസാ(അ)മിന്നും അല്ലാഹുവിന്റെ അനുഗ്രഹമുണ്ടായിരിക്കട്ടെ, അദ്ദേഹം ക്ഷമ കൈകൊണ്ടിരുന്നുവെങ്കിൽ തന്റെ കൂട്ടുകാരനിൽനിന്ന് അദ്ദേഹത്തിന് ധാരാളം അത്ഭുതങ്ങൾ കാണാമായിരുന്നു. പക്ഷേ, അദ്ദേഹം പറഞ്ഞു: ''അതിനുശേഷം ഞാൻ താങ്കളോട് വല്ലതിനെക്കുറിച്ചും ചോദിച്ചാൽ താങ്കളെന്നെ സഹയാത്രികനാക്കേണ്ട. നിശ്ചയമായും താങ്കൾക്ക് എന്നിൽനിന്ന് (വ്യക്തമായ ഒരു കാരണം) ലഭിച്ചിരിക്കുന്നു.'' (അൽ കഹ്ഫ്: 76)." ഹംസ(റ) അതിനെ (ഖദ് ബലഗ്ത മിൻലദുന്നീ എന്നതിനെ) ദീർഘിപ്പിച്ചു. മറ്റൊരു നിവേദനം: തിരുനബി(സ) ആ സൂക്തം ''ഖദ് ബലഗ്ത മിൻലദുന്നീ'' എന്ന് ഓതുകയും അതിനെ കനപ്പിക്കുകയും ചെയ്തിരിക്കുന്നു. (ദ,തു)', 'ابْنِ عَبَّاسٍ، عَنْ أُبَيِّ بْنِ كَعْبٍ –', 'ഉബയ്യുബ്നു കഅ്ബ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], 'الكهف: ٧٦', null, 577, 577, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=11 and h.hadith_no=164), 1, 'وَفِي رِوَايَةٍ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَرَأَهَا: {قَدْ بَلَغْتَ مِنْ لَدُنِّي} وَثَقَّلَهَا. (د,ت)', 'മറ്റൊരു നിവേദനം: തിരുനബി(സ) ആ സൂക്തം ''ഖദ് ബലഗ്ത മിൻലദുന്നീ'' എന്ന് ഓതുകയും അതിനെ കനപ്പിക്കുകയും ചെയ്തിരിക്കുന്നു. (ദ,തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 165, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أَقْرَأَنِي أُبَيُّ بْنُ كَعْبٍ كَمَا أَقْرَأَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: {فِي عَيْنٍ حَمِئَةٍ} [الكهف: ٨٦] مُخَفَّفَةً. (د,ت)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) ഉബയ്യുബ്നു കഅ്ബ്(റ)വിനെ ഓതിച്ചതുപോലെ അദ്ദേഹം എന്നെ ഓതിച്ചു: ''കറുത്ത മണ്ണുള്ള ഒരു അരുവിയിൽ'' (''ഹമിഅത്'' എന്ന് കനം കുറച്ചുകൊണ്ട്) (അൽകഹ്ഫ്: 86). (ദ,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], 'الكهف: ٨٦', null, 577, 578, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 166, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنْتُ رَدِيفَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ عَلَى حِمَارٍ، وَالشَّمْسُ عِنْدَ غُرُوبِهَا، فَقَالَ: "هَلْ تَدْرِي أَيْنَ تَغْرُبُ هَذِهِ". قُلْتُ: اللَّهُ وَرَسُولُهُ أَعْلَمُ، قَالَ: "فَإِنَّهَا تَغْرُبُ فِي عَيْنٍ حَامِيَةٍ". (ق,د,ت)', 'അബൂദർറ്(റ): റസൂൽ(സ) ഒരു കഴുതപ്പുറത്തിരിക്കവെ ഞാനവിടത്തെ സഹയാത്രികനായിരുന്നു. സൂര്യനാണെങ്കിൽ അസ്തമിക്കാനടുത്തിട്ടുമുണ്ട്. അപ്പോൾ അവിടുന്ന് ചോദിച്ചു: "താങ്കൾക്കറിയുമോ അത് എവിടെയാണ് അസ്തമിക്കുന്നതെന്ന്?" ഞാൻ പറഞ്ഞു: അല്ലാഹുവും അവന്റെ ദൂതരുമാണ് കൂടുതൽ അറിവുള്ളവർ. അവിടുന്ന് പറഞ്ഞു: "ശക്തമായ ചൂടുള്ള ഒരു അരുവിയിലാണ് നിശ്ചയം അത് അസ്തമിക്കുന്നത്." (ഇവിടെ ''ഹാമിയത്'' എന്നാണ് പ്രയോഗിച്ചത്). (ബു,മു,ദ,തു)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 578, 578, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 167, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: حَدَّثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَدِيثًا ذَكَرَ فِيهِ: "جِبْرِيلَ وَمِيكَالَ". فَقَالَ: {جِبْرَائِلُ وَمِيكَائِلُ}. (د)', 'അബൂസഈദിൽ ഖുദ്രി(റ): റസൂൽ(സ) ഒരു ഹദീസ് വിവരിച്ചു. അതിൽ ജിബ്രീലിനെയും മീകാഈലിനെയും പ്രതിപാതിച്ചപ്പോൾ അവിടുന്ന് പറഞ്ഞു. ''ജിബ്റാഇലും മീകാഇലും.'' (ദ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 578, 578, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 168, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: ذَكَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَاحِبَ الصُّورِ فَقَالَ: "عَنْ يَمِينِهِ جِبْرَائِلُ، وَعَنْ يَسَارِهِ مِيكَائِلُ". (د)', 'അബൂസഈദിൽ ഖുദ്രി(റ): റസൂൽ(സ) കാഹളത്തിന്റെയാളെക്കുറിച്ച് പറഞ്ഞു: "ആ മലക്കിന്റെ വലതുഭാഗത്ത് ജിബ്റാഇലും ഇടത്ത് മീകാഇലുമാണ്." (ദ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 578, 578, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 169, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَرَأَ: {وَتَرَى النَّاسَ سُكَارَى وَمَا هُمْ بِسُكَارَى} [الحج: ٢]. (ت)', 'ഇംറാനുബ്നു ഹുസൈൻ(റ): നബി(സ) പാരായണം ചെയ്തു: ''ജനങ്ങളെ മത്ത് പിടിച്ചവരായി താങ്കൾക്ക് കാണുകയും ചെയ്യാം. (യഥാർത്ഥത്തിൽ) അവർ ലഹരി ബാധിച്ചവരല്ല.'' (ഹജ്ജ്: 2) (''സുകാറാ'' എന്നതിനു പകരം ''സക്റാ'' എന്നും വന്നിട്ടുണ്ട്). (തു)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസൈൻ(റ)', null, null, array['ت']::text[], array['തു']::text[], 'الحج: ٢', null, 578, 578, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=57 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 170, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: نَزَلَ الْوَحْيُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَرَأَ عَلَيْنَا: {سُورَةٌ أَنْزَلْنَاهَا وَفَرَضْنَاهَا} [النور: ١] قَالَ أَبُو دَاوُدَ: يَعْنِي مُخَفَّفَةً. (د)', 'ആഇശ(റ): റസൂൽ(സ)ക്ക് വഹ്യ് ഇറങ്ങി. അപ്പോൾ അവിടുന്ന് ഞങ്ങൾക്ക് ഓതിത്തന്നു: ''നാം അവതരിപ്പിക്കുകയും നിർബന്ധമാക്കി വെക്കുകയും ചെയ്തിട്ടുള്ള ഒരദ്ധ്യായമത്രെ ഇത്.'' (നൂർ: 1) അബൂദാവൂദ്(റ) പറഞ്ഞു: അഥവാ (''ഫറള്നാഹാ'' എന്നതിൽ റാഇന്) കനം കുറച്ചുകൊണ്ട്. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], 'النور: ١', null, 578, 578, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 171, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ الرَّجُلَ مِنْ أَهْلِ عِلِّيِّينَ لَيُشْرِفُ عَلَى أَهْلِ الْجَنَّةِ، فَتُضِيءُ الْجَنَّةُ لِوَجْهِهِ كَأَنَّهَا كَوْكَبٌ دُرِّيٌّ". قَالَ: وَهَكَذَا جَاءَ الْحَدِيثُ: "دُرِّيٌّ". مَرْفُوعَةَ الدَّالِ لَا تُهْمَزُ "وَإِنَّ أَبَا بَكْرٍ وَعُمَرَ لَمِنْهُمْ وَأَنْعَمَا". (د,جه)', 'അബൂസഈദുൽ ഖുദ്രി(റ): നബി(സ) പറഞ്ഞു: "നിശ്ചയം ഇല്ലിയ്യീനിലെ (സ്വർഗ്ഗത്തിലെ ഏറ്റവും ഉയർന്ന സ്ഥാനം) ആളുകളിൽപെട്ട ഒരാൾ ഉയരത്തിൽനിന്ന് സ്വർഗ്ഗക്കാരെ നോക്കും. കത്തിജ്വലിക്കുന്ന നക്ഷത്രം പോലെയുള്ള അവന്റെ മുഖം കാരണത്താൽ സ്വർഗ്ഗം പ്രകാശപൂരിതമാകും." നിവേദകൻ പറയുന്നു: ഇപ്രകാരം ''ദാലി''ന് റഫ്അ് ചെയ്തുകൊണ്ട് ''ഹംസ്'' എന്ന അക്ഷരം ഇല്ലാതെ "ദുർരിയ്യ് (നന്നായി പ്രകാശിക്കുന്ന)" എന്നാണ് ഹദീസിലുള്ളത്. "നിശ്ചയം അബൂബക്കറും ഉമറും അവരിൽ പെട്ടവരാണ്. അവർ രണ്ടുപേരും കൂടുതൽ ഗുണമുള്ളവരുമാണ്." (ദ,ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്രി(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 578, 579, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 172, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا كان يوم بدر ظهرت الروم على فارس، فَأَعْجَبَ ذَلِكَ الْمُؤْمِنِينَ، فَنَزَلَتْ: {الم. غُلِبَتِ الرُّومُ} إِلَى قَوْلِهِ {يَفْرَحُ الْمُؤْمِنُونَ} فَفَرِحَ الْمُؤْمِنُونَ بِظُهُورِ الرُّومِ عَلَى فَارِسَ. قَالَ التِّرْمِذِيُّ: يُقْرَأُ: {غُلِبَتْ} وَ{غَلَبَتْ} يَقُولُ: كَانَتْ غُلِبَتْ ثُمَّ غَلَبَتْ، هَكَذَا قَرَأَ نَصْرُ بْنُ عَلِيٍّ: {غَلَبَتْ}. (ت)', 'അബൂസഈദ്(റ): ബദ്റിന്റെ ദിനത്തിൽ റോം പേർഷ്യയെ അതിജയിക്കുകയും അതുകാരണം സത്യവിശ്വാസികൾ അൽഭുതപ്പെടുകയും ചെയ്തു. അപ്പോൾ ''അലിഫ് ലാം മീം, റോം അതിജയിക്കപ്പെട്ടിരിക്കുന്നു'' എന്ന സൂറത്ത് ''സത്യവിശ്വാസികൾ സന്തോഷിക്കും'' എന്നതുവരെ ഇറങ്ങി. അപ്പോൾ റോം പേർഷ്യയുടെ മേൽ അതിജയിച്ചതിൽ സത്യവിശ്വാസികൾ സന്തോഷിച്ചു. തുർമുദി(റ) പറയുന്നു: ''ഗുലിബത്'' (പരാജയപ്പെട്ടു) എന്നും ''ഗലബത്'' (വിജയിച്ചു) എന്നും ഓതാം. അദ്ദേഹം പറയുന്നു: റോം ആദ്യം പരാജയപ്പെടുകയും ശേഷം വിജയിക്കുകയും ചെയ്തു. ഇപ്രകാരം ''ഗലബത്'' എന്നാണ് നസ്റുബ്നു അലി(റ) ഓതിയത്. (തു)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 579, 579, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 173, 'عَنْ عَطِيَّةَ بْنِ سَعْدٍ الْعَوْفِيِّ قَالَ: قَرَأْتُ عَلَى عَبْدِ اللَّهِ بْنِ عُمَرَ: {اللَّهُ الَّذِي خَلَقَكُمْ مِنْ ضَعْفٍ} [الروم: ٥٤] فَقَالَ: {مِنْ ضُعْفٍ} قَرَأْتُهَا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَمَا قَرَأْتَهَا عَلَيَّ، فَأَخَذَ عَلَيَّ كَمَا أَخَذْتُ عَلَيْكَ. (د,ت)', 'അതിയ്യതുബ്നു സഅ്ദിൽ ഔഫീ(റ): ഞാൻ അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)വിന് (പഠനാർത്ഥം) ഓതിക്കേൾപ്പിച്ചു: ''അശക്തതയിൽ നിന്ന് നിങ്ങളെ പടച്ച അല്ലാഹു'' (റൂം: 54) (''മിൻ ളഅ്ഫിൻ'' എന്ന് ''ളാ''ഇന് ഫതഹോടെ). അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ''മിൻ ളുഅ്ഫിൻ'' (''ളാ''ഇന് ഉമ്മോടെ). താങ്കൾ എനിക്ക് ഓതിക്കേൾപ്പിച്ചതു പോലെ ഞാൻ റസൂൽ(സ)ക്ക് ഓതിക്കേൾപ്പിച്ചുകൊടുത്തു. അപ്പോൾ, ഞാൻ താങ്കളെ തടഞ്ഞതുപോലെ അവിടുന്ന് എന്നെ തടഞ്ഞു. (ദ,തു)', 'عَطِيَّةَ بْنِ سَعْدٍ الْعَوْفِيِّ قَالَ', 'അതിയ്യതുബ്നു സഅ്ദിൽ ഔഫീ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], 'الروم: ٥٤', null, 579, 579, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 174, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: {مِنْ ضُعْفٍ}. (ت)', 'അബൂസഈദ്(റ): നബി(സ) ''മിൻ ളുഅ്ഫിൻ'' (ബലഹീനതയിൽ നിന്ന്) എന്ന് (ളാഇന് ഉമ്മോടെ) ഓതി. (തു)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 579, 579, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 175, 'عَنْ فَرْوَةَ بْنِ مُسَيْكٍ الْغُطَيْفِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَذَكَرَ الْحَدِيثَ، فَقَالَ رَجُلٌ مِنَ الْقَوْمِ: يَا رَسُولَ اللَّهِ، أَخْبِرْنَا عَنْ سَبَأٍ، مَا هُوَ؟ أَرْضٌ أَمِ امْرَأَةٌ؟ فَقَالَ: "لَيْسَ بِأَرْضٍ وَلَا امْرَأَةٍ، وَلَكِنَّهُ رَجُلٌ وَلَدَ عَشْرَةً مِنَ الْعَرَبِ، فَتَيَامَنَ سِتَّةٌ وَتَشَاءَمَ أَرْبَعَةٌ". (د,ت)', 'ഫർവതുബ്നു മുസൈകിൽ ഗുതൈഫി(റ): ഞാൻ നബി(സ)യുടെ അടുക്കൽ ചെന്നു. അപ്പോൾ അവിടുന്ന് ഹദീസ് പറഞ്ഞു. ഉടനെ അക്കൂട്ടത്തിലൊരാൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, സബഇനെക്കുറിച്ച് ഞങ്ങൾക്ക് അറിയിച്ചു തന്നാലും, എന്താണത്? ഒരു സ്ഥലമോ, അതോ സ്ത്രീയോ? അവിടുന്ന് പറഞ്ഞു: "അതൊരു സ്ഥലവുമല്ല, സ്ത്രീയുമല്ല. എന്നാൽ അതൊരു വ്യക്തിയാണ്, അയാൾ അറബികളായ പത്ത് കുട്ടികൾക്ക് ജന്മം നൽകി. അവരിൽ ആറുപേർ യമനിന്റെ ഭാഗത്തേക്കും നാലുപേർ ശാമിന്റെ (സിരിയയുടെ) ഭാഗത്തേക്കും പോയി." (ദ,തു)', 'فَرْوَةَ بْنِ مُسَيْكٍ الْغُطَيْفِيِّ', 'ഫർവതുബ്നു മുസൈകിൽ ഗുതൈഫി(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 579, 580, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 176, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَذَكَرَ حَدِيثَ الْوَحْيِ، قَالَ: "فَذَلِكَ قَوْلُهُ تَعَالَى: {حَتَّى إِذَا فُزِّعَ عَنْ قُلُوبِهِمْ} [سبأ: ٢٣]". (خ,د,ت,جه)', 'അബൂഹുറൈറ(റ) നബി(സ)യിൽ നിന്ന്: അവിടുന്ന് ദിവ്യബോധനത്തെക്കുറിച്ച് സംസാരിച്ചുകൊണ്ട് ഇപ്രകാരം പറഞ്ഞു: "അതിനെക്കുറിച്ചാണ് അല്ലാഹുവിന്റെ ഈ വചനം: ''അങ്ങനെ അവരുടെ ഹൃദയങ്ങളിൽ നിന്ന് ഭയം അകറ്റപ്പെടുമ്പോൾ'' (സബഅ്: 23)." (''ഫുസ്സിഅ'' എന്നും ''ഫസഅ'' എന്നുമുണ്ട്). (ബു,ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','د','ت','جه']::text[], array['ബു','ദ','തു','ജ']::text[], 'سبأ: ٢٣', null, 580, 580, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 177, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا، زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَتْ: قِرَاءَةُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: {بَلَى قَدْ جَاءَتْكِ آيَاتِي فَكَذَّبْتِ بِهَا وَاسْتَكْبَرْتِ وَكُنْتِ مِنَ الْكَافِرِينَ} [الزمر: ٥٩]. (د)', 'പ്രവാചക പത്നി ഉമ്മുസലമ(റ): മഹതി പറഞ്ഞു: നബി(സ)യുടെ പാരായണം ഇപ്രകാരമാണ്: ''അതെ, തീർച്ചയായും എന്റെ ദൃഷ്ടാന്തങ്ങൾ നിനക്കെത്തുകയുണ്ടായി. അപ്പോൾ നീ അവയെ നിഷേധിച്ച് തള്ളുകയും അഹങ്കരിക്കുകയും സത്യനിഷേധികളുടെ കൂട്ടത്തിലാവുകയും ചെയ്തു.'' (അഭിസംബോധന സ്ത്രീയോടാക്കിക്കൊണ്ട്) (സുമർ: 59). (ദ)', 'أُمِّ سَلَمَةَ', 'പ്രവാചക പത്നി ഉമ്മുസലമ(റ)', null, null, array['د']::text[], array['ദ']::text[], 'الزمر: ٥٩', null, 580, 580, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 178, 'عَنْ يَعْلَى رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى الْمِنْبَرِ يَقْرَأُ: {وَنَادَوْا يَا مَالِكُ} [الزخرف: ٧٧]. (ق,د,ت)', 'യഅ്ലാ(റ): മിമ്പറിൽവെച്ച് നബി(സ) ഓതുന്നത് ഞാൻ കേട്ടു: ''അവർ വിളിക്കും, ഓ മാലിക്.'' (സുഖ്റുഫ്: 77). (ബു,മു,ദ,തു)', 'يَعْلَى', 'യഅ്ലാ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], 'الزخرف: ٧٧', null, 580, 580, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 179, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أَقْرَأَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ {إِنِّي أَنَا هُوَ الرَّزَّاقُ ذُو الْقُوَّةِ الْمَتِينُ} [الذاريات: ٥٨]. (د,ت,ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) എന്നെ ഓതിച്ചു: ''നിശ്ചയം ഞാൻ തന്നെയാണ് ഏറ്റവും കൂടുതൽ നൽകുന്ന ഉറച്ച ശക്തിയുള്ളവൻ'' എന്ന്. (''ഹുവ'' എന്ന് അധികരിപ്പിച്ചു). (ദാരിയാത്: 58) (ദ,തു,ന)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], 'الذاريات: ٥٨', null, 580, 581, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 180, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَقْرَأَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: {إِنِّي أَنَا الرَّزَّاقُ ذُو الْقُوَّةِ الْمَتِينُ} [الذاريات: ٥٨]. (د,ت)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ''നിശ്ചയം ഞാൻ കൂടുതൽ നൽകുന്നവനും ശക്തനും കഴിവുള്ളവനുമാണ്'' (''ഹുവ'' എന്നില്ലാതെ) (അദ്ദാരിയാത്ത്: 58) എന്ന സൂക്തം റസൂൽ(സ) എന്നെ ഓതിക്കേൾപ്പിച്ചു. (ദ,തു)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], 'الذاريات: ٥٨', null, 581, 581, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 181, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقْرَؤُهَا: {فَهَلْ مِنْ مُدَّكِرٍ} [القمر: ٢٢] يَعْنِي: مُثَقَّلًا. (د,ت)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നബി(സ) ഇപ്രകാരമാണ് ഓതിയിരുന്നത്: ''എന്നാൽ ചിന്തിച്ച് മനസ്സിലാക്കുന്നവർ ആരെങ്കിലുമുണ്ടോ.'' അഥവാ (''മുദ്ദകിർ'' എന്ന് ദാലിന്) കനം കൂട്ടിക്കൊണ്ട്. (അൽഖമർ: 22) (ദ,തു)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], 'القمر: ٢٢', null, 581, 581, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 182, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْرَؤُهَا: {فَرُوحٌ وَرَيْحَانٌ} [الواقعة: ٨٩]. (د,ت)', 'ആഇശ(റ): നബി(സ) ''(അവന്) റൂഹും (ആത്മാവ്) വിശിഷ്ടമായ ഉപജീവനവും ഉണ്ടായിരിക്കും'' (റൗഹ് (ആശ്വാസം) എന്നതിനെ റൂഹ് (ആത്മാവ്) എന്ന് ഓതി) (വാഖിഅ: 89). (ദ,തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], 'الواقعة: ٨٩', null, 581, 581, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 183, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقْرَأُ: {فَرُوحٌ وَرَيْحَانٌ وَجَنَّةُ نَعِيمٍ} [الواقعة: ٨٩]. (د,ت,ن)', 'ആഇശ(റ): നബി(സ) ഓതുമായിരുന്നു: ''(അവന്) റൂഹും വിശിഷ്ടമായ ഉപജീവനവും സുഖാനുഭൂതിയുടെ സ്വർഗ്ഗത്തോപ്പും ഉണ്ടായിരിക്കും.'' (വാഖിഅ: 89). (ദ,തു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], 'الواقعة: ٨٩', null, 581, 581, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 184, 'عَنْ أَبِي قِلَابَةَ، عَمَّنْ أَقْرَأَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: {فَيَوْمَئِذٍ لَا يُعَذَّبُ عَذَابَهُ أَحَدٌ وَلَا يُوثَقُ وَثَاقَهُ أَحَدٌ} [الفجر: ٢٥, ٢٦].
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=11 and h.hadith_no=184), 1, 'وَفِي رِوَايَةٍ: أَنْبَأَنِي مَنْ أَقْرَأَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَوْ: مَنْ أَقْرَأَهُ مَنْ أَقْرَأَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: {فَيَوْمَئِذٍ لَا يُعَذَّبُ}. (د)', 'മറ്റൊരു നിവേദനം: നബി(സ) ഓതിക്കൊടുത്ത ഒരാൾ, അല്ലെങ്കിൽ: നബി(സ) ഓതിക്കൊടുത്തയാൾ ഓതിക്കൊടുത്ത മറ്റൊരാൾ എന്നോട് പറഞ്ഞു: ''അപ്പോൾ ആ ദിവസം (അവൻ ശിക്ഷിക്കപ്പെടുന്ന പ്രകാരം) ഒരാളും ശിക്ഷിക്കപ്പെടുകയില്ല.'' (''യുഅദ്ദിബു'' എന്നതിനു പകരം ''യുഅദ്ദബു'' എന്ന്). (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 185, 'عَنْ عَلْقَمَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قدمنا الشَّامَ، فَأَتَانَا أَبُو الدَّرْدَاءِ رَضِيَ اللهُ عَنْهُ فَقَالَ: أفيكم أَحَدٌ يَقْرَأُ عَلَيَّ قراءة عَبْدِ اللهِ؟ قَالَ: فَأَشَارُوا إِلَيَّ، فَقُلْتُ: نَعَمْ، قَالَ: كَيْفَ سمعت عَبْدَ اللهِ يَقْرَأُ هَذِهِ الْآيَةَ: {وَاللَّيْلِ إِذَا يَغْشَى}. قَالَ: قُلْتُ: سَمِعْتُهُ يَقْرَؤُهَا: {وَاللَّيْلِ إِذَا يَغْشَى. وَالذَّكَرِ وَالْأُنْثَى} فَقَالَ أَبُو الدَّرْدَاءِ: وَأَنَا وَاللهِ هَكَذَا سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَقْرَؤُهَا، وَهَؤُلَاءِ يُرِيدُونَنِي أَنْ أَقْرَأَهَا: {وَمَا خَلَقَ} فَلَا أُتَابِعُهُمْ. (ق,ت)', 'അൽഖമ(റ): ഞങ്ങൾ ശാമിലെത്തി. അപ്പോൾ അബുദ്ദർദാഅ്(റ) ഞങ്ങളുടെ അടുക്കൽ വന്ന് ചോദിച്ചു: അബ്ദുല്ല(റ)വിന്റെ പാരായണ ശൈലി എനിക്ക് ഓതിക്കേൾപിക്കാൻ പറ്റിയ ആരെങ്കിലും നിങ്ങളിലുണ്ടോ? അദ്ദേഹം പറയുന്നു: അപ്പോൾ അവർ എന്നെ ചൂണ്ടിക്കാണിച്ചു. അന്നേരം ഞാൻ പറഞ്ഞു: അതെ. അദ്ദേഹം ചോദിച്ചു: ''രാത്രി തന്നെ സത്യം, അത് (ആകെ) മൂടിയാൽ'' എന്ന സൂക്തം അബ്ദുല്ല(റ) എങ്ങനെ ഓതുന്നതായാണ് താങ്കൾ ശ്രവിച്ചത്? അദ്ദേഹം പറയുന്നു: ഞാൻ പറഞ്ഞു: ''രാത്രിയെത്തന്നെയാണ് സത്യം, അത് (ആകെ) മൂടിയാൽ. ആൺ തന്നെയാണ് സത്യം, സ്ത്രീ തന്നെയും.'' എന്ന് ഓതുന്നതായാണ് ഞാൻ കേട്ടത്. അബുദ്ദർദാഅ്(റ) പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം, ഞാൻ റസൂൽ(സ) ഇപ്രകാരം ഓതുന്നതായിത്തന്നെയാണ് കേട്ടത്, എന്നാൽ അതിനെ ''വമാ ഖലഖ'' (സൃഷ്ടിച്ചതിനെത്തന്നെയാണ് സത്യം) എന്ന് ഞാൻ ഓതണമെന്നാണ് ഇക്കൂട്ടർ ആഗ്രഹിക്കുന്നത്. എന്നാൽ ഞാനവരോട് യോജിക്കുന്നുമില്ല. (ബു,മു,തു)', 'عَلْقَمَةَ', 'അൽഖമ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 582, 582, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 186, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ: {يَحْسِبُ أَنَّ مَالَهُ أَخْلَدَهُ} [الهمزة: ٣]. (د)', 'ജാബിർ(റ): നബി(സ) ഓതുന്നത് ഞാൻ കണ്ടു: ''അവന്റെ ധനം അവന് ശാശ്വത ജീവിതം നൽകിയിരിക്കുന്നവെന്ന് അവൻ വിചാരിക്കുന്നു.'' (ഹുമസ: 3) (''യഹ്സബു'' എന്നതിനു പകരം ''യഹ്സിബു'' എന്ന്). (ദ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['د']::text[], array['ദ']::text[], 'الهمزة: ٣', null, 582, 582, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=4 and b.book_no=11 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
